using System;
using System.Collections.Generic;

public class HttpStatusCodes
{
    private Dictionary<int, string> statusTable = new Dictionary<int, string>();

    public HttpStatusCodes()
    {
        // Initialize the status table with default HTTP status codes and phrases
        statusTable.Add(200, "OK");
        statusTable.Add(404, "Not Found");
        statusTable.Add(500, "Internal Server Error");
    }

    public string GetPhrase(int code)
    {
        if (statusTable.ContainsKey(code))
        {
            return statusTable[code];
        }
        else
        {
            return "Unknown";
        }
    }

    public void AddStatusCode(int code, string phrase)
    {
        if (!statusTable.ContainsKey(code))
        {
            statusTable.Add(code, phrase);
        }
        else
        {
            // Handle the case where the code already exists in the table
            Console.WriteLine($"Status code {code} already exists in the table.");
        }
    }

    public static void Main()
    {
        HttpStatusCodes table = new HttpStatusCodes();

        // Retrieve phrases for existing status codes
        Console.WriteLine("Phrase for status code 200: " + table.GetPhrase(200));
        Console.WriteLine("Phrase for status code 404: " + table.GetPhrase(404));

        // Add a new status code and phrase
        table.AddStatusCode(201, "Created");

        // Retrieve phrase for the newly added status code
        Console.WriteLine("Phrase for status code 201: " + table.GetPhrase(201));

        // Try to retrieve phrase for a non-existing status code
        Console.WriteLine("Phrase for status code 403: " + table.GetPhrase(403));
    }
}
