class AppointmentManager:
    def __init__(self):
        self.appointments = []

    def add_appointment(self, date, time, patient_name):
        self.appointments.append((date, time, patient_name))

    def remove_appointment(self, date, time):
        self.appointments = [app for app in self.appointments if (app[0], app[1]) != (date, time)]

    def reschedule_appointment(self, current_date, current_time, new_date, new_time):
        for i, app in enumerate(self.appointments):
            if (app[0], app[1]) == (current_date, current_time):
                self.appointments[i] = (new_date, new_time, app[2])

    def get_schedule(self, date):
        return [(app[1], app[2]) for app in self.appointments if app[0] == date]
