public function parseUrl($requestUri) {
    try {
        $baseUri = self::$base_uri;
        $regExp = '/^' . preg_quote($baseUri, '/') . '[\/]?([^\?]*)(\?.*)?$/i';
        $matches = [];

        if (preg_match($regExp, $requestUri, $matches)) {
            $path = $matches[1];
            $query = isset($matches[2]) ? ltrim($matches[2], '?') : '';
            return ['path' => $path, 'query' => $query];
        } else {
            throw new Exception('Invalid URL format');
        }
    } catch (Exception $e) {
        // Handle the exception, log the error, and return a default value or re-throw the exception as needed
        // Example: logError($e->getMessage());
        return ['path' => '', 'query' => ''];
    }
}
```

