use std::fs;
use std::io;

fn process_transactions(path: &str, description: &str) -> Result<f64, io::Error> {
    if let Ok(content) = std::fs::read_to_string(path) {
        let mut total_amount = 0.0;
        for line in content.lines() {
            let parts: Vec<&str> = line.split(',').collect();
            if parts.len() == 3 {
                let timestamp = parts[0].parse::<i64>();
                let amount = parts[1].parse::<f64>();
                let desc = parts[2];
                if let (Ok(timestamp), Ok(amount)) = (timestamp, amount) {
                    if desc == description {
                        total_amount += amount;
                    }
                }
            }
        }
        Ok(total_amount)
    } else {
        Err(io::Error::new(io::ErrorKind::NotFound, "File not found"))
    }
}
```

