class DependencyContainer:
    _instance = None

    @classmethod
    def Instance(cls):
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def __init__(self):
        self._registry = {}

    def register(self, class_type, factory_function):
        self._registry[class_type] = factory_function

    def get(self, class_type):
        if class_type in self._registry:
            return self._registry[class_type]()
        else:
            raise Exception(f"Class {class_type.__name__} not registered in the container")

class Dispatcher:
    def dispatch(self, command):
        print(f"Dispatching command: {command}")

def command():
    return "Sample command"

# Testing the dependency injection container
DependencyContainer.Instance().register(Dispatcher, lambda: Dispatcher())
DependencyContainer.Instance().get(Dispatcher).dispatch(command())
```

