public float ExtractNumericValue(string input)
{
    string prefix = "";
    float value;
    if (float.TryParse(input, out value))
    {
        return value;
    }
    else
    {
        // Check for prefix and extract numerical value
        int index = 0;
        foreach (char c in input)
        {
            if (char.IsLetter(c))
            {
                prefix += c;
                index++;
            }
            else
            {
                break;
            }
        }
        if (float.TryParse(input.Substring(index), out value))
        {
            return value;
        }
        else
        {
            return 0;
        }
    }
}
