class BankingSystem:
    def __init__(self):
        self.accounts = {}
        self.account_counter = 1000

    def create_account(self, name: str, initial_balance: float) -> str:
        if name and initial_balance >= 0:
            account_number = f"ACC-{self.account_counter:04d}"
            self.accounts[account_number] = initial_balance
            self.account_counter += 1
            return account_number
        else:
            raise ValueError("Invalid account details")

    def deposit(self, account_number: str, amount: float) -> bool:
        if account_number in self.accounts and amount >= 0:
            self.accounts[account_number] += amount
            return True
        else:
            return False

    def withdraw(self, account_number: str, amount: float) -> Union[bool, str]:
        if account_number in self.accounts and amount >= 0:
            if self.accounts[account_number] >= amount:
                self.accounts[account_number] -= amount
                return True
            else:
                return "Insufficient funds"
        else:
            return False

    def check_balance(self, account_number: str) -> Union[float, str]:
        if account_number in self.accounts:
            return self.accounts[account_number]
        else:
            return "Invalid account number"
