        tasks: Vec<Task>,
    }

    impl TaskQueue {
        pub fn new() -> TaskQueue {
            TaskQueue { tasks: Vec::new() }
        }

        pub fn add_task(&mut self, id: u64, task_fn: Box<dyn Fn() -> u64>) {
            let task = Task { id, task_fn };
            self.tasks.push(task);
        }

        pub fn execute_task(&mut self) -> Option<u64> {
            if let Some(task) = self.tasks.first() {
