                self.tasks.remove(0);
                Some(result)
            } else {
                None
            }
        }

        pub fn get_result(&self) -> Option<u64> {
            if let Some(task) = self.tasks.last() {
                Some((task.task_fn)())
            } else {
                None
            }
        }
    }
}
