      xhr.setRequestHeader(key, headers[key]);
    }
    xhr.onload = function () {
      if (xhr.status >= 200 && xhr.status < 300) {
        resolve(JSON.parse(xhr.responseText));
      } else {
        reject(xhr.statusText);
      }
    };
    xhr.onerror = function () {
      reject(xhr.statusText);
    };
    xhr.send(JSON.stringify(data));
  });
}
```

This solution creates a new Promise and uses XMLHttpRequest to make the asynchronous HTTP request. It sets the request headers, sends the request data, and resolves or rejects the Promise based on the response from the server.

