import java.util.Stack;

public int countValidSubarrays(int[] nums) {
    int ans = 0;
    Stack<Integer> stack = new Stack<>();

    for (int num : nums) {
        while (!stack.isEmpty() && stack.peek() > num)
            stack.pop();

        stack.push(num);
        ans += stack.size();
    }

    return ans;
}
```

