import smore.apispec.core

class APISpec:
    def __init__(self):
        self._definition_helpers = []
        self._path_helpers = []

    def register_definition_helper(self, func):
        """
        Register a new definition helper. The helper **must** meet the following conditions:
        - Include ``**kwargs`` in signature.
        - Return a `smore.apispec.core.Definition` object.
        """
        if 'kwargs' in func.__code__.co_varnames:
            definition = func(**{})
            if isinstance(definition, smore.apispec.core.Definition):
                self._definition_helpers.append(func)
            else:
                raise ValueError("Definition helper must return a smore.apispec.core.Definition object")
        else:
            raise ValueError("Definition helper must include **kwargs in its signature")

    def register_path_helper(self, func):
        """
        Register a new path helper. The helper **must** meet the following conditions:
        - Include ``**kwargs`` in signature.
        - Return a `smore.apispec.core.Path` object.
        """
        if 'kwargs' in func.__code__.co_varnames:
            path = func(**{})
            if isinstance(path, smore.apispec.core.Path):
                self._path_helpers.append(func)
            else:
                raise ValueError("Path helper must return a smore.apispec.core.Path object")
        else:
            raise ValueError("Path helper must include **kwargs in its signature")

    def get_definition_helpers(self):
        return self._definition_helpers

    def get_path_helpers(self):
