function resolveModulePath(importingModulePath, importedModulePath) {
  if (importedModulePath.startsWith('./')) {
    const importingDir = importingModulePath.substring(0, importingModulePath.lastIndexOf('/') + 1);
    return importingDir + importedModulePath.substring(2) + '.js';
  } else if (importedModulePath.startsWith('../')) {
    const parentDir = importingModulePath.substring(0, importingModulePath.lastIndexOf('/', importingModulePath.lastIndexOf('/') - 1) + 1);
    return parentDir + importedModulePath.substring(3) + '.js';
  } else {
    return '/' + importedModulePath + '.js';
  }
}
```

