use std::sync::atomic::{AtomicI64, Ordering};

pub struct Counter(AtomicI64);

impl Counter {
    pub fn new() -> Self {
        Counter(AtomicI64::new(0))
    }

    pub fn add(&self, value: i64) {
        self.0.fetch_add(value, Ordering::Relaxed);
    }

