class PriorityQueue:
    def __init__(self):
        self.tasks = []

    def enqueue(self, task):
        # Add a task to the priority queue based on its priority
        self.tasks.append(task)
        self.tasks.sort(key=lambda t: t.queue.priority)  # Assuming Task.queue has a 'priority' attribute

    def dequeue(self):
        # Remove and return the highest priority task from the priority queue
        if self.tasks:
            return self.tasks.pop(0)
        else:
            return None

    def size(self):
        # Return the current size of the priority queue
        return len(self.tasks)
