import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.util.concurrent.atomic.AtomicLong;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.TYPE)
@interface JoinAnnotation {}

class JoinAnnotationBeanNameGenerator {
    private static final AtomicLong timestamp = new AtomicLong(System.currentTimeMillis());

    public static String generateBeanName(Class<?> clazz) {
        if (clazz.isAnnotationPresent(JoinAnnotation.class)) {
            return clazz.getSimpleName() + "_" + timestamp.getAndIncrement();
        } else {
            return "NoJoinAnnotation_" + timestamp.getAndIncrement();
        }
    }
}
