from typing import Union, Any
from importlib import import_module

def execute_dynamic_function(module_name: str, function_name: str) -> Union[str, Any]:
    try:
        module = import_module(module_name)
    except ModuleNotFoundError:
        return f"Module '{module_name}' not found."
    except Exception as e:
        return f"Error occurred while importing module '{module_name}': {str(e)}"

    try:
        dynamic_function = getattr(module, function_name)
    except AttributeError:
        return f"Function '{function_name}' not found in module '{module_name}'."
    except Exception as e:
        return f"Error occurred while retrieving function '{function_name}' from module '{module_name}': {str(e)}"

    try:
        result = dynamic_function()
        return result
    except Exception as e:
        return f"Error occurred while executing function '{function_name}' from module '{module_name}': {str(e)}"

