using System;
using System.Net;
using System.Net.Sockets;

namespace TubumuMeeting.Libuv
{
    public class TcpConnector : IConnectable<Socket, IPEndPoint>
    {
        public void Connect(IPEndPoint endPoint, Action<Exception> callback)
        {
            try
            {
                Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
                socket.BeginConnect(endPoint, ar =>
                {
                    try
                    {
                        socket.EndConnect(ar);
                        callback(null); // No exception, connection successful
                    }
                    catch (Exception ex)
                    {
                        callback(ex); // Pass any encountered exception to the callback
                    }
                    finally
                    {
                        socket.Dispose(); // Ensure socket is properly disposed
                    }
                }, null);
            }
            catch (Exception ex)
            {
                callback(ex); // Pass any encountered exception to the callback
            }
        }
    }
}
```

