class Dispatcher:
    def __init__(self):
        self.handlers = {}

    def dispatch(self, on):
        def register_handler(func):
            self.handlers[on] = func
            return func
        return register_handler

    def __call__(self, *args):
        if len(args) == 1:
            if args[0] in self.handlers:
                self.handlers[args[0]]()
            else:
                print(args[0])
        elif len(args) == 2:
            if args[0] in self.handlers:
                self.handlers[args[0]](*args[1])
            else:
                print(args[0] * args[1])

foo = Dispatcher()

@foo.dispatch(on=5)
def multiply(bar: int, baz: int):
    print(bar * baz)

@foo.dispatch(on=10)
def negate():
    print(-10)

foo(1)  # Output: 1
foo(5, 10)  # Output: 50
```

