import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.util.HashMap;
import java.util.Map;

class BankAccount {
    private static int nextAccountNumber = 1001;
    private int accountNumber;
    private String accountHolderName;
    private double balance;

    public BankAccount(String accountHolderName, double initialBalance) {
        this.accountNumber = nextAccountNumber++;
        this.accountHolderName = accountHolderName;
        this.balance = initialBalance;
    }

    public void deposit(double amount) {
        balance += amount;
    }

    public boolean withdraw(double amount) {
        if (balance >= amount) {
            balance -= amount;
            return true;
        }
        return false;
    }

    public double getBalance() {
        return balance;
    }

    public String getAccountInfo() {
        return "Account Number: " + accountNumber + "\nAccount Holder: " + accountHolderName + "\nBalance: $" + balance;
    }
}

public class Main {
    private static Map<Integer, BankAccount> accounts = new HashMap<>();
    private static JTextArea outputArea;

    public static void main(String[] args) {
        JFrame frame = new JFrame("Banking System");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        JPanel panel = new JPanel();
        panel.setLayout(new GridLayout(5, 2));

        JLabel nameLabel = new JLabel("Account Holder Name:");
        JTextField nameField = new JTextField();
        JLabel balanceLabel = new JLabel("Initial Balance:");
        JTextField balanceField = new JTextField();
        JButton createButton = new JButton("Create Account");
        JLabel depositLabel = new JLabel("Deposit Amount:");
        JTextField depositField = new JTextField();
        JButton depositButton = new JButton("Deposit");
        JLabel withdrawLabel = new JLabel("Withdraw Amount:");
        JTextField withdrawField = new JTextField();
        JButton withdrawButton = new JButton("Withdraw");
        JButton balanceButton = new JButton("Check Balance");

        outputArea = new JTextArea(10, 30);
        outputArea.setEditable(false);

        panel.add(nameLabel);
        panel.add(nameField);
        panel.add(balanceLabel);
        panel.add(balanceField);
        panel.add(createButton);
        panel.add(new JLabel());
        panel.add(depositLabel);
        panel.add(depositField);
        panel.add(depositButton);
        panel.add(new JLabel());
        panel.add(withdrawLabel);
        panel.add(withdrawField);
        panel.add(withdrawButton);
        panel.add(new JLabel());
        panel.add(balanceButton);
        panel.add(new JLabel());
        panel.add(outputArea);

        createButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                String name = nameField.getText();
                double balance = Double.parseDouble(balanceField.getText());
                BankAccount account = new BankAccount(name, balance);
                accounts.put(account.getAccountNumber(), account);
                outputArea.setText("Account created successfully.\n" + account.getAccountInfo());
            }
        });

        depositButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                int accountNumber = Integer.parseInt(JOptionPane.showInputDialog("Enter account number:"));
                double amount = Double.parseDouble(depositField.getText());
                BankAccount account = accounts.get(accountNumber);
                if (account != null) {
                    account.deposit(amount);
                    outputArea.setText("Deposit successful.\n" + account.getAccountInfo());
                } else {
                    outputArea.setText("Account not found.");
                }
            }
        });

        withdrawButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                int accountNumber = Integer.parseInt(JOptionPane.showInputDialog("Enter account number:"));
                double amount = Double.parseDouble(withdrawField.getText());
                BankAccount account = accounts.get(accountNumber);
                if (account != null) {
                    if (account.withdraw(amount)) {
                        outputArea.setText("Withdrawal successful.\n" + account.getAccountInfo());
                    } else {
                        outputArea.setText("Insufficient funds.");
                    }
                } else {
                    outputArea.setText("Account not found.");
                }
            }
        });

        balanceButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                int accountNumber = Integer.parseInt(JOptionPane.showInputDialog("Enter account number:"));
                BankAccount account = accounts.get(accountNumber);
                if (account != null) {
                    outputArea.setText(account.getAccountInfo());
                } else {
                    outputArea.setText("Account not found.");
                }
            }
        });

        frame.add(panel);
        frame.pack();
        frame.setVisible(true);
    }
}
