void Libfreenect2OpenCV::updateMat()
{
    // Acquire frames from the Kinect sensor
    libfreenect2::FrameMap frames;
    if (!m_dev->waitForNewFrame(frames, 10 * 1000)) {  // Wait for new frames with a timeout of 10 seconds
        std::cerr << "Timeout waiting for new frames" << std::endl;
        return;
    }

    // Process the acquired frames
