    libfreenect2::Frame* irFrame = frames[libfreenect2::Frame::Ir];
    libfreenect2::Frame* depthFrame = frames[libfreenect2::Frame::Depth];

    // Convert the frames to OpenCV matrices
    cv::Mat rgbMat(rgbFrame->height, rgbFrame->width, CV_8UC4, rgbFrame->data);
    cv::Mat irMat(irFrame->height, irFrame->width, CV_32FC1, irFrame->data);
    cv::Mat depthMat(depthFrame->height, depthFrame->width, CV_32FC1, depthFrame->data);

    // Perform further processing or visualization using the acquired matrices
    // Example: Display the RGB image
    cv::imshow("RGB Image", rgbMat);
    cv::waitKey(1);  // Wait for a short duration to update the display

    // Release the frames to free the memory
    m_dev->release(frames);
}
