    private Vector2 _goal;
    private Vector2 _velocity;
    private float _damper;

    public PhysicsSimulation(Vector2 goal, Vector2 velocity, float damper)
    {
        _goal = goal;
        _velocity = velocity;
        _damper = damper;
    }

    public Vector2 CalculateNextPosition(Vector2 currentPosition)
    {
        Vector2 newVelocity = _velocity + (_goal - currentPosition) * _damper;
        Vector2 newPosition = currentPosition + newVelocity;
        return newPosition;
    }
}
