```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Task
{
    public int Id { get; set; }
    public int Priority { get; set; }
    public int Status { get; set; }
}

public class TaskScheduler
{
    private List<Task> tasks;

    public TaskScheduler()
    {
        tasks = new List<Task>();
    }

    public void AddTask(Task task)
    {
        tasks.Add(task);
    }

    public void RemoveTask(int taskId)
    {
        Task taskToRemove = tasks.FirstOrDefault(t => t.Id == taskId);
        if (taskToRemove != null)
        {
            tasks.Remove(taskToRemove);
        }
    }

    public void ExecuteNextTask()
    {
        Task nextTask = tasks.Where(t => t.Status == 1).OrderByDescending(t => t.Priority).ThenBy(t => t.Id).FirstOrDefault();
        if (nextTask != null)
        {
            Console.WriteLine($"Executing task {nextTask.Id} with priority {nextTask.Priority}");
        }
        else
        {
            Console.WriteLine("No active tasks to execute");
        }
    }

    public void PauseTask(int taskId)
    {
        Task taskToPause = tasks.FirstOrDefault(t => t.Id == taskId);
        if (taskToPause != null)
        {
            taskToPause.Status = 0;
        }
    }

    public void ResumeTask(int taskId)
    {
        Task taskToResume = tasks.FirstOrDefault(t => t.Id == taskId);
        if (taskToResume != null)
        {
            taskToResume.Status = 1;
        }
    }
}
