    // Assuming the ASS file content is read and stored in a variable named 'assFileContent'

    // Split the file content by sections
    let sections = assFileContent.components(separatedBy: "[")

    // Find the [Events] section
    guard let eventsSection = sections.first(where: { $0.hasPrefix("Events]") }) else {
        return 0 // Return 0 if [Events] section is not found
