function distributeWidth(colStyles, totalWidth) {
    let totalMinWidth = 0;
    for (let col of colStyles) {
        totalMinWidth += col.MinWidth;
    }

    if (totalWidth >= totalMinWidth) {
        let remainingWidth = totalWidth - totalMinWidth;
        colStyles.forEach((col, index) => {
            if (index === colStyles.length - 1) {
                col.Width = Math.max(col.MinWidth, col.Width + remainingWidth);
            } else {
                let allocatedWidth = Math.max(col.MinWidth, Math.floor(col.Width / totalMinWidth * totalWidth));
                col.Width = allocatedWidth;
                remainingWidth -= (allocatedWidth - col.MinWidth);
                totalMinWidth -= col.MinWidth;
            }
        });
