        for time_str in self.time_data:
            h, m, s = map(int, time_str.split(':'))
            total_seconds += h * 3600 + m * 60 + s
        average_seconds = total_seconds // len(self.time_data)
        average_time = '{:02d}:{:02d}:{:02d}'.format(average_seconds // 3600, (average_seconds // 60) % 60, average_seconds % 60)
