```javascript
class FamilyTree {
  constructor() {
    this.members = new Map();
  }

  addFamilyMember(memberId, parentId) {
    this.members.set(memberId, { id: memberId, parent: parentId });
  }

  getFamilyMember(memberId) {
    return this.members.get(memberId);
  }

  isDescendant(childId, parentId) {
    let currentId = childId;
    while (currentId !== null) {
      const member = this.members.get(currentId);
      if (member.parent === parentId) {
        return true;
      }
      currentId = member.parent;
    }
    return false;
  }
}
```

