fn search_case_insensitive(query: &str, content: &str) -> Vec<&str> {
    let query_lower = query.to_lowercase();
    let content_lower = content.to_lowercase();
    let mut matches = Vec::new();
    let mut start_index = 0;

    while let Some(index) = content_lower[start_index..].find(&query_lower) {
        let actual_index = index + start_index;
        matches.push(&content[actual_index..(actual_index + query.len())]);
        start_index = actual_index + query.len();
    }

    matches
}

fn main() {
    let query = "end";
    let content = "This is not the end. This is just the beginning. The end is near.";
    assert_eq!(
        vec!["This is not the end.", "The end is near."],
        search_case_insensitive(query, content)
    );
}
