// Define the to function
func to<T1, T2, Argument, Output>(elementFactory: @escaping (T1, T2, Argument) -> Output) -> (Provider<T1>, Provider<T2>) -> Element<Argument, Output> {
    return { provider1, provider2 in
        return Element { argument in
            elementFactory(provider1.get(), provider2.get(), argument)
        }
    }
}

