use std::fs::{self, DirEntry};
use std::path::Path;

struct FileInfo {
    path: String,
    size: u64,
    modified_time: i64,
}

fn process_directory(path: &Path, file_info: &mut Vec<FileInfo>) {
    if let Ok(entries) = fs::read_dir(path) {
        for entry in entries {
            if let Ok(entry) = entry {
                let metadata = entry.metadata().unwrap();
                if metadata.is_file() {
                    let path_str = entry.path().to_string_lossy().into_owned();
                    let size = metadata.len();
                    let modified_time = metadata.modified().unwrap().duration_since(std::time::SystemTime::UNIX_EPOCH).unwrap().as_secs() as i64;
                    file_info.push(FileInfo { path: path_str, size, modified_time });
                } else if metadata.is_dir() {
                    process_directory(&entry.path(), file_info);
                }
            }
        }
    }
}

fn main() {
    let root_path = Path::new("/path/to/root/directory");
    let mut file_info: Vec<FileInfo> = Vec::new();
    process_directory(root_path, &mut file_info);

    let total_files = file_info.len();
    let total_size: u64 = file_info.iter().map(|info| info.size).sum();
    let largest_file = file_info.iter().max_by_key(|info| info.size).unwrap();
    let recent_file = file_info.iter().max_by_key(|info| info.modified_time).unwrap();

    println!("Total number of files processed: {}", total_files);
    println!("Total size of all files processed: {} bytes", total_size);
    println!("Path of the largest file: {}", largest_file.path);
    println!("Path of the most recently modified file: {}", recent_file.path);
}
