import re

def evaluate_expression(expression):
    # Remove all spaces from the expression
    expression = expression.replace(" ", "")

    # Use regular expression to find all numbers, operators, and parentheses
    tokens = re.findall(r'(\d+|\+|\-|\*|\/|\(|\))', expression)

    # Operator precedence dictionary
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def evaluate(tokens):
        values = []
        operators = []
        for token in tokens:
            if token.isdigit():
                values.append(int(token))
            elif token in precedence:
                while (operators and precedence[operators[-1]] >= precedence[token]):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()
        while operators:
            apply_operator(operators, values)
        return values[0]

    return evaluate(tokens)

def main():
    user_input = input("Enter a mathematical expression: ")
    result = evaluate_expression(user_input)
    print(f"The result of the expression '{user_input}' is: {result}")

if __name__ == '__main__':
    main()
```

In the solution, the `evaluate_expression` function takes a mathematical expression as input, tokenizes it using regular expressions, and then evaluates the expression using a stack-based algorithm that respects operator precedence and parentheses. The `main` function takes user input, calls `evaluate_expression`, and then displays the result.

