    ListIterator<XmlElement> it = xmlElements.listIterator(xmlElements.size());
    while (it.hasPrevious() && pos > 0) {
        XmlElement e = it.previous();
        pos--;
        if (!e.getName().equals(namesFromTopAncestorToParent[pos])) {
            return false; // Element name does not match the pattern
        }
    }
    // Check if the last element in the stack matches the given Element
