```python
import cv2
import numpy as np

class StyleAugmentor:
    def __init__(self, style_params):
        self.style_params = style_params

    def apply_augmentation(self, image):
        augmented_image = image.copy()

        if 'brightness' in self.style_params:
            augmented_image = self.adjust_brightness(augmented_image, self.style_params['brightness'])

        if 'contrast' in self.style_params:
            augmented_image = self.adjust_contrast(augmented_image, self.style_params['contrast'])

        if 'rotation' in self.style_params:
            augmented_image = self.rotate_image(augmented_image, self.style_params['rotation'])

        return augmented_image

    def adjust_brightness(self, image, factor):
        hsv_image = cv2.cvtColor(image, cv2.COLOR_BGR2HSV)
        h, s, v = cv2.split(hsv_image)
        v = np.clip(v * factor, 0, 255).astype(np.uint8)
        final_hsv = cv2.merge([h, s, v])
        return cv2.cvtColor(final_hsv, cv2.COLOR_HSV2BGR)

    def adjust_contrast(self, image, factor):
        lab_image = cv2.cvtColor(image, cv2.COLOR_BGR2LAB)
        l, a, b = cv2.split(lab_image)
        l = np.clip(l * factor, 0, 255).astype(np.uint8)
        final_lab = cv2.merge([l, a, b])
        return cv2.cvtColor(final_lab, cv2.COLOR_LAB2BGR)

    def rotate_image(self, image, angle):
        height, width = image.shape[:2]
        rotation_matrix = cv2.getRotationMatrix2D((width / 2, height / 2), angle, 1)
        return cv2.warpAffine(image, rotation_matrix, (width, height))
```
This solution provides a `StyleAugmentor` class that can apply brightness adjustment, contrast adjustment, and rotation to an input image based on the specified style parameters. The `apply_augmentation` method applies the specified style augmentation operations to the input image, and the helper methods `adjust_brightness`, `adjust_contrast`, and `rotate_image` perform the actual image transformations.

