You are given a code snippet that performs factorization of a number using the Pollard's rho algorithm. Your task is to implement a function that takes an integer `n` as input and returns the prime factors of `n` using the Pollard's rho algorithm.

The Pollard's rho algorithm is an algorithm used to find the prime factors of a composite integer. It is based on the concept of iterating a function and finding the greatest common divisor (GCD) of the resulting values. The algorithm uses a random number generator and a function to generate a sequence of numbers, and then applies the GCD operation to find factors.

Your task is to implement the function `pollardsRho` that takes an integer `n` as input and returns a list of prime factors of `n`.

```cpp
#include <iostream>
#include <vector>
#include <cmath>

int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

bool prime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

std::vector<int> pollardsRho(int n) {
    std::vector<int> factors;
    if (n == 1) {
        factors.push_back(1);
        return factors;
    }
    if (n % 2 == 0) {
        factors.push_back(2);
        while (n % 2 == 0) {
            n /= 2;
        }
    }
    if (n == 1) return factors;

    int x = rand() % (n - 2) + 2;
    int y = x;
    int c = rand() % (n - 1) + 1;
    int d = 1;

    auto f = [n](int x) { return (x * x + 3) % n; };

    while (d == 1) {
        x = f(x);
        y = f(f(y));
        d = gcd(abs(x - y), n);
    }

    if (d == n) {
        do {
            y = (y * y + 3) % n;
            d = gcd(abs(x - y), n);
        } while (d == 1);
    }

    if (!prime(d)) {
        factors.push_back(d);
        factors.push_back(n / d);
    } else {
        factors.push_back(d);
    }

    return factors;
}

int main() {
    int n;
    std::cout << "Enter a number: ";
    std::cin >> n;
    std::vector<int> factors = pollardsRho(n);
    std::cout << "Prime factors of " << n << " are: ";
    for (int factor : factors) {
        std::cout << factor << " ";
    }
    std::cout << std::endl;
    return 0;
}
```

