import Foundation

class EmployeeDataProcessor {
    private var employeeData: [(name: String, salary: Double)] = []

    func readDataFromFile(filename: String) {
        if let fileURL = Bundle.main.url(forResource: filename, withExtension: "txt") {
            do {
                let data = try String(contentsOf: fileURL, encoding: .utf8)
                let lines = data.components(separatedBy: .newlines)
                for line in lines {
                    let components = line.components(separatedBy: ",")
                    if components.count == 2, let salary = Double(components[1]) {
                        employeeData.append((name: components[0], salary: salary))
                    }
                }
            } catch {
                print("Error reading file: \(error)")
            }
        } else {
            print("File not found")
        }
    }

    func calculateAverageSalary() -> Double {
        let totalSalary = employeeData.reduce(0.0) { $0 + $1.salary }
        return totalSalary / Double(employeeData.count)
    }

    func findEmployeeWithHighestSalary() -> String {
        if let employee = employeeData.max(by: { $0.salary < $1.salary }) {
            return employee.name
        }
        return "No employees found"
    }

    func findEmployeeWithLowestSalary() -> String {
        if let employee = employeeData.min(by: { $0.salary < $1.salary }) {
            return employee.name
        }
        return "No employees found"
    }

    func calculateTotalSalaryExpense() -> Double {
        return employeeData.reduce(0.0) { $0 + $1.salary }
    }
}

// Usage
let processor = EmployeeDataProcessor()
processor.readDataFromFile(filename: "employee_data")
let averageSalary = processor.calculateAverageSalary()
let highestSalaryEmployee = processor.findEmployeeWithHighestSalary()
let lowestSalaryEmployee = processor.findEmployeeWithLowestSalary()
let totalExpense = processor.calculateTotalSalaryExpense()
print("Average Salary: \(averageSalary)")
print("Employee with Highest Salary: \(highestSalaryEmployee)")
print("Employee with Lowest Salary: \(lowestSalaryEmployee)")
print("Total Salary Expense: \(totalExpense)")
