std::vector<std::string> extractAndSortWrites(const std::string& trace) {
  std::vector<std::string> writes;
  size_t eol = 0;
  while (eol != std::string::npos) {
    size_t bol = eol + 1;
    eol = trace.find('\n', bol);
    size_t line_len = (eol == std::string::npos) ? std::string::npos : eol - bol;
    std::string line = trace.substr(bol, line_len);
    if (line.size() > 0 && line[0] == '>')
      writes.push_back(line);
  }
  std::sort(writes.begin(), writes.end());
  return writes;
}

int main() {
  std::string trace = "Read data\n>Write to file\n>Update database\n>Log activity\n>Write to file\n";
  std::vector<std::string> sorted_writes = extractAndSortWrites(trace);
  for (const auto& write : sorted_writes) {
    std::cout << write << std::endl;
  }
  return 0;
}
