        weight = packages[i]
        destination = destinations[i]
        if weight <= rates[destination]['max']:
            for weight_range, cost in sorted(rates[destination].items()):
                if weight <= weight_range:
                    total_cost += cost
                    break
        else:
            total_cost += rates[destination]['additional_fee']
    return total_cost
