class ConstrainedProperty:
    def __init__(self, min_value, max_value):
        self.min_value = min_value
        self.max_value = max_value

    def __call__(self, fget):
        def wrapped(instance):
            return instance.__dict__[fget.__name__]

        def setter(instance, value):
            if not isinstance(value, int):
                raise ValueError("Property value must be an integer")
            if not self.min_value <= value <= self.max_value:
                raise ValueError(f"Property value must be between {self.min_value} and {self.max_value}")
            instance.__dict__[fget.__name__] = value

        return property(wrapped, setter)


class MyClass:
    @ConstrainedProperty(1, 100)
    def constrained_value(self):
        return self.__dict__.get('constrained_value', None)

    @constrained_value.setter
    def constrained_value(self, value):
        pass  # The setter logic is handled by the decorator

# Usage
