// EmailValidatorService implementation
@Injectable()
export class EmailValidatorService {
    constructor(private http: HttpClient) { }

    validateEmail(email: string): Promise<boolean> {
        return new Promise((resolve, reject) => {
            // Basic email format validation
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            if (!emailRegex.test(email)) {
                reject("Invalid email format");
            }

            // Check if domain exists
            const domain = email.split('@')[1];
            this.checkDomainExists(domain)
                .then(exists => {
                    resolve(exists);
                })
                .catch(error => {
                    reject(error);
                });
        });
    }

    private checkDomainExists(domain: string): Promise<boolean> {
        return this.http.get(`https://api.domaincheck.com/check/${domain}`)
            .toPromise()
            .then(response => {
                return response.exists;
            })
            .catch(error => {
                throw new Error("Error checking domain existence");
            });
    }
}

// EmailValidatorComponent implementation
@Component({
    selector: "ns-email-validator",
    providers: [EmailValidatorService],
    moduleId: module.id,
    templateUrl: "./email-validator.component.html",
    styleUrls: ["./email-validator.component.css"]
})
export class EmailValidatorComponent implements OnInit {
    email: string;
    response: string;

    constructor(private emailValidatorService: EmailValidatorService, private location: Location, private routerExtension: RouterExtensions) { }

    ngOnInit() {
        this.email = "";
        this.response = "Waiting for email to validate";
    }

    validateEmail() {
        this.response = "Validating email...";
        this.emailValidatorService.validateEmail(this.email)
            .then(valid => {
                this.response = valid ? "Email is valid" : "Email is invalid";
            })
            .catch(error => {
                this.response = "Validation error: " + error.message;
            });
    }
}
```
