public int uniquePaths(int[][] grid) {
    int m = grid.length;
    int n = grid[0].length;

    if (grid[0][0] == 1 || grid[m-1][n-1] == 1) {
        return 0; // No path if start or end is blocked
    }

    int[][] dp = new int[m][n];
    dp[0][0] = 1;

    // Fill the first row
    for (int i = 1; i < n; i++) {
        if (grid[0][i] == 0) {
            dp[0][i] = dp[0][i-1];
        }
    }

    // Fill the first column
    for (int i = 1; i < m; i++) {
        if (grid[i][0] == 0) {
            dp[i][0] = dp[i-1][0];
        }
    }

    // Fill the rest of the grid
    for (int i = 1; i < m; i++) {
        for (int j = 1; j < n; j++) {
            if (grid[i][j] == 0) {
                dp[i][j] = dp[i-1][j] + dp[i][j-1];
            }
        }
    }

    return dp[m-1][n-1];
}
```

