class Task:
    def __init__(self, name, sync=True, **meta):
        self.name = name
        self.sync = sync
        self.meta = meta

class TaskManager:
    def __init__(self, name=None, log=False):
        self.tasks = []
        self.name = name
        self.log = log
        self.active_tasks = {}

    def start(self, name, sync=True, **meta):
        task = self.task(name, sync=sync, **meta)
        if self.log:
            print('Started', name)

        if name in self.active_tasks:
            raise ValueError(f'Nesting tasks is not allowed, "{name}" was already started and not finished')
        self.active_tasks[name] = task

    def finish(self, name):
        if name not in self.active_tasks:
            raise ValueError(f"Task '{name}' was not found or already finished")
        del self.active_tasks[name]
        if self.log:
            print('Finished', name)

    def task(self, name, sync=True, **meta):
        new_task = Task(name, sync, **meta)
        self.tasks.append(new_task)
        return new_task
```

