        self.devices = {}

    def add_device(self, device_id, status):
        if status not in ["on", "off"]:
            raise ValueError("Invalid status. Status must be 'on' or 'off'.")
        self.devices[device_id] = status

    def remove_device(self, device_id):
        if device_id in self.devices:
            del self.devices[device_id]
        else:
            raise KeyError("Device not found.")

    def toggle_device(self, device_id):
        if device_id in self.devices:
            if self.devices[device_id] == "on":
                self.devices[device_id] = "off"
            else:
                self.devices[device_id] = "on"
        else:
            raise KeyError("Device not found.")

    def force_turn_off(self, device_id):
