      if (char === '+' || char === '-') {
        if (currentNum !== '') {
          parsedExpression.push(parseInt(currentNum, 10));
          currentNum = '';
        }
        parsedExpression.push(char);
      } else {
        currentNum += char;
      }
    }
    if (currentNum !== '') {
      parsedExpression.push(parseInt(currentNum, 10));
    }
    return parsedExpression;
  }

  evaluateExpression(parsedExpression) {
    let result = 0;
    let currentOperator = '+';
    for (let i = 0; i < parsedExpression.length; i++) {
      const token = parsedExpression[i];
      if (typeof token === 'number') {
        if (currentOperator === '+') {
          result += token;
        } else {
          result -= token;
        }
      } else {
        currentOperator = token;
      }
    }
    return result;
  }
}
```

In the solution, the MEP class is implemented with the `parseExpression` and `evaluateExpression` methods. The `parseExpression` method parses the input string into an array of integers and operators. The `evaluateExpression` method evaluates the parsed expression and returns the result.

