import abc

class BankAccount:
    def __init__(self, account_number, name, initial_balance):
        self.account_number = account_number
        self.name = name
        self.balance = initial_balance

class Bank(abc.ABC):
    def __init__(self):
        self.accounts = {}

    @dispatch(str, int)
    def create_account(self, name, initial_balance):
        account_number = str(len(self.accounts) + 1)
        new_account = BankAccount(account_number, name, initial_balance)
        self.accounts[account_number] = new_account
        return account_number

    @dispatch(str, float)
    def deposit(self, account_number, amount):
        if account_number in self.accounts:
            self.accounts[account_number].balance += amount
        else:
            raise ValueError("Account not found")

    @dispatch(str, float)
    def withdraw(self, account_number, amount):
        if account_number in self.accounts:
            if self.accounts[account_number].balance >= amount:
                self.accounts[account_number].balance -= amount
            else:
                raise ValueError("Insufficient balance")
        else:
            raise ValueError("Account not found")

    @dispatch(str, str, float)
    def transfer(self, from_account_number, to_account_number, amount):
        if from_account_number in self.accounts and to_account_number in self.accounts:
            if self.accounts[from_account_number].balance >= amount:
                self.accounts[from_account_number].balance -= amount
                self.accounts[to_account_number].balance += amount
            else:
                raise ValueError("Insufficient balance in the source account")
        else:
            raise ValueError("One or both accounts not found")
