import os

class BankingSystem:
    def __init__(self):
        if not os.path.exists('accounts.txt'):
            with open('accounts.txt', 'w'):
                pass

    def create_account(self, name, initial_balance):
        with open('accounts.txt', 'a') as file:
            account_number = self._generate_account_number()
            file.write(f"{account_number},{name},{initial_balance}\n")
            return account_number

    def deposit(self, account_number, amount):
        accounts = self._read_accounts()
        for i, account in enumerate(accounts):
            if account[0] == account_number:
                accounts[i] = (account[0], account[1], float(account[2]) + amount)
                self._write_accounts(accounts)
                return
        print("Account not found.")

    def withdraw(self, account_number, amount):
        accounts = self._read_accounts()
        for i, account in enumerate(accounts):
            if account[0] == account_number:
                if float(account[2]) >= amount:
                    accounts[i] = (account[0], account[1], float(account[2]) - amount)
                    self._write_accounts(accounts)
                    return
                else:
                    print("Insufficient balance.")
                    return
        print("Account not found.")

    def check_balance(self, account_number):
        accounts = self._read_accounts()
        for account in accounts:
            if account[0] == account_number:
                return float(account[2])
        print("Account not found.")
        return None

    def _generate_account_number(self):
        accounts = self._read_accounts()
        if not accounts:
            return "1"
        else:
            return str(int(accounts[-1][0]) + 1)

    def _read_accounts(self):
        accounts = []
        with open('accounts.txt', 'r') as file:
            for line in file:
                account_info = line.strip().split(',')
                accounts.append((account_info[0], account_info[1], account_info[2]))
        return accounts

    def _write_accounts(self, accounts):
        with open('accounts.txt', 'w') as file:
            for account in accounts:
                file.write(','.join(account) + '\n')

def main():
    banking_system = BankingSystem()
    while True:
        print("1. Create Account")
        print("2. Deposit")
        print("3. Withdraw")
        print("4. Check Balance")
        print("5. Exit")
