class HTMLTag:
    def __init__(self, tag, content=None, **kwargs):
        self.tag = tag
        self.content = []
        self.meta = kwargs
        if content:
            self.__add__(content)

    def __add__(self, content):
        if isinstance(content, str):
            self.content.append(content)
        elif isinstance(content, HTMLTag):
            self.content.append(content)

    def __repr__(self):
        output = ""
        attributes = ""
        for attr, val in self.meta.items():
            if attr == "cl":
                attr = "class"
            attributes += """{}='{}' """.format(attr, val)
        if self.tag:
            output += "<{} {}>".format(self.tag, attributes)
            for item in self.content:
                if isinstance(item, HTMLTag):
                    output += repr(item)
                else:
                    output += str(item)
            output += "</{}>".format(self.tag)
        return output
```

