import Foundation

func findMostFrequentWord() {
    do {
        // Read the contents of the "input.txt" file
        if let filePath = Bundle.main.path(forResource: "input", ofType: "txt") {
            let content = try String(contentsOfFile: filePath)

            // Tokenize the text into individual words, remove punctuation marks, and convert to lowercase
            let words = content.lowercased().components(separatedBy: .punctuationCharacters).joined().components(separatedBy: .whitespaces)

            // Count the frequency of each word
            var wordFrequency: [String: Int] = [:]
            for word in words {
                if !word.isEmpty {
                    wordFrequency[word, default: 0] += 1
                }
            }

            // Identify the word with the highest frequency
            if let mostFrequentWord = wordFrequency.max(by: { $0.value < $1.value }) {
                print("Most frequent word: \(mostFrequentWord.key), Frequency: \(mostFrequentWord.value)")
            } else {
                print("No words found in the file.")
