class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def construct_binary_tree(nums):
    if not nums:
        return None

    nodes = [None if val is None else TreeNode(val) for val in nums]
    root = nodes[0]
    queue = [root]
    i = 1

    while queue and i < len(nums):
        node = queue.pop(0)
        if node:
            node.left = nodes[i]
            queue.append(node.left)
            i += 1
            if i < len(nums):
                node.right = nodes[i]
                queue.append(node.right)
                i += 1

    return root

def print_textual_tree(root):
    if not root:
        return

    queue = [root]
    result = []
    while queue:
        level_vals = []
        next_level = []
        for node in queue:
            if node:
                level_vals.append(str(node.val))
                next_level.append(node.left)
                next_level.append(node.right)
            else:
                level_vals.append("None")
        if any(next_level):
            result.append(" ".join(level_vals))
        queue = next_level

    for line in result:
        print(line)
```

You can use the `construct_binary_tree` function to construct the binary tree from the given list of integers and then use the `print_textual_tree` function to print its textual representation.

