            self.dimensions[dimension_name].append(hierarchy_name)
        else:
            raise ValueError("Dimension does not exist")

    def remove_hierarchy(self, dimension_name, hierarchy_name):
        if dimension_name in self.dimensions:
            if hierarchy_name in self.dimensions[dimension_name]:
                self.dimensions[dimension_name].remove(hierarchy_name)
            else:
                raise ValueError("Hierarchy does not exist in the dimension")
        else:
            raise ValueError("Dimension does not exist")

    def get_dimensions(self):
        return list(self.dimensions.keys())

    def get_hierarchies(self, dimension_name):
        if dimension_name in self.dimensions:
            return self.dimensions[dimension_name]
        else:
            raise ValueError("Dimension does not exist")
