fn convert_slices(int_slice: &mut [i32], float_slice: &mut [f32]) {
    assert_eq!(int_slice.len(), float_slice.len(), "Slice lengths must be equal");

    let int_ptr = int_slice.as_mut_ptr();
    let float_ptr = float_slice.as_mut_ptr();

    let int_len = int_slice.len();
    let float_len = float_slice.len();

    // Ensure that the slices do not overlap in memory
    assert!(!int_ptr as usize + int_len * std::mem::size_of::<i32>() > float_ptr as usize, "Slices overlap in memory");

