impl Light {
    fn find_pos_min_max(&self) -> Option<((isize, isize), (isize, isize))> {
        if self.velocity.0 == 0 && self.velocity.1 == 0 {
            return Some((self.pos, self.pos));
        }

        let min_x = if self.velocity.0 < 0 {
            Some(self.pos.0 + self.velocity.0)
        } else {
            None
        };

        let max_x = if self.velocity.0 > 0 {
            Some(self.pos.0 + self.velocity.0)
        } else {
            None
        };

        let min_y = if self.velocity.1 < 0 {
            Some(self.pos.1 + self.velocity.1)
        } else {
            None
        };

        let max_y = if self.velocity.1 > 0 {
            Some(self.pos.1 + self.velocity.1)
        } else {
            None
        };

        match (min_x, max_x, min_y, max_y) {
            (Some(min_x), Some(max_x), Some(min_y), Some(max_y)) => Some(((min_x, min_y), (max_x, max_y))),
            _ => None,
        }
    }
}
```

The `find_pos_min_max` method first checks if the velocity is zero in both directions and returns the current position as both the minimum and maximum positions if so. Then, it calculates the potential minimum and maximum positions in both x and y directions based on the velocity. Finally, it constructs the output tuple based on the calculated minimum and maximum positions, returning `Some` if both minimum and maximum positions are valid, and `None` otherwise.

