import json
from pathlib import Path

class FileStorage:
    def __init__(self, file_path: str):
        self._path = Path(file_path)
        if not self._path.exists():
            self._path.touch()

    def read(self) -> str:
        with self._path.open("r", encoding="utf-8") as f:
            return f.read()

    def write(self, data: str, sort: bool = False) -> None:
        data = json.dumps(data, sort_keys=sort)

