def simulate_migration(dependencies, operations):
    # Create a graph to represent the dependencies between migrations
    graph = defaultdict(list)
    for app, migration in dependencies:
        graph[migration].append(app)

    # Perform topological sorting to determine the order of applying migrations
    def topological_sort(node, visited, stack):
