impl Graph {
    pub fn add_forbidden_path(&mut self, path: Vec<NodeIdT>, graph: &impl EdgeIdGraph) {
        let mut forbidden_path = Vec::new();
        for (index, &node) in path.iter().enumerate() {
            if index > 0 && index < path.len() - 1 {
                self.node_forbidden_path_counter[node as usize] += 1;
            }
            if let Some((link_id, tail)) = graph.find_edge(path[index], path.get(index + 1).cloned().unwrap_or_default()) {
                let global_id = graph.edge_id_to_graph_id(link_id);
                let offset = graph.edge_id_to_offset(link_id);
                self.edge_forbidden_paths[link_id as usize].push((global_id, offset + 1, self.node_forbidden_path_counter[tail as usize] as u32));
            }
            forbidden_path.push((NodeIdT(node), self.node_forbidden_path_counter[node as usize] as u32));
        }
        self.forbidden_paths.push(forbidden_path);
    }

