def process_query(self, query, limit=None, exclude_self=False):
    if limit <= 0:
        raise ValueError(f'`limit` must be larger than 0, receiving {limit}')
    else:
        limit = int(limit)

    _limit = len(self) if limit is None else (limit + (1 if exclude_self else 0))

    if isinstance(query, (DocumentArray, Document)):
        # Process the query against the collection of documents
        results = self.process_document_query(query, _limit, exclude_self)
    elif isinstance(query, str):
        # Perform a text search against the collection of documents
        results = self.perform_text_search(query, _limit, exclude_self)
    else:
        raise ValueError('Unsupported query type')

    if limit is not None:
        return results[:limit]
    else:
        return results
