use std::collections::HashMap;

#[derive(Debug, PartialEq, Eq, Hash)]
struct Position {
    x: usize,
    y: usize,
}

#[derive(Debug, PartialEq, Eq)]
enum Tile {
    Passage,
    Portal,
}

type TileMap = HashMap<Position, Tile>;
type PortalMap = Vec<Position>;

fn find_portals(tilemap: &TileMap) -> PortalMap {
    tilemap
        .iter()
        .filter(|(_, &v)| v == &Tile::Portal)
        .map(|(pos, _)| pos.clone())
        .collect()
}

fn main() {
    let mut tilemap = TileMap::new();
    tilemap.insert(Position { x: 0, y: 0 }, Tile::Passage);
    tilemap.insert(Position { x: 1, y: 0 }, Tile::Portal);
    tilemap.insert(Position { x: 0, y: 1 }, Tile::Portal);
    tilemap.insert(Position { x: 1, y: 1 }, Tile::Passage);

    let portals = find_portals(&tilemap);
    println!("{:?}", portals); // Output: [Position { x: 1, y: 0 }, Position { x: 0, y: 1 }]
