def is_convex_hull(nodes, hull):
    def orientation(p, q, r):
        val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
        if val == 0:
            return 0  # collinear
        return 1 if val > 0 else 2  # clockwise or counterclockwise

    def is_convex(nodes, hull):
        n = len(nodes)
        if n < 3:
            return True
        prev_orientation = 0
        for i in range(n):
            p = nodes[hull[i % n]]
            q = nodes[hull[(i + 1) % n]]
            r = nodes[hull[(i + 2) % n]]
            o = orientation(p, q, r)
            if o == 0:
                continue
            if prev_orientation == 0:
                prev_orientation = o
            elif prev_orientation != o:
                return False
        return True

    return is_convex(nodes, hull)
```

