import Foundation

func monitorFileAndBuild(filePath: String, buildCommand: String) {
    let fileManager = FileManager.default
    var previousModificationDate = fileManager.attributesOfItem(atPath: filePath)?[.modificationDate] as? Date

    while true {
        if let modificationDate = fileManager.attributesOfItem(atPath: filePath)?[.modificationDate] as? Date {
            if modificationDate != previousModificationDate {
                print("File has been modified. Triggering build process...")
                let process = Process()
                process.launchPath = "/bin/bash"
                process.arguments = ["-c", buildCommand]
                process.launch()
                process.waitUntilExit()
                previousModificationDate = modificationDate
            }
        }
        // Introduce a delay before checking for file changes again
        sleep(1)
    }
}

