use std::collections::LinkedList;
use std::hash::{BuildHasher, Hash, Hasher};
use std::collections::hash_map::RandomState;

struct CustomHashMap<K, V, S = RandomState> {
    buckets: Vec<LinkedList<(K, V)>>,
    hash_builder: S,
}

impl<K, V, S> CustomHashMap<K, V, S>
where
    K: Eq + Hash,
    S: BuildHasher,
{
    fn new() -> Self {
        let initial_capacity = 16; // Initial capacity for the hash map
        let mut buckets = Vec::with_capacity(initial_capacity);
        for _ in 0..initial_capacity {
            buckets.push(LinkedList::new());
        }
        CustomHashMap {
            buckets,
            hash_builder: S::default(),
        }
    }

    fn insert(&mut self, key: K, value: V) {
        let hash = self.hash(&key);
        let index = (hash as usize) % self.buckets.len();
        for (existing_key, existing_value) in &mut self.buckets[index] {
            if *existing_key == key {
                *existing_value = value;
                return;
            }
        }
        self.buckets[index].push_back((key, value));
    }

    fn remove(&mut self, key: &K) {
        let hash = self.hash(key);
        let index = (hash as usize) % self.buckets.len();
        self.buckets[index].retain(|(k, _)| k != key);
    }

    fn get(&self, key: &K) -> Option<&V> {
        let hash = self.hash(key);
        let index = (hash as usize) % self.buckets.len();
        for (existing_key, existing_value) in &self.buckets[index] {
            if *existing_key == *key {
                return Some(existing_value);
            }
        }
        None
    }

    fn hash<T: Hash>(&self, t: &T) -> u64 {
        let mut hasher = self.hash_builder.build_hasher();
        t.hash(&mut hasher);
        hasher.finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_custom_hash_map() {
        let mut custom_map: CustomHashMap<&str, i32> = CustomHashMap::new();
        custom_map.insert("one", 1);
        custom_map.insert("two", 2);
        assert_eq!(custom_map.get(&"one"), Some(&1));
        assert_eq!(custom_map.get(&"two"), Some(&2));
        custom_map.insert("two", 20);
        assert_eq!(custom_map.get(&"two"), Some(&20));
        custom_map.remove(&"two");
        assert_eq!(custom_map.get(&"two"), None);
    }
}
```

