class Context:
    def __init__(self, Descriptor, params):
        self.Descriptor = Descriptor
        self.params = params

class Descriptor:
    def __init__(self, Parameters):
        self.Parameters = Parameters

def string_expansion(expanded: str, context: Context, default: str) -> str:
    for match in re.finditer(r'\${(.*?)\.(.*?)}', expanded):
        group, key = match.groups()
        if group == "Params":
            collection = context.Descriptor.Parameters
        elif group == "Publish":
            collection = context.params
        else:
            collection = context.params

        value = collection.get(key, default) if collection is not None else f'<<UNKNOWN GROUP {group}>>'
        expanded = expanded.replace(match.group(0), str(value))

    return expanded
```

