import java.io.*;
import java.util.ArrayList;
import java.util.List;

class Book {
    private String title;
    private String author;
    private int quantity;

    public Book(String title, String author, int quantity) {
        this.title = title;
        this.author = author;
        this.quantity = quantity;
    }

    // Getters and setters for title, author, and quantity

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getAuthor() {
        return author;
    }

    public void setAuthor(String author) {
        this.author = author;
    }

    public int getQuantity() {
        return quantity;
    }

    public void setQuantity(int quantity) {
        this.quantity = quantity;
    }
}

public class LibraryInventory {
    private List<Book> inventory;

    public LibraryInventory() {
        this.inventory = new ArrayList<>();
    }

    public void addBook(String title, String author, int quantity) {
        for (Book book : inventory) {
            if (book.getTitle().equals(title) && book.getAuthor().equals(author)) {
                book.setQuantity(book.getQuantity() + quantity);
                return;
            }
        }
        inventory.add(new Book(title, author, quantity));
    }

    public void removeBook(String title, String author) {
        inventory.removeIf(book -> book.getTitle().equals(title) && book.getAuthor().equals(author));
    }

    public List<Book> searchByTitle(String title) {
        List<Book> result = new ArrayList<>();
        for (Book book : inventory) {
            if (book.getTitle().contains(title)) {
                result.add(book);
            }
        }
        return result;
    }

    public List<Book> searchByAuthor(String author) {
        List<Book> result = new ArrayList<>();
        for (Book book : inventory) {
            if (book.getAuthor().contains(author)) {
                result.add(book);
            }
        }
        return result;
    }

    public void displayInventory() {
        for (Book book : inventory) {
            System.out.println("Title: " + book.getTitle() + ", Author: " + book.getAuthor() + ", Quantity: " + book.getQuantity());
        }
    }

    public void saveInventoryToFile(String filename) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filename))) {
            oos.writeObject(inventory);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void loadInventoryFromFile(String filename) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filename))) {
            inventory = (List<Book>) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }
}
```

