void DrawTexturedPolygon(const Color& color, const Vector2D* vertices, int numVertices, const Vector2D& position, int width, const Vector2D& uv11, const Vector2D& uv21) {
    vgui::surface()->DrawSetColor(color);

    // Create an array of vgui vertices
    Vertex_t* vguiVertices = new Vertex_t[numVertices];
    for (int i = 0; i < numVertices; i++) {
        vguiVertices[i].m_Position.x = vertices[i].x;
        vguiVertices[i].m_Position.y = vertices[i].y;
        vguiVertices[i].m_TexCoord.x = uv11.x + (uv21.x - uv11.x) * (vguiVertices[i].m_Position.x - position.x) / width;
        vguiVertices[i].m_TexCoord.y = uv11.y + (uv21.y - uv11.y) * (vguiVertices[i].m_Position.y - position.y) / width;
    }

    // Draw the textured polygon
    vgui::surface()->DrawTexturedPolygon(numVertices, vguiVertices);

    // Clean up allocated memory
    delete[] vguiVertices;
}
```
