        for i in range(self.size):
            for j in range(self.size):
                self.grid[i][j] = state[i][j]

    def player_won(self):
        # Check rows, columns, and diagonals for a winning condition
        for i in range(self.size):
            if all(self.grid[i][j] == '1' for j in range(self.size)) or \
               all(self.grid[j][i] == '1' for j in range(self.size)):
                return True
        if all(self.grid[i][i] == '1' for i in range(self.size)) or \
           all(self.grid[i][self.size - 1 - i] == '1' for i in range(self.size)):
            return True
        return False

    def get_empty_cells(self):
        empty_cells = []
        for i in range(self.size):
