def test_ssh(drop):
    if drop < 0:
        return "Invalid drop value. Please provide a non-negative integer."

    attempts = 0

    def login_attempt():
        nonlocal attempts
        attempts += 1
        if attempts < drop:
            return "Incorrect password. Please try again."
        elif attempts == drop:
            return "Maximum login attempts reached. Connection dropped."
        else:
            return "Connection already dropped."

    return login_attempt
