        if os.path.exists(file_path):
            os.remove(file_path)
        else:
            print(f"File '{file_name}' does not exist.")

    def list_files(self) -> List[str]:
        files = [f for f in os.listdir(self.current_directory) if os.path.isfile(os.path.join(self.current_directory, f))]
        return files

    def create_directory(self, directory_name: str):
        directory_path = os.path.join(self.current_directory, directory_name)
        if not os.path.exists(directory_path):
            os.makedirs(directory_path)
        else:
            print(f"Directory '{directory_name}' already exists.")

    def delete_directory(self, directory_name: str):
        directory_path = os.path.join(self.current_directory, directory_name)
