<?php

namespace BitmovinApiSdk\Apis\Encoding\Inputs\S3;

use \BitmovinApiSdk\Common\ObjectMapper;
use \BitmovinApiSdk\Models\S3Input;

class S3InputPaginationResponse extends \BitmovinApiSdk\Common\BasePaginationResponse
{
    /** @var S3Input[] */
    public $items;

    public function getNextPage(int $pageSize, int $currentPage): array
    {
        $startIndex = $pageSize * $currentPage;
        $endIndex = min($startIndex + $pageSize, count($this->items));
        return array_slice($this->items, $startIndex, $endIndex - $startIndex);
    }

    public function getPreviousPage(int $pageSize, int $currentPage): array
    {
        $startIndex = max(0, $pageSize * ($currentPage - 2));
        $endIndex = $pageSize * ($currentPage - 1);
        return array_slice($this->items, $startIndex, $endIndex - $startIndex);
    }
}
```

