Nil = None

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self, *elems):
        if len(elems) == 0:
            self.head = Nil
        else:
            self.head = Node(elems[0])
            current = self.head
            for elem in elems[1:]:
                current.next = Node(elem)
                current = current.next

    def append(self, elem):
        if self.head is Nil:
            self.head = Node(elem)
        else:
            current = self.head
            while current.next is not None:
                current = current.next
            current.next = Node(elem)

    def insert(self, elem, index):
        if index < 0:
            raise IndexError("Index out of range")
        if index == 0:
            new_node = Node(elem)
            new_node.next = self.head
            self.head = new_node
        else:
            current = self.head
            for _ in range(index - 1):
                if current is None:
                    raise IndexError("Index out of range")
                current = current.next
            if current is None:
                raise IndexError("Index out of range")
            new_node = Node(elem)
            new_node.next = current.next
            current.next = new_node

    def remove(self, elem):
        current = self.head
        if current is not None:
            if current.data == elem:
                self.head = current.next
                current = None
                return
        while current is not None:
            if current.data == elem:
                break
            prev = current
            current = current.next
        if current is None:
            return
        prev.next = current.next
        current = None

    def get(self, index):
        current = self.head
        for _ in range(index):
            if current is None:
                raise IndexError("Index out of range")
            current = current.next
        if current is None:
            raise IndexError("Index out of range")
        return current.data
```

