fn tokenize(mut job: Job) -> Vec<Token> {
    while !job.cursor.is_end() {
        // name tokens
        if let Some(x) = job.patterns.name.extract(job.cursor.tail()) {
            let x = try_traced!(x);
            job.push_token(Token::Name(x.name.to_string()));
            job.cursor.move_by(x.position.1);
            continue;
        }

        // numbers
        if let Some(x) = job.patterns.number.extract(job.cursor.tail()) {
            let x = try_traced!(x);
            let token = match x.number {
                number::Number::Integer(u) => Token::IntegerNumber(u),
                number::Number::Floating(f) => Token::FloatingNumber(f),
            };
            job.push_token(token);
            job.cursor.move_by(x.position.1);
            continue;
        }

        // keywords
        if let Some(x) = job.patterns.keyword.extract(job.cursor.tail()) {
            let x = try_traced!(x);
            job.push_token(Token::Keyword(x.keyword.to_string()));
            job.cursor.move_by(x.position.1);
            continue;
        }

        // symbols
        if let Some(x) = job.patterns.symbol.extract(job.cursor.tail()) {
            let x = try_traced!(x);
            job.push_token(Token::Symbol(x.symbol.to_string()));
            job.cursor.move_by(x.position.1);
            continue;
        }

        // identifiers
        if let Some(x) = job.patterns.identifier.extract(job.cursor.tail()) {
            let x = try_traced!(x);
            job.push_token(Token::Identifier(x.identifier.to_string()));
            job.cursor.move_by(x.position.1);
            continue;
        }

        // handle unrecognized tokens or syntax errors
        // ...

        // move cursor if no token is extracted
        job.cursor.move_forward(1);
    }

    job.tokens
}
```

