func parseProjectConfiguration(_ data: String) -> [String: Any] {
    var configuration: [String: Any] = [:]

    let lines = data.components(separatedBy: "\n")
    for line in lines {
        let components = line.components(separatedBy: ":")
        if components.count == 2 {
            let key = components[0].trimmingCharacters(in: .whitespaces)
            let value = components[1].trimmingCharacters(in: .whitespaces)
            if key == "isTest" {
                configuration[key] = (value.lowercased() == "true")
            } else if key == "dependencies" || key == "exclude" || key == "source" {
                let values = value.components(separatedBy: ",").map { $0.trimmingCharacters(in: .whitespaces) }
                configuration[key] = values
            } else {
                configuration[key] = value
            }
        }
    }

    return configuration
}

