fn vertical_lifting_base(
    left: &mut [&mut [i16]],
    middle: &mut [&mut [i16]],
    right: &mut [&mut [i16]],
    step: usize,
) {
    for i in 0..middle.len() {
        let middle_len = middle[i].len();
        for j in 0..middle_len {
            let avg = (left[i][j] + right[i][j]) / 2;
            middle[i][j] += avg - middle[i][j];
        }
    }
}
