// Implementation for finite field operations
pub mod field_n {
    use std::ops::{Add, Sub, Mul, Div};

    pub struct FieldN<T> {
        modulus: T,
    }

    impl<T> FieldN<T>
    where
        T: Copy + Add<Output = T> + Sub<Output = T> + Mul<Output = T> + Div<Output = T> + PartialEq,
    {
        pub fn new(modulus: T) -> Self {
            FieldN { modulus }
        }

        pub fn add(&self, a: T, b: T) -> T {
            (a + b) % self.modulus
        }

        pub fn sub(&self, a: T, b: T) -> T {
            (a - b + self.modulus) % self.modulus
        }

        pub fn mul(&self, a: T, b: T) -> T {
            (a * b) % self.modulus
        }

        pub fn div(&self, a: T, b: T) -> T {
            let inv_b = Self::mod_inv(b, self.modulus);
            self.mul(a, inv_b)
        }

        fn mod_inv(a: T, modulus: T) -> T {
            let mut t = (0, 1);
            let mut r = (modulus, a);

            while r.1 != 0 {
                let q = r.0 / r.1;
                t = (t.1, t.0 - q * t.1);
                r = (r.1, r.0 - q * r.1);
            }

            if r.0 > 1 {
                panic!("Modular inverse does not exist");
            }

            if t.0 < 0 {
                t.0 + modulus
            } else {
                t.0
            }
        }
    }
}

// Implementation for prime field operations
pub mod field_p {
    pub struct FieldP<T> {
        modulus: T,
    }

    pub trait ModExp<T> {
        fn mod_exp(&self, base: T, exponent: T) -> T;
    }

    impl<T> FieldP<T>
    where
        T: Copy + Add<Output = T> + Sub<Output = T> + Mul<Output = T> + PartialEq,
    {
        pub fn new(modulus: T) -> Self {
            FieldP { modulus }
        }

        pub fn add(&self, a: T, b: T) -> T {
            (a + b) % self.modulus
        }

        pub fn sub(&self, a: T, b: T) -> T {
            (a - b + self.modulus) % self.modulus
        }

        pub fn mul(&self, a: T, b: T) -> T {
            (a * b) % self.modulus
        }
    }

    impl<T> ModExp<T> for FieldP<T>
    where
        T: Copy + Add<Output = T> + Mul<Output = T> + PartialEq,
    {
        fn mod_exp(&self, base: T, exponent: T) -> T {
            let mut result = T::one();
            let mut base_val = base;
            let mut exp = exponent;

            while exp > T::zero() {
                if exp % T::from(2) == T::one() {
                    result = result * base_val % self.modulus;
                }
                base_val = base_val * base_val % self.modulus;
                exp = exp / T::from(2);
            }

            result
        }
    }
}
```

