let mut map = Map {
    caves: HashMap::new(),
};
map.caves.insert(
    "start".to_string(),
    Cave {
        name: "start".to_string(),
        connected_caves: vec!["cave1".to_string(), "cave2".to_string()],
    },
);
map.caves.insert(
    "cave1".to_string(),
    Cave {
        name: "cave1".to_string(),
        connected_caves: vec!["cave2".to_string()],
    },
);
map.caves.insert(
    "cave2".to_string(),
    Cave {
        name: "cave2".to_string(),
        connected_caves: vec!["end".to_string()],
    },
);
