import socket
import threading
import queue

class Scan_Handler:
    def __init__(self, verbose=False, verbosity="high", threads=50, ports=[80, 443]):
        self.verbose = verbose
        self.verbosity = verbosity
        self.threads = threads
        self.ports = ports
        self.outputs_queue = queue.Queue()

    def scan_port(self, ip, port):
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(1)
            result = sock.connect_ex((ip, port))
            if result == 0:
                self.outputs_queue.put(f"Port {port} is open on {ip}")
            sock.close()
        except Exception as e:
            if self.verbose:
                self.outputs_queue.put(f"Error scanning port {port} on {ip}: {str(e)}")

    def start_scanner(self, start_ip, end_ip):
        for ip in self.get_ip_range(start_ip, end_ip):
            for port in self.ports:
                thread_list = []
                for _ in range(self.threads):
                    t = threading.Thread(target=self.scan_port, args=(ip, port))
                    t.start()
                    thread_list.append(t)
                for t in thread_list:
                    t.join()

    def get_outputs_realtime(self):
        while True:
            if not self.outputs_queue.empty():
                yield self.outputs_queue.get()

    def get_ip_range(self, start_ip, end_ip):
        start = list(map(int, start_ip.split('.')))
        end = list(map(int, end_ip.split('.')))
        for i in range(start[0], end[0] + 1):
            for j in range(start[1], end[1] + 1):
                for k in range(start[2], end[2] + 1):
                    for l in range(start[3], end[3] + 1):
                        yield f"{i}.{j}.{k}.{l}"

def Background():
    for data in Scanner.get_outputs_realtime():
        print(str(data))

Scanner = Scan_Handler(verbose=False, verbosity="high", threads=50, ports=[80, 443])
Scanner.start_scanner("192.168.0.1", "192.168.0.5")

bg = threading.Thread(target=Background)
bg.start()
```

