public class InvestmentManager {
    private Map<String, BigDecimal> proportions;

    public InvestmentManager() {
        this.proportions = new HashMap<>();
    }

    public void setProportion(String investorName, BigDecimal proportion) {
        proportions.put(investorName, proportion);
    }

    public void calculateInvestorAmount(BigDecimal totalInvestmentAmount) {
        BigDecimal totalProportion = BigDecimal.ZERO;
        for (BigDecimal proportion : proportions.values()) {
            totalProportion = totalProportion.add(proportion);
        }

        if (totalProportion.compareTo(BigDecimal.ONE) != 0) {
            throw new IllegalArgumentException("Total proportions must sum to 1");
        }

        for (Map.Entry<String, BigDecimal> entry : proportions.entrySet()) {
            BigDecimal investorAmount = totalInvestmentAmount.multiply(entry.getValue());
            System.out.println(entry.getKey() + " will receive: " + investorAmount);
        }
    }

    public BigDecimal getInvestorAmount(String investorName, BigDecimal totalInvestmentAmount) {
        BigDecimal proportion = proportions.get(investorName);
        if (proportion == null) {
            throw new IllegalArgumentException("Investor not found");
        }
        return totalInvestmentAmount.multiply(proportion);
    }

    public static void main(String[] args) {
        InvestmentManager manager = new InvestmentManager();
        manager.setProportion("Investor1", new BigDecimal("0.3"));
        manager.setProportion("Investor2", new BigDecimal("0.5"));
        manager.setProportion("Investor3", new BigDecimal("0.2"));

        BigDecimal totalInvestmentAmount = new BigDecimal("10000");
