                if (i < data.Length - 1)
                {
                    sb.Append(",");
                }
            }
            sb.Append("]");
            return sb.ToString();
        }

        public string Serialize(string[] data)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("[");
            for (int i = 0; i < data.Length; i++)
            {
                sb.Append(Serialize(data[i]));
                if (i < data.Length - 1)
                {
                    sb.Append(",");
                }
            }
            sb.Append("]");
            return sb.ToString();
        }
    }

    public class DataDeserializer
    {
        public int DeserializeInt(string data)
        {
            return int.Parse(data);
        }

        public string DeserializeString(string data)
        {
            return data.Trim('"');
        }

        public bool DeserializeBool(string data)
        {
            return bool.Parse(data);
        }

        public int[] DeserializeIntArray(string data)
        {
            string[] elements = data.Trim('[', ']').Split(',');
            int[] result = new int[elements.Length];
            for (int i = 0; i < elements.Length; i++)
            {
                result[i] = DeserializeInt(elements[i]);
            }
            return result;
        }

        public string[] DeserializeStringArray(string data)
        {
            string[] elements = data.Trim('[', ']').Split(',');
            string[] result = new string[elements.Length];
            for (int i = 0; i < elements.Length; i++)
            {
                result[i] = DeserializeString(elements[i]);
            }
            return result;
        }
    }
}
```

This solution provides a basic implementation of a data serialization and deserialization library in C#. The `DataSerializer` class includes methods to serialize different data types, while the `DataDeserializer` class provides methods to deserialize the serialized data back to its original form. The serialization format is designed to be human-readable and easy to parse. This solution demonstrates a clear understanding of data serialization concepts and provides a robust and efficient implementation for the specified data types.

