import java.io.IOException;
import java.io.StringWriter;
import java.util.Map;

public class CustomFileWriter {
    private int size = 0;
    private String lineSeparator = System.lineSeparator();
    private String indent = "    "; // Example indentation

    public int writeToFile(Map<String, Object> keyValuePairs, StringWriter writer) throws IOException {
        for (Map.Entry<String, Object> kv : keyValuePairs.entrySet()) {
            String str = indent + kv.getKey() + " = " + kv.getValue().toString() + lineSeparator;
            writer.write(str);
            size += str.length();
        }
        String endMarker = "END" + lineSeparator;
        writer.write(endMarker);
        size += endMarker.length();
        return size;
    }

    public int calculateFileSize(Map<String, Object> keyValuePairs) {
        StringWriter tempWriter = new StringWriter();
        try {
            writeToFile(keyValuePairs, tempWriter);
        } catch (IOException e) {
            // Handle exception
            e.printStackTrace();
        }
        return tempWriter.toString().length();
    }
}
