struct CommandProcessor {
    values: Vec<i32>,
}

impl CommandProcessor {
    fn new() -> CommandProcessor {
        CommandProcessor { values: Vec::new() }
    }

    fn add_value(&mut self, value: i32) {
        self.values.push(value);
    }

    fn remove_value(&mut self, value: i32) {
        if let Some(index) = self.values.iter().position(|&x| x == value) {
            self.values.remove(index);
        }
    }

    fn calculate_sum(&self) -> i32 {
        self.values.iter().sum()
    }
}

fn process_commands(commands: &Vec<(&str, i32)>) {
    let mut processor = CommandProcessor::new();

    for command in commands {
        match command.0 {
            "add" => processor.add_value(command.1),
            "remove" => processor.remove_value(command.1),
            "sum" => println!("{}", processor.calculate_sum()),
            _ => println!("Invalid command"),
        }
    }
}
```

