class PeerManager {
    constructor() {
        this.peerstore = new Map();
    }

    addPeer(id, addr, ttl) {
        if (this.peerstore.has(id)) {
            const conflictingPeer = { id, addr: this.peerstore.get(id).addr_ttl.addr };
            return new Error(`Peer with ID ${id} already exists at address ${conflictingPeer.addr}`);
        } else {
            this.peerstore.set(id, { addr_ttl: { addr, ttl } });
        }
    }

    updatePeer(id, addr, ttl) {
        if (this.peerstore.has(id)) {
            this.peerstore.set(id, { addr_ttl: { addr, ttl } });
        } else {
            return new Error(`Peer with ID ${id} not found`);
        }
    }

    getPeer(id) {
        if (this.peerstore.has(id)) {
            const { addr, ttl } = this.peerstore.get(id).addr_ttl;
            return { id, addr, ttl };
        } else {
            return null;
        }
    }
}

// Usage
const manager = new PeerManager();
manager.addPeer("peer1", "192.168.0.1", 3600);
manager.addPeer("peer2", "192.168.0.2", 7200);
console.log(manager.getPeer("peer1")); // { id: 'peer1', addr: '192.168.0.1', ttl: 3600 }
manager.updatePeer("peer1", "192.168.0.3", 1800);
console.log(manager.getPeer("peer1")); // { id: 'peer1', addr: '192.168.0.3', ttl: 1800 }
console.log(manager.getPeer("peer3")); // null
```

