import Foundation

class Queue<T> {
    private var elements: [T] = []
    private let queueSync = DispatchQueue(label: "com.example.queueSync", attributes: .concurrent)

    func enqueue(_ element: T) {
        queueSync.async(flags: .barrier) {
            self.elements.append(element)
        }
    }

    func dequeue() -> T? {
        var element: T?
        queueSync.sync(flags: .barrier) {
            if !self.elements.isEmpty {
                element = self.elements.removeFirst()
            }
        }
        return element
    }

    func isEmpty() -> Bool {
        var empty = false
        queueSync.sync {
            empty = self.elements.isEmpty
        }
        return empty
    }

    func peek() -> T? {
        var element: T?
        queueSync.sync {
            if !self.elements.isEmpty {
                element = self.elements.first
            }
        }
        return element
    }
}
```

In the solution, a `DispatchQueue` with the `.concurrent` attribute is used to synchronize access to the queue's methods. The `enqueue` and `dequeue` methods use `async(flags: .barrier)` and `sync(flags: .barrier)` to ensure thread-safe modification of the queue. The `isEmpty` and `peek` methods also use `sync` to safely access the queue's state. This implementation guarantees that the queue can be safely accessed and modified by multiple threads concurrently.

