import os
import shutil

def organize_files(source_dir):
    if not os.path.exists(source_dir):
        print("Source directory does not exist.")
        return

    file_extension_dict = {}
    for root, _, files in os.walk(source_dir):
        for file in files:
            if '.' in file:
                file_extension = file.split('.')[-1]
                if file_extension not in file_extension_dict:
                    file_extension_dict[file_extension] = []
                file_extension_dict[file_extension].append(file)

    for extension, files in file_extension_dict.items():
        destination_dir = os.path.join(source_dir, extension)
        if not os.path.exists(destination_dir):
            os.makedirs(destination_dir)
        for file in files:
            source_file_path = os.path.join(source_dir, file)
            destination_file_path = os.path.join(destination_dir, file)
            if os.path.exists(destination_file_path):
                base, extension = os.path.splitext(file)
                index = 1
                while os.path.exists(os.path.join(destination_dir, f"{base}_{index}{extension}")):
                    index += 1
                destination_file_path = os.path.join(destination_dir, f"{base}_{index}{extension}")
            shutil.move(source_file_path, destination_file_path)

source_directory = input("Enter the source directory path: ")
organize_files(source_directory)
