class VendingMachine:
    def __init__(self):
        self.stock = {}
        self.balance = 0

    def stock_item(self, item_name, price, quantity):
        if item_name in self.stock:
            self.stock[item_name]['quantity'] += quantity
        else:
            self.stock[item_name] = {'price': price, 'quantity': quantity}

    def display_items(self):
        print("Available Items:")
        for item, details in self.stock.items():
            print(f"{item}: ${details['price']} - Quantity: {details['quantity']}")

    def insert_coin(self, coin_value):
        if coin_value in [1, 5, 10, 25]:
            self.balance += coin_value
        else:
            print("Invalid coin denomination. Accepted denominations: 1, 5, 10, 25")

    def select_item(self, item_name):
        if item_name in self.stock:
            if self.stock[item_name]['quantity'] > 0:
                if self.balance >= self.stock[item_name]['price']:
                    print(f"Dispensing {item_name}")
                    self.stock[item_name]['quantity'] -= 1
                    self.balance -= self.stock[item_name]['price']
                else:
                    print("Insufficient balance. Please insert more coins.")
            else:
                print(f"{item_name} is out of stock.")
        else:
            print(f"{item_name} is not available in the vending machine.")

    def return_change(self):
        change = self.balance
        self.balance = 0
        coins = {25: 0, 10: 0, 5: 0, 1: 0}
        while change > 0:
            if change >= 25 and coins[25] < 4:
                coins[25] += 1
                change -= 25
            elif change >= 10 and coins[10] < 4:
                coins[10] += 1
                change -= 10
            elif change >= 5 and coins[5] < 4:
                coins[5] += 1
                change -= 5
            else:
                coins[1] += change
                change = 0
        print("Returning change:")
        for coin, count in coins.items():
            if count > 0:
                print(f"{count} x {coin}c")
