    def print_task(self, pages):
        print(f"Printing {pages} pages...")
        time.sleep(pages / self.printing_speed * 60)
        print("Printed successfully.")

    def simulate_printing(self):
        if not self.enabled:
            print(f"{self.name} is currently disabled.")
            return

        while not self.print_queue.empty():
            pages = self.print_queue.get()
            self.print_task(pages)
