    var itemTextColor: UIColor = .black
    var itemFont: UIFont = UIFont.systemFont(ofSize: 14)
    var itemBackgroundColor: UIColor = .clear

    func reloadData() {
        // Remove existing item views
        itemViews.forEach { $0.removeFromSuperview() }
        itemViews.removeAll()

        // Create and layout new item views
        var previousItemView: UIView?
        for item in items {
            let itemView = createItemView(with: item)
            addSubview(itemView)
            itemViews.append(itemView)

            // Layout item view
            itemView.translatesAutoresizingMaskIntoConstraints = false
            itemView.leadingAnchor.constraint(equalTo: leadingAnchor).isActive = true
            itemView.trailingAnchor.constraint(equalTo: trailingAnchor).isActive = true
            if let previousItemView = previousItemView {
                itemView.topAnchor.constraint(equalTo: previousItemView.bottomAnchor, constant: itemSpacing).isActive = true
            } else {
                itemView.topAnchor.constraint(equalTo: topAnchor).isActive = true
            }

            previousItemView = itemView
        }

        // Set content size for scroll view if needed
        if let lastItemView = itemViews.last {
            lastItemView.bottomAnchor.constraint(equalTo: bottomAnchor).isActive = true
        }
    }

    private func createItemView(with text: String) -> UILabel {
        let label = UILabel()
        label.text = text
        label.textColor = itemTextColor
        label.font = itemFont
        label.backgroundColor = itemBackgroundColor
        return label
    }
}
```

