#ifndef STACK_HPP
#define STACK_HPP

#include <vector>
#include <stdexcept>

class Stack {
private:
    std::vector<int> elements;

public:
    // Constructor
    Stack() {}

    // Destructor
    ~Stack() {}

    // Add an element to the top of the stack
    void push(int val) {
        elements.push_back(val);
    }

    // Remove the element from the top of the stack and return its value
    int pop() {
