class ShoppingCart {
  items: { name: string, price: number }[] = [];

  addItem(item: { name: string, price: number }): void {
    this.items.push(item);
  }

  removeItem(itemName: string): void {
    const index = this.items.findIndex(item => item.name === itemName);
    if (index !== -1) {
      this.items.splice(index, 1);
    }
  }

  calculateTotal(): number {
    return this.items.reduce((total, item) => total + item.price, 0);
  }

  applyDiscount(discountPercentage: number): void {
    if (discountPercentage >= 0 && discountPercentage <= 100) {
      const discountFactor = 1 - discountPercentage / 100;
      this.items.forEach(item => {
        item.price *= discountFactor;
      });
    } else {
      throw new Error('Invalid discount percentage. Please provide a value between 0 and 100.');
    }
  }
}

// Example usage
const cart = new ShoppingCart();
cart.addItem({ name: 'Shirt', price: 25 });
cart.addItem({ name: 'Pants', price: 40 });
console.log(cart.calculateTotal()); // Output: 65
cart.applyDiscount(10);
console.log(cart.calculateTotal()); // Output: 58.5
cart.removeItem('Shirt');
console.log(cart.calculateTotal()); // Output: 40
