from datetime import timedelta

def format_time_delta(delta, granularity):
    if granularity == 'seconds':
        return f"{delta.seconds} seconds"
    elif granularity == 'minutes':
        minutes, seconds = divmod(delta.seconds, 60)
        if minutes == 1 and seconds == 0:
            return "1 minute"
        else:
            return f"{minutes}m {seconds}s"
    elif granularity == 'hours':
        hours, remainder = divmod(delta.seconds, 3600)
        if hours == 1 and remainder == 0:
            return "1 hour"
        else:
            minutes, seconds = divmod(remainder, 60)
            return f"{hours}h {minutes}m"
    elif granularity == 'days':
        return f"{delta.days} days"
    else:
        return "Invalid granularity"

# Test cases
print(format_time_delta(timedelta(days=0, hours=0, minutes=0, seconds=0), 'seconds'))  # Output: 0 seconds
print(format_time_delta(timedelta(days=0, hours=0, minutes=0, seconds=5), 'seconds'))  # Output: 5 seconds
print(format_time_delta(timedelta(days=0, hours=0, minutes=1, seconds=5), 'minutes'))  # Output: 1m 5s
