```cpp
#include <iostream>
#include <string>

std::string incrementVersion(int major, int minor, int revision) {
    revision++;  // Increment the revision component by one

    // Check for overflow and adjust the version numbers accordingly
    if (revision > 9) {
        revision = 0;
        minor++;
    }
    if (minor > 9) {
        minor = 0;
        major++;
    }

    // Construct the incremented version number as a string
    return std::to_string(major) + "." + std::to_string(minor) + "." + std::to_string(revision);
}

int main() {
    const int Major = 4;
    const int Minor = 2;
    const int Revision = 2;

    std::string newVersion = incrementVersion(Major, Minor, Revision);
    std::cout << "Incremented version: " << newVersion << std::endl;

    return 0;
}
