import java.util.HashMap;
import java.util.Map;

// Interface for part factory
interface PartFactory<T> {
    T createPart();
}

// Generic factory class
public class GenericPartFactory {
    private Map<Class<?>, PartFactory<?>> factories = new HashMap<>();

    // Register a part factory for the specified type
    public <T> void registerFactory(Class<T> type, PartFactory<T> factory) {
        factories.put(type, factory);
    }

    // Retrieve the part factory for the specified type
    @SuppressWarnings("unchecked")
    public <T> PartFactory<T> getFactory(Class<T> type) {
        return (PartFactory<T>) factories.get(type);
    }

    // Create a part for the specified type using the registered part factory
    public <T> T createPart(Class<T> type) {
        PartFactory<T> factory = getFactory(type);
        if (factory == null) {
            throw new IllegalArgumentException("No factory registered for type " + type.getName());
        }
        return factory.createPart();
    }
}

// Example part factory for floating-point numbers
class FloatPartFactory implements PartFactory<Float> {
    @Override
    public Float createPart() {
        return 0.0f; // Example implementation for creating a float part
    }
}

// Example part factory for integer numbers
class IntegerPartFactory implements PartFactory<Integer> {
    @Override
    public Integer createPart() {
        return 0; // Example implementation for creating an integer part
    }
}

// Example usage
class Main {
    public static void main(String[] args) {
        GenericPartFactory genericPartFactory = new GenericPartFactory();
        genericPartFactory.registerFactory(Float.class, new FloatPartFactory());
        genericPartFactory.registerFactory(Integer.class, new IntegerPartFactory());

        Float floatPart = genericPartFactory.createPart(Float.class);
        System.out.println("Created float part: " + floatPart);

        Integer intPart = genericPartFactory.createPart(Integer.class);
