from PIL import Image, ImageFilter

def process_image(image: Image, operations: List[str]) -> Image:
    processed_image = image.copy()

    for operation in operations:
        operation_parts = operation.split()
        if operation_parts[0] == "resize":
            width, height = int(operation_parts[1]), int(operation_parts[2])
            processed_image = processed_image.resize((width, height))
        elif operation_parts[0] == "crop":
            x, y, width, height = int(operation_parts[1]), int(operation_parts[2]), int(operation_parts[3]), int(operation_parts[4])
            processed_image = processed_image.crop((x, y, x + width, y + height))
        elif operation_parts[0] == "apply_filter":
            filter_name = operation_parts[1]
            if filter_name == "grayscale":
                processed_image = processed_image.convert("L")
            elif filter_name == "sepia":
                processed_image = sepia_filter(processed_image)
            elif filter_name == "blur":
                processed_image = processed_image.filter(ImageFilter.BLUR)

    return processed_image

def sepia_filter(image: Image) -> Image:
    width, height = image.size
    pixels = image.load()
    for x in range(width):
        for y in range(height):
            r, g, b = pixels[x, y]
            tr = int(0.393 * r + 0.769 * g + 0.189 * b)
            tg = int(0.349 * r + 0.686 * g + 0.168 * b)
            tb = int(0.272 * r + 0.534 * g + 0.131 * b)
            pixels[x, y] = (min(tr, 255), min(tg, 255), min(tb, 255))
    return image
```

This solution defines the `process_image` function that iterates through the list of operations and applies the corresponding image manipulation operations. The `sepia_filter` function is also provided to apply the sepia filter to the image.

