```python
class DataPointBase:
    def __init__(self, attributes):
        self.attributes = attributes

    def get_attribute(self, attribute_name):
        return self.attributes.get(attribute_name, None)


class DataPoint(DataPointBase):
    def __init__(self, attributes):
        super().__init__(attributes)

    def calculate_distance(self, other_data_point):
        # Calculate the Euclidean distance between this data point and another data point
        distance = 0
        for attribute_name in self.attributes:
            if attribute_name in other_data_point.attributes:
                distance += (self.attributes[attribute_name] - other_data_point.attributes[attribute_name]) ** 2
        return distance ** 0.5

    def normalize(self):
        # Normalize the data values of this data point
        max_value = max(self.attributes.values())
        for attribute_name in self.attributes:
            self.attributes[attribute_name] /= max_value
