use std::io;
use rand::Rng;

fn number_comparison_game(rounds: u32) -> i32 {
    let mut score = 0;
    let mut rng = rand::thread_rng();

    for _ in 0..rounds {
        let current_num = rng.gen_range(1..=100);
        println!("Current number: {}", current_num);

        let next_num = rng.gen_range(1..=100);
        println!("Is the next number greater than {}? (yes/no)", current_num);

        let mut guess = String::new();
        io::stdin().read_line(&mut guess).expect("Failed to read line");

        let next_greater = next_num > current_num;
        let guess_correct = if next_greater {
            guess.trim() == "yes"
        } else {
            guess.trim() == "no"
        };

        if guess_correct {
            score += 1;
        } else {
            score -= 1;
        }
    }

    score
}

fn main() {
    let rounds = 5;
    let final_score = number_comparison_game(rounds);
    println!("Final score: {}", final_score);
}
