from typing import List

def version_control(commands: List[str]) -> str:
    current_branch = "main"
    commits = set()

    for command in commands:
        operation, *args = command.split()
        if operation == "checkout":
            current_branch = args[0]
        elif operation == "reset":
            commits = {args[2]}  # Reset to a single commit
        elif operation == "cherry-pick":
