#include <vector>

std::vector<double> ApplyConstraint(const std::vector<std::vector<double>>& relationMatrix, const std::vector<double>& constantVector, const std::vector<double>& masterDofsValues) {
    std::vector<double> modifiedConstantVector(constantVector.size(), 0.0);

    for (size_t i = 0; i < relationMatrix.size(); ++i) {
        double aux = constantVector[i];
        for (size_t j = 0; j < relationMatrix[i].size(); ++j) {
            aux += relationMatrix[i][j] * masterDofsValues[j];
        }
        modifiedConstantVector[i] = aux;
    }

    return modifiedConstantVector;
}
```

