use bytes::Bytes;

struct ByteQueue {
    data: Vec<u8>,
}

impl ByteQueue {
    fn new() -> ByteQueue {
        ByteQueue { data: Vec::new() }
    }

    fn push(&mut self, byte: u8) {
        self.data.push(byte);
    }

    fn pop(&mut self) -> Option<u8> {
        if self.data.is_empty() {
            None
        } else {
            Some(self.data.remove(0))
        }
    }

    fn peek(&self) -> Option<u8> {
        self.data.first().cloned()
    }

    fn size(&self) -> usize {
        self.data.len()
    }
}

fn main() {
    let mut queue = ByteQueue::new();
    queue.push(10);
    queue.push(20);
    println!("{}", queue.peek().unwrap()); // Output: 10
    println!("{}", queue.pop().unwrap());  // Output: 10
    println!("{}", queue.size()); // Output: 1
}
```

