function getExportedItems(moduleName) {
  const modulePath = `./${moduleName}.js`;
  if (!fs.existsSync(modulePath)) {
    throw new NoSuchModuleError(moduleName);
  }

  const moduleExports = require(path.resolve(modulePath));
  const exportedItems = Object.keys(moduleExports);

  if (exportedItems.length === 0) {
    throw new NoSuchExportError(moduleName);
  }

  return exportedItems;
}

