class CommentExtractor {
    public func getData(from input: String) -> String {
        guard let startRange = input.range(of: "/*"), let endRange = input.range(of: "*/") else {
            return ""
        }

        let startIndex = startRange.upperBound
        let endIndex = endRange.lowerBound
        let commentContent = input[startIndex..<endIndex].trimmingCharacters(in: .whitespacesAndNewlines)

        return commentContent
    }
}

