// Define the custom vector type
struct dVector {
    float x, y, z, w;
    dVector(float _x, float _y, float _z, float _w) : x(_x), y(_y), z(_z), w(_w) {}
};

float calculateUV(float* vertex, float* normals, int vertexCount, int indexCount, int* nIndex) {
    dVector* n = new dVector[indexCount];
    dVector* uv0 = new dVector[indexCount];
    dVector* uv1 = new dVector[indexCount];

    for (int i = 0; i < vertexCount; i++) {
        int j = i * 3;
        n[i] = dVector(static_cast<float>(vertex[j + 0]), static_cast<float>(vertex[j + 1]), static_cast<float>(vertex[j + 2]), 0.0f);
    }

    for (int i = 0; i < indexCount; i++) {
        nIndex[i] = i;
        int j = i * 3;
        n[i] = dVector(static_cast<float>(normals[j + 0]), static_cast<float>(normals[j + 1]), static_cast<float>(normals[j + 2]), 0.0f);
        // Initialize uv0 and uv1 arrays with specific values
        uv0[i] = dVector(1.0f, 0.0f, 0.0f, 0.0f);
        uv1[i] = dVector(0.0f, 1.0f, 0.0f, 0.0f);
    }

    // Calculate the sum of x-coordinates of the dVector objects in the n array
    float sumX = 0.0f;
    for (int i = 0; i < indexCount; i++) {
        sumX += n[i].x;
    }

    // Deallocate the dynamically allocated memory
    delete[] n;
    delete[] uv0;
    delete[] uv1;

    return sumX;
}

int main() {
    // Example usage
    int vertexCount = 3;
    int indexCount = 3;
    float* vertex = new float[vertexCount * 3];
    float* normals = new float[indexCount * 3];
    int* nIndex = new int[indexCount];

    // Populate vertex and normals arrays with sample data

    // Call the calculateUV function
    float sumX = calculateUV(vertex, normals, vertexCount, indexCount, nIndex);
    std::cout << "Sum of x-coordinates: " << sumX << std::endl;

    // Deallocate the dynamically allocated memory
    delete[] vertex;
    delete[] normals;
    delete[] nIndex;

    return 0;
}
