import os

class FileExplorer:
    def __init__(self):
        self.current_directory = os.getcwd()

    def to_string(self):
        print(f"Contents of directory '{self.current_directory}':")
        for item in os.listdir(self.current_directory):
            print(item)

    def change_directory(self, directory_name: str):
        new_directory = os.path.join(self.current_directory, directory_name)
        if os.path.isdir(new_directory):
            self.current_directory = new_directory
            print(f"Changed directory to '{self.current_directory}'")
        else:
            print(f"Directory '{directory_name}' does not exist")

    def parent_directory(self):
        parent_directory = os.path.dirname(self.current_directory)
        if parent_directory != self.current_directory:
            self.current_directory = parent_directory
            print(f"Changed directory to '{self.current_directory}'")
        else:
            print("Already in the root directory")

def main():
    explorer = FileExplorer()
    explorer.to_string()
    explorer.change_directory("subdirectory1")
    explorer.to_string()
    explorer.parent_directory()
    explorer.to_string()

if __name__ == "__main__":
    main()
```

In the solution, the `FileExplorer` class is implemented using the `os` module to interact with the file system. The `to_string()` method lists the contents of the current directory, `change_directory()` allows navigation into subdirectories, and `parent_directory()` enables navigation to the parent directory. The `main()` function demonstrates the usage of the `FileExplorer` class by listing the contents, navigating into a subdirectory, and then returning to the parent directory.

