import Combine

class CustomPublisher: Publisher {
    typealias Output = Int
    typealias Failure = Never

    func receive<S>(subscriber: S) where S : Subscriber, Failure == S.Failure, Output == S.Input {
        let subscription = CustomSubscription(subscriber: subscriber)
        subscriber.receive(subscription: subscription)
    }
}

class CustomSubscription<S: Subscriber>: Subscription where S.Input == Int, S.Failure == Never {
    private var subscriber: S?
    private var counter = 1

    init(subscriber: S) {
        self.subscriber = subscriber
    }

    func request(_ demand: Subscribers.Demand) {
        while counter <= 5, demand > 0 {
            if let subscriber = subscriber {
                demand -= 1
                let newDemand = subscriber.receive(counter)
                if newDemand == .none {
                    break
                }
                counter += 1
            }
        }
        if counter > 5, let subscriber = subscriber {
            subscriber.receive(completion: .finished)
        }
    }

    func cancel() {
        subscriber = nil
    }
}

class CustomSubscriber: Subscriber {
    typealias Input = Int
    typealias Failure = Never

