You are tasked with implementing a doubly linked list in C++. A doubly linked list is a data structure that consists of a sequence of elements, where each element has a reference to the previous and next elements in the sequence. Your task is to create a class that represents a doubly linked list and implement various operations on it.

Your doubly linked list class should have the following functionalities:
1. Insertion of a new element at the beginning of the list.
2. Deletion of a specified element from the list.
3. Traversal of the list in both forward and backward directions.

You should also implement a method to print the elements of the list in both forward and backward directions.

Your implementation should include the following class definition:
```cpp
class DoublyLinkedList {
private:
    struct Node {
        int data;
        Node* prev;
        Node* next;
        Node(int val) : data(val), prev(nullptr), next(nullptr) {}
    };
    Node* head;

public:
    DoublyLinkedList() : head(nullptr) {}

    // Function to insert a new element at the beginning of the list
    void insertAtBeginning(int val);

    // Function to delete a specified element from the list
    void deleteElement(int val);

    // Function to traverse the list in the forward direction and print the elements
    void traverseForward();

    // Function to traverse the list in the backward direction and print the elements
    void traverseBackward();
};
```

output:
```cpp
#include <iostream>

void DoublyLinkedList::insertAtBeginning(int val) {
    Node* newNode = new Node(val);
    if (head == nullptr) {
        head = newNode;
    } else {
        newNode->next = head;
        head->prev = newNode;
        head = newNode;
    }
}

void DoublyLinkedList::deleteElement(int val) {
    Node* current = head;
    while (current != nullptr) {
        if (current->data == val) {
            if (current->prev != nullptr) {
                current->prev->next = current->next;
            } else {
                head = current->next;
            }
            if (current->next != nullptr) {
                current->next->prev = current->prev;
            }
            delete current;
            return;
        }
        current = current->next;
    }
}

void DoublyLinkedList::traverseForward() {
    Node* current = head;
    while (current != nullptr) {
        std::cout << current->data << " ";
        current = current->next;
    }
    std::cout << std::endl;
}

void DoublyLinkedList::traverseBackward() {
    Node* current = head;
    while (current->next != nullptr) {
        current = current->next;
    }
    while (current != nullptr) {
        std::cout << current->data << " ";
        current = current->prev;
    }
    std::cout << std::endl;
}

int main() {
    DoublyLinkedList list;
    list.insertAtBeginning(3);
    list.insertAtBeginning(5);
    list.insertAtBeginning(7);
    list.insertAtBeginning(9);
    list.traverseForward();  // Output: 9 7 5 3
    list.traverseBackward(); // Output: 3 5 7 9
    list.deleteElement(5);
    list.traverseForward();  // Output: 9 7 3
    list.traverseBackward(); // Output: 3 7 9
    return 0;
}
```

