import re

def parse_configuration(config_snippet: str) -> dict:
    result = {}

    # Extracting first run number
    first_run_match = re.search(r'myFirstRunLSEvt\[(\d+)\]', config_snippet)
    if first_run_match:
        result['first_run'] = int(first_run_match.group(1))
    else:
        result['first_run'] = None

    # Extracting event range
    event_range_match = re.search(r'join\(myFirstRunLSEvt\[0:3\]\)\+\'-\'\+join\(myLastRunLSEvt\[0:3\]\)', config_snippet)
    if event_range_match:
        event_range_values = re.findall(r'myFirstRunLSEvt\[(\d+)\]', config_snippet)
        result['event_range_start'] = ':'.join(event_range_values[:3])
        result['event_range_end'] = ':'.join(event_range_values[3:])
    else:
        result['event_range_start'] = None
        result['event_range_end'] = None

    # Extracting file name
    file_name_match = re.search(r'myFirstRunLSEvt\[3\]', config_snippet)
    if file_name_match:
        result['file_name'] = '%s' % file_name_match.group(0)
    else:
        result['file_name'] = None

    # Extracting production annotation
    production_annotation_match = re.search(r'annotation = cms.untracked.string\(\'(.+?)\'\)', config_snippet)
    if production_annotation_match:
        result['production_annotation'] = production_annotation_match.group(1)
    else:
        result['production_annotation'] = None

    return result
