from abc import ABC, abstractmethod
from datetime import datetime, timedelta

class DatetimeProcessor(ABC):
    @abstractmethod
    def string_to_datetime(self, date: str, format_: str = None) -> datetime:
        pass

    @abstractmethod
    def calculate_time_difference(self, dt1: datetime, dt2: datetime) -> timedelta:
        pass

class MyDatetimeProcessor(DatetimeProcessor):
    def string_to_datetime(self, date: str, format_: str = None) -> datetime:
        if format_ is None:
            format_ = "%Y/%m/%d %H:%M:%S.%f"
        dt = datetime.strptime(date.replace('-', '/').replace('T', ' ').replace('Z', ''), format_)
        return dt

    def calculate_time_difference(self, dt1: datetime, dt2: datetime) -> timedelta:
        return dt2 - dt1

# Example usage
processor = MyDatetimeProcessor()
date_str = "2022-01-01T12:00:00Z"
dt = processor.string_to_datetime(date_str, "%Y-%m-%dT%H:%M:%SZ")
print(dt)  # Output: 2022-01-01 12:00:00
dt1 = datetime(2022, 1, 1, 12, 0, 0)
dt2 = datetime(2022, 1, 1, 13, 0, 0)
time_diff = processor.calculate_time_difference(dt1, dt2)
print(time_diff)  # Output: 1:00:00
