from typing import List, Dict, Union

class Token:
    MapStart = "MapStart"
    MapEnd = "MapEnd"
    String = "String"

def processTokens(tokens: List[Token]) -> Dict[str, Union[str, Dict[str, Union[str, Dict[str, Union[str, ...]]]]]]:
    stack = []
    current_map = {}
    stack.append(current_map)

    for token in tokens:
        if token == Token.MapStart:
            new_map = {}
            stack[-1][key] = new_map
            stack.append(new_map)
        elif token == Token.MapEnd:
            stack.pop()
        elif token == Token.String:
            key = token.value
            stack[-1][key] = None
        else:
            raise ValueError("Invalid token")

    return current_map
```

This solution uses a stack to keep track of the current map being processed. It iterates through the tokens and updates the nested map structure accordingly, handling `MapStart`, `MapEnd`, and `String` tokens appropriately. The final nested map is returned as the result.

