class DirectedGraph:
    def __init__(self):
        self.adjacency_list = {}

    def add_node(self, node):
        if node not in self.adjacency_list:
            self.adjacency_list[node] = []

    def add_edge(self, from_node, to_node):
        if from_node in self.adjacency_list and to_node in self.adjacency_list:
            self.adjacency_list[from_node].append(to_node)

    def has_node(self, node):
        return node in self.adjacency_list

    def predecessors_iter(self, node):
        predecessors = []
        for from_node, to_nodes in self.adjacency_list.items():
            if node in to_nodes:
                predecessors.append(from_node)
        return iter(predecessors)

