#include <iostream>
#include <stack>
#include <string>

int minBracesToAdd(const std::string& codeSnippet) {
    std::stack<char> bracesStack;
    int openBraces = 0;
    int closeBraces = 0;

    for (char c : codeSnippet) {
        if (c == '{') {
            bracesStack.push(c);
        } else if (c == '}') {
            if (bracesStack.empty()) {
                closeBraces++;
            } else {
                bracesStack.pop();
            }
        }
    }

    openBraces = bracesStack.size();

    return openBraces + closeBraces;
}

int main() {
    std::string codeSnippet = "void someFunction() { if (condition) { // }";
    std::cout << minBracesToAdd(codeSnippet) << std::endl; // Output: 2
    return 0;
