import argparse

def main():
    parser = argparse.ArgumentParser(description='COMPlus Settings Configuration Tool')
    parser.add_argument('complus_settings', nargs='*', help='list of extra COMPlus settings in the format Name=Value')
    parser.add_argument('-n', '--ngen', help='use ngened mscorlib', default=False, action="store_true")
    parser.add_argument('-p', '--precise-gc', help='test with precise gc', default=False, action="store_true")

    args = parser.parse_args()

    # Process and validate COMPlus settings
    comp_plus_settings = {}
    for setting in args.complus_settings:
        name_value = setting.split('=')
        if len(name_value) == 2:
            name, value = name_value
            if not name.startswith('COMPlus_AltJit'):
                comp_plus_settings[name] = value
            else:
                print(f"Ignoring setting '{name}' as it has the COMPlus_AltJit prefix.")

    # Handle optional arguments
    if args.ngen:
        print("Using ngened mscorlib")

    if args.precise_gc:
        print("Testing with precise garbage collection")

    # Process and apply COMPlus settings
    for name, value in comp_plus_settings.items():
        print(f"Setting COMPlus setting '{name}' to '{value}'")

if __name__ == '__main__':
    main()
```

