struct BitSet {
    private var bits: UInt64 = 0

    init(withWords words: UInt64...) {
        for word in words {
            bits |= word
        }
    }

    func setBit(atIndex index: Int) {
        bits |= (1 << index)
    }

    func clearBit(atIndex index: Int) {
        bits &= ~(1 << index)
    }

    func getBit(atIndex index: Int) -> Int {
        return (bits >> index) & 1
    }

    func toggleBit(atIndex index: Int) {
        bits ^= (1 << index)
    }

    func toString() -> String {
        var result = ""
        var tempBits = bits
        while tempBits > 0 {
            result = "\(tempBits & 1)" + result
            tempBits >>= 1
        }
        return result.isEmpty ? "0" : result
    }
}
```

