// Command interface
class Command {
public:
    virtual void Execute() = 0;
};

// Concrete command classes
class ConcreteCommand1 : public Command {
public:
    void Execute() override {
        std::cout << "Executing ConcreteCommand1" << std::endl;
    }
};

class ConcreteCommand2 : public Command {
public:
    void Execute() override {
        std::cout << "Executing ConcreteCommand2" << std::endl;
    }
};

// CommandProcessor class
class CommandProcessor {
private:
    std::vector<Command*> commands;
    size_t cmdPtr;

public:
    CommandProcessor() : cmdPtr(0) {}

    void AddCommand(Command* cmd) {
        commands.push_back(cmd);
    }

    void ExecuteCommands() {
        while (cmdPtr != commands.size()) {
            Command* a = commands[cmdPtr];
            a->Execute();
            cmdPtr++;
        }
    }
};

int main() {
    CommandProcessor processor;
    processor.AddCommand(new ConcreteCommand1());
    processor.AddCommand(new ConcreteCommand2());

    processor.ExecuteCommands();

    return 0;
}
```

