    public IList<Person> FilterAndSortByFacts(List<Person> persons, string relationshipType)
    {
        var filteredPersons = persons
            .Where(p => p.Relationships.Contains(relationshipType))
            .OrderBy(p => p.Facts.Count)
            .ThenByDescending(p => p.LastName)
            .ToList();

        return filteredPersons;
    }
}
