extension Parser {
    func pullback<NewInput>(_ keyPath: KeyPath<NewInput, Input>) -> AnyParser<NewInput, Output> {
        return AnyParser<NewInput, Output> { newInput in
            var input = newInput[keyPath: keyPath]
            if let (output, rest) = self.parse(&input) {
                return (output, newInput[keyPath: keyPath] = rest)
            }
            return nil
        }
    }
}
