from typing import Dict, Union

class Bank:
    def __init__(self):
        self.accounts: Dict[int, float] = {}

    def create_account(self, account_holder: str, initial_balance: float) -> int:
        account_number = hash(account_holder)  # Using hash of account holder's name as a unique account number
        self.accounts[account_number] = initial_balance
        return account_number

    def deposit(self, account_number: int, amount: float) -> float:
        if account_number in self.accounts:
            self.accounts[account_number] += amount
            return self.accounts[account_number]
        else:
            raise ValueError("Account not found")

    def withdraw(self, account_number: int, amount: float) -> Union[float, str]:
        if account_number in self.accounts:
            if self.accounts[account_number] >= amount:
                self.accounts[account_number] -= amount
                return self.accounts[account_number]
            else:
                return "Insufficient funds"
        else:
            return "Account not found"

    def check_balance(self, account_number: int) -> Union[float, str]:
        if account_number in self.accounts:
            return self.accounts[account_number]
        else:
            return "Account not found"

# Sample usage
