const path = require('path');
const fs = require('fs');

function resolveModuleBindings(modulePath) {
  const resolvedPath = path.resolve(modulePath);
  const moduleDir = path.dirname(resolvedPath);
  const moduleContent = fs.readFileSync(resolvedPath, 'utf8');

  const consumedBindings = [];
  const providedBindings = [];

  const importRegex = /import\s+\{(.+?)\}\s+from\s+'(.+?)'/g;
  let match;
  while ((match = importRegex.exec(moduleContent)) !== null) {
    const importedBindings = match[1].split(',').map(binding => binding.trim());
    const importedModulePath = path.resolve(moduleDir, match[2]);
    const importedModuleBindings = resolveModuleBindings(importedModulePath);
    consumedBindings.push(...importedBindings);
    providedBindings.push(...importedModuleBindings.providedBindings);
  }

  return { consumedBindings, providedBindings };
}

// Test the function with the provided example
const resolvedBindings = resolveModuleBindings('./index.js');
console.log(resolvedBindings);
```

This solution uses Node.js built-in modules `path` and `fs` to resolve module paths and read module content. It employs regular expressions to extract consumed and provided bindings from the module content and recursively resolves imported module bindings. The function returns an object containing the consumed and provided bindings for the specified module.

