class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def add(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def show(self, node, word):
        if node.is_end_of_word:
            print(word, end=" ")
        for char, next_node in node.children.items():
            self.show(next_node, word + char)

if __name__ == "__main__":
    trie = Trie()
    words = ["wait", "waiter", "shop", "shopper"]
    for word in words:
        trie.add(word)
    print(trie.search("wait"))    # Output: True
    print(trie.search("waiter"))  # Output: True
    print(trie.search(""))        # Output: False
    print(trie.search("wai"))     # Output: False
    trie.show(trie.root, "")      # Output: wait waiter shop shopper
```

In this solution, the `TrieNode` class represents each node in the Trie, containing a dictionary of children nodes and a boolean flag to indicate the end of a word. The `Trie` class implements the `add` and `search` methods to add words to the Trie and search for words, respectively. The `show` method is used to visualize all the words in the Trie. When the code is executed, it adds the words "wait", "waiter", "shop", and "shopper" to the Trie and performs search operations, followed by displaying all the words in the Trie.

