class Library:
    def __init__(self):
        self.books = {}
        self.members = {}

    def borrow_book(self, member_id, book_title):
        if book_title in self.books and self.books[book_title] > 0:
            if member_id in self.members and len(self.members[member_id]) < 3:
                self.books[book_title] -= 1
                if member_id not in self.members:
                    self.members[member_id] = [book_title]
                else:
                    self.members[member_id].append(book_title)
                return "Book successfully borrowed"
            else:
                return "Member has reached maximum borrow limit"
        else:
            return "Book not available"

    def return_book(self, member_id, book_title):
        if member_id in self.members and book_title in self.members[member_id]:
            self.books[book_title] += 1
            self.members[member_id].remove(book_title)
            return "Book successfully returned"
        else:
            return "Member has not borrowed this book"
```

