import os
from typing import List

def extract_message_types(directory_path: str) -> List[str]:
    message_types = []
    for root, dirs, files in os.walk(directory_path):
        for file in files:
            if file.endswith('.py'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    lines = f.readlines()
                    for line in lines:
                        if line.startswith('from .') and line.endswith(' import *\n'):
                            message_type = line.split('from .')[1].split(' import')[0]
                            message_types.append(message_type)
    return message_types
```

This solution uses the `os.walk` function to traverse the directory and its subdirectories, then reads each Python file to find lines that match the pattern `from ._<MessageType> import *`. It extracts the message type from each matching line and adds it to the `message_types` list, which is returned at the end.

