class DirectoryExistsError(Exception):
    pass

class DirectoryNotFoundError(Exception):
    pass

class SimpleFileSystem:
    def __init__(self):
        self.file_system = {}

    def create_directory(self, directory_name):
        if directory_name in self.file_system:
            raise DirectoryExistsError(f"Directory '{directory_name}' already exists.")
        self.file_system[directory_name] = {}

    def create_file(self, directory_name, file_name, content):
        if directory_name not in self.file_system:
            raise DirectoryNotFoundError(f"Directory '{directory_name}' not found.")
        self.file_system[directory_name][file_name] = content

    def list_directory_contents(self, directory_name):
        if directory_name not in self.file_system:
            raise DirectoryNotFoundError(f"Directory '{directory_name}' not found.")
        return list(self.file_system[directory_name].keys())
