class EventHandler:
    def __init__(self):
        self._eventHandlers = {}

    def registerEventHandler(self, eventType, callback):
        if eventType not in self._eventHandlers:
            self._eventHandlers[eventType] = []

        handlerID = len(self._eventHandlers[eventType])
        self._eventHandlers[eventType].append(callback)

        return handlerID

    def unregisterEventHandler(self, eventType, handlerID):
        if eventType in self._eventHandlers and 0 <= handlerID < len(self._eventHandlers[eventType]):
            del self._eventHandlers[eventType][handlerID]
            return True
        else:
            return False
```

