struct VirtualMachine {
    architecture: String,
    image_type: String,
    virtualization_type: String,
    // Other attributes
}

struct Filter {
    name: Option<String>,
    values: Option<Vec<String>>,
}

fn filter_virtual_machines(filters: Vec<Filter>, virtual_machines: Vec<VirtualMachine>) -> Vec<VirtualMachine> {
    virtual_machines
        .into_iter()
        .filter(|vm| {
            filters.iter().all(|filter| {
                match &filter.name {
                    Some(name) => {
                        match name.as_str() {
                            "architecture" => filter.values.as_ref().map_or(true, |values| values.contains(&vm.architecture)),
                            "image-type" => filter.values.as_ref().map_or(true, |values| values.contains(&vm.image_type)),
                            "virtualization-type" => filter.values.as_ref().map_or(true, |values| values.contains(&vm.virtualization_type)),
                            _ => true, // Handle other filter types if needed
                        }
                    }
                    None => true, // Handle filters with no name if needed
                }
            })
        })
        .collect()
}
