```python
import os
import sys
import shlex

ALIASES_FILE = os.path.expanduser("~/.custom_aliases")

def load_aliases():
    aliases = {}
    if os.path.exists(ALIASES_FILE):
        with open(ALIASES_FILE, "r") as file:
            for line in file:
                name, command = line.strip().split("=", 1)
                aliases[name] = command
    return aliases

def save_aliases(aliases):
    with open(ALIASES_FILE, "w") as file:
        for name, command in aliases.items():
            file.write(f"{name}={command}\n")

def list_aliases(aliases):
    for name, command in aliases.items():
        print(f"{name}='{command}'")

def main():
    aliases = load_aliases()

    if len(sys.argv) == 1:
        list_aliases(aliases)
    elif sys.argv[1] == "alias":
        if len(sys.argv) < 4 or sys.argv[2] != "=":
            print("Invalid alias command format. Usage: alias <name>='<command>'")
        else:
            name = sys.argv[2]
            command = " ".join(sys.argv[3:])
            aliases[name] = command
            save_aliases(aliases)
    elif sys.argv[1] == "unalias":
        name = sys.argv[2]
        if name in aliases:
            del aliases[name]
            save_aliases(aliases)
        else:
            print(f"Alias '{name}' does not exist.")
    else:
        print("Invalid command. Supported commands: alias, unalias")

if __name__ == "__main__":
    main()
```

This Python program provides a simple command-line tool for managing aliases. It loads aliases from a file, allows users to create new aliases, list existing aliases, and remove aliases. The aliases are persisted in a file for future sessions. The program expects commands in the format `alias <name>='<command>'`, `alias`, or `unalias <name>`.

