import sys
import os

def create_file(file_system_name, file_name):
    file_path = f"{file_system_name}/{file_name}"
    if not os.path.exists(file_system_name):
        os.makedirs(file_system_name)
    with open(file_path, 'w'):
        pass

def read_file(file_system_name, file_name):
    file_path = f"{file_system_name}/{file_name}"
    if os.path.exists(file_path):
        with open(file_path, 'r') as file:
            print(file.read())
    else:
        print(f"File '{file_name}' not found in the file system '{file_system_name}'")

def update_file(file_system_name, file_name, new_content):
    file_path = f"{file_system_name}/{file_name}"
    if os.path.exists(file_path):
        with open(file_path, 'w') as file:
            file.write(new_content)
    else:
        print(f"File '{file_name}' not found in the file system '{file_system_name}'")

def delete_file(file_system_name, file_name):
    file_path = f"{file_system_name}/{file_name}"
    if os.path.exists(file_path):
        os.remove(file_path)
    else:
        print(f"File '{file_name}' not found in the file system '{file_system_name}'")

def main():
    if len(sys.argv) < 5:
        print("Usage: ./sfs -f <file_system_name> <operation> [operation_arguments]")
        return

    file_system_name = sys.argv[2]
    operation = sys.argv[3]
    if operation == "create":
        if len(sys.argv) < 6:
            print("Usage: ./sfs -f <file_system_name> create <file_name>")
            return
        create_file(file_system_name, sys.argv[4])
    elif operation == "read":
        if len(sys.argv) < 5:
            print("Usage: ./sfs -f <file_system_name> read <file_name>")
            return
        read_file(file_system_name, sys.argv[4])
    elif operation == "update":
        if len(sys.argv) < 7:
            print("Usage: ./sfs -f <file_system_name> update <file_name> <new_content>")
            return
        update_file(file_system_name, sys.argv[4], sys.argv[5])
    elif operation == "delete":
        if len(sys.argv) < 5:
            print("Usage: ./sfs -f <file_system_name> delete <file_name>")
            return
        delete_file(file_system_name, sys.argv[4])
    else:
        print(f"Unsupported operation: {operation}")

if __name__ == "__main__":
    main()
```

