def validate_schema_consistency(pyspark_schema: List[StructField], cerberus_schema: Dict[str, Dict[str, Any]]) -> bool:
    if len(pyspark_schema) != len(cerberus_schema):
        return False
    if sorted([column_schema.name for column_schema in pyspark_schema]) != sorted(cerberus_schema.keys()):
        return False
    if not all(isinstance(column_schema, StructField) for column_schema in pyspark_schema):
        return False
    return True
