use regex::Regex;

#[derive(Debug)]
struct CodeInfo {
    extern_html_root_takes_precedence: bool,
    xpath_query: String,
    xpath_query_target: String,
    reexported_module: String,
}

fn extract_code_info(code_snippet: &str) -> CodeInfo {
    let mut info = CodeInfo {
        extern_html_root_takes_precedence: false,
        xpath_query: String::new(),
        xpath_query_target: String::new(),
        reexported_module: String::new(),
    };

    let precedence_regex = Regex::new(r"--extern-html-root.*--takes-precedence").unwrap();
    if precedence_regex.is_match(code_snippet) {
        info.extern_html_root_takes_precedence = true;
    }

    let xpath_regex = Regex::new(r#"\s*//\s*@has\s*-\s*'([^']+)'\s*'([^']+)'\s*"#).unwrap();
    if let Some(captures) = xpath_regex.captures(code_snippet) {
        info.xpath_query = captures.get(1).unwrap().as_str().to_string();
        info.xpath_query_target = captures.get(2).unwrap().as_str().to_string();
    }

    let reexport_regex = Regex::new(r"pub use\s+([\w:]+);").unwrap();
    if let Some(captures) = reexport_regex.captures(code_snippet) {
        info.reexported_module = captures.get(1).unwrap().as_str().to_string();
    }

    info
}

fn main() {
    let code_snippet = r#"
    // --extern-html-root should take precedence if `--takes-precedence` is passed
    // @has - '//a/@href' 'https://example.com/core/0.1.0/core/iter/index.html'
    #[doc(no_inline)]
    pub use std::iter;
    "#;

    let code_info = extract_code_info(code_snippet);
    println!("{:?}", code_info);
}
