```csharp
using System;
using System.Collections.Generic;

public interface IBinding
{
    Type InterfaceType { get; }
    Type ImplementationType { get; }
    bool IsSingleton { get; }
    object Instance { get; }
}

public class Binding<TInterface> : IBinding
{
    public Type InterfaceType => typeof(TInterface);
    public Type ImplementationType { get; private set; }
    public bool IsSingleton { get; private set; }
    public object Instance { get; private set; }

    public Binding<TInterface> To<TImplementation>()
    {
        ImplementationType = typeof(TImplementation);
        return this;
    }

    public Binding<TInterface> InSingletonScope()
    {
        IsSingleton = true;
        return this;
    }

    public void SetInstance(object instance)
    {
        Instance = instance;
    }
}

public class DependencyInjector
{
    private readonly Dictionary<Type, IBinding> bindings = new Dictionary<Type, IBinding>();

    public Binding<TInterface> Bind<TInterface>()
    {
        var binding = new Binding<TInterface>();
        bindings[typeof(TInterface)] = binding;
        return binding;
    }

    public TInterface Resolve<TInterface>()
    {
        if (bindings.TryGetValue(typeof(TInterface), out var binding))
        {
            if (binding.IsSingleton && binding.Instance != null)
            {
                return (TInterface)binding.Instance;
            }
            else
            {
                var instance = (TInterface)Activator.CreateInstance(binding.ImplementationType);
                if (binding.IsSingleton)
                {
                    binding.SetInstance(instance);
                }
                return instance;
            }
        }
        else
        {
            throw new InvalidOperationException($"No binding found for interface {typeof(TInterface)}");
        }
    }
}

// Usage
public interface ICashierService
{
    void ProcessPayment(double amount);
}

public class CashierService : ICashierService
{
    public void ProcessPayment(double amount)
    {
        Console.WriteLine($"Processing payment of {amount}");
    }
}

public class Program
{
    public static void Main()
    {
        var injector = new DependencyInjector();
        injector.Bind<ICashierService>()
            .To<CashierService>()
            .InSingletonScope();

        var cashierService1 = injector.Resolve<ICashierService>();
        var cashierService2 = injector.Resolve<ICashierService>();

        cashierService1.ProcessPayment(100.0);
        cashierService2.ProcessPayment(200.0);

        // Output:
        // Processing payment of 100
        // Processing payment of 200
    }
}
```

In this solution, we define an `IBinding` interface and a `Binding<TInterface>` class to represent the binding between an interface and its concrete implementation. The `DependencyInjector` class manages the bindings and resolves instances based on the bindings. The `Bind<TInterface>()` method creates a new binding, and the `To<TImplementation>()` and `InSingletonScope()` methods configure the binding. The `Resolve<TInterface>()` method resolves an instance of the bound interface, creating a new instance or returning a singleton instance based on the binding configuration. Finally, we demonstrate the usage of the dependency injection container with the `ICashierService` and `CashierService` example.

