fn is_prime(num: i32) -> bool {
    if num <= 1 {
        return false;
    }
    for i in 2..=(num as f64).sqrt() as i32 {
        if num % i == 0 {
            return false;
        }
    }
    true
}

fn sum_of_primes(start: i32, end: i32) -> i32 {
    let mut sum = 0;
    for num in start..=end {
        if is_prime(num) {
            sum += num;
        }
    }
    sum
}

fn main() {
