#include <vector>

class CircularBuffer {
private:
    std::vector<int> buffer;
    int capacity;
    int readIndex;
    int writeIndex;
    bool full;

public:
    CircularBuffer(int capacity) : capacity(capacity), readIndex(0), writeIndex(0), full(false) {
        buffer.resize(capacity, -1); // Initialize buffer with -1
    }

    void write(int value) {
        buffer[writeIndex] = value;
        writeIndex = (writeIndex + 1) % capacity; // Update write index with wrap-around
        if (writeIndex == readIndex) {
            readIndex = (readIndex + 1) % capacity; // Update read index if buffer is full
            full = true;
        }
    }

    int read() {
        if (readIndex == writeIndex && !full) {
            return -1; // Buffer is empty
        }
        int value = buffer[readIndex];
        readIndex = (readIndex + 1) % capacity; // Update read index with wrap-around
        full = false;
        return value;
    }
};
