struct CustomDataStructure {
    let arg: String
    let force: Bool?
    let quiet: Bool?
}

func parseArguments(_ arguments: [String]) throws -> CustomDataStructure {
    var arg: String?
    var force: Bool?
    var quiet: Bool?

    var index = 0
    while index < arguments.count {
        let currentArg = arguments[index]
        switch currentArg {
        case "-arg":
            guard index + 1 < arguments.count else {
                throw ArgumentParsingError.missingValueForArgument("-arg")
            }
            arg = arguments[index + 1]
            index += 1
        case "-force":
            force = true
        case "-quiet":
            quiet = true
        default:
            throw ArgumentParsingError.invalidArgument(currentArg)
        }
        index += 1
    }

    guard let parsedArg = arg else {
        throw ArgumentParsingError.missingArgument("-arg")
    }

    return CustomDataStructure(arg: parsedArg, force: force, quiet: quiet)
}

enum ArgumentParsingError: Error {
    case missingArgument(String)
    case missingValueForArgument(String)
    case invalidArgument(String)
}
