class SlicedImage:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def sliceImage(self, inputFileName, outputFileName):
        try:
            original_image = Image.open(inputFileName)
            x_slices = self.width // 100  # Assuming 100 as the width of sub-images
            y_slices = self.height // 100  # Assuming 100 as the height of sub-images
            for i in range(x_slices):
                for j in range(y_slices):
                    left = i * 100
                    upper = j * 100
                    right = (i + 1) * 100
                    lower = (j + 1) * 100
                    sub_image = original_image.crop((left, upper, right, lower))
                    sub_image.save(f"{outputFileName}_{i}_{j}.png")
            return True
        except FileNotFoundError:
            print("Input file not found.")
            return False
        except Exception as e:
            print(f"An error occurred: {e}")
            return False

def makeSlices(width, height, inputFileName, outputFileName):
