from hat_trie import Trie
from dawg import BytesDAWG

def generate_lookup_entries(w, max_edit_distance=0):
    """given a word, derive strings with up to max_edit_distance characters
       deleted"""
    result = {w}
    queue = {w}
    for d in range(max_edit_distance):
        temp_queue = set()
        for word in queue:
            if len(word) > 1:
                for c in range(len(word)):  # character index
                    word_minus_c = word[:c] + word[c + 1:]
                    temp_queue.add(word_minus_c)
        result.update(temp_queue)
        queue = temp_queue
    return result

def spell_checker(dictionary, word, max_distance):
    trie = Trie()
    for w in dictionary:
        entries = generate_lookup_entries(w, max_distance)
        for entry in entries:
            trie[entry] = True

    result = []
    entries = generate_lookup_entries(word, max_distance)
    for entry in entries:
        if entry in trie:
            result.append(entry)

    return result
```

