import java.util.Stack;

public class HTMLValidator {
    public static boolean isValidHTML(String html) {
        Stack<String> stack = new Stack<>();

        for (int i = 0; i < html.length(); i++) {
            if (html.charAt(i) == '<') {
                if (html.charAt(i + 1) == '/') {
                    int closeIndex = html.indexOf('>', i);
                    String tag = html.substring(i + 2, closeIndex);
                    if (!stack.isEmpty() && stack.peek().equals(tag)) {
                        stack.pop();
                    } else {
                        return false;
                    }
                    i = closeIndex;
                } else {
                    int closeIndex = html.indexOf('>', i);
                    String tag = html.substring(i + 1, closeIndex);
                    stack.push(tag);
                    i = closeIndex;
                }
            }
        }

        return stack.isEmpty();
    }

    public static void main(String[] args) {
        System.out.println(isValidHTML("<div><p></p></div>")); // true
        System.out.println(isValidHTML("<div><p></div></p>")); // false
    }
}
