class DownloadManager {
  private downloads: Map<string, { url: string, status: 'downloading' | 'paused', progress: number }> = new Map();

  startDownload(url: string, fileName: string): void {
    if (!this.downloads.has(fileName)) {
      this.downloads.set(fileName, { url, status: 'downloading', progress: 0 });
      // Simulate download URL
      this.simulateDownload(url, fileName);
    }
  }

  pauseDownload(fileName: string): void {
    const download = this.downloads.get(fileName);
    if (download && download.status === 'downloading') {
      download.status = 'paused';
    }
  }

  resumeDownload(fileName: string): void {
    const download = this.downloads.get(fileName);
    if (download && download.status === 'paused') {
      download.status = 'downloading';
      // Simulate download URL
      this.simulateDownload(download.url, fileName);
    }
  }

  cancelDownload(fileName: string): void {
    this.downloads.delete(fileName);
  }

  getDownloadProgress(fileName: string): number {
    const download = this.downloads.get(fileName);
    return download ? download.progress : 0;
