import pandas as pd

def keyword_analysis(excel_path, keyword_lists):
    # Read the Excel file
    data = pd.read_excel(excel_path)

    # Extract specific columns
    extracted_columns = data.iloc[:, [8, 9, 11, 12, 13]]

    # Initialize a dictionary to store keyword group counts
    keyword_counts = {tuple(keyword_group): 0 for keyword_group in keyword_lists}

    # Perform keyword analysis
    for index, row in extracted_columns.iterrows():
        for keyword_group in keyword_lists:
            for keyword in keyword_group:
                for column in extracted_columns.columns:
                    if keyword in str(row[column]).lower():
                        keyword_counts[tuple(keyword_group)] += 1
                        break

    return keyword_counts
