function isValidHTMLTags(input) {
    const stack = [];
    const tagRegex = /<\/?([a-zA-Z]+)>/g;
    let match;

    while ((match = tagRegex.exec(input)) !== null) {
        const tag = match[1].toLowerCase();
        if (tag.startsWith('/')) {
            if (stack.length === 0 || stack.pop() !== tag.substring(1)) {
                return false;
            }
        } else {
            stack.push(tag);
        }
    }

    return stack.length === 0;
}
```

