// Constants for J1939 identifier construction
const int J1939_DST_ADDR_MASK = 0xFF;
const int J1939_DST_ADDR_OFFSET = 8;
const int J1939_PGN_MASK = 0x3FFFF;
const int J1939_PGN_OFFSET = 8;
const int J1939_PRIORITY_OFFSET = 26;

// Enum for PDU format group
enum PDUFormatGroup {
    PDU_FORMAT_1,
    PDU_FORMAT_2
