def get_version_number(root, relative_to, fallback_version):
    import os
    import re

    file_path = os.path.join(root, relative_to)

    try:
        with open(file_path, 'r') as file:
            content = file.read()
            version_match = re.search(r'\b\d+\.\d+\.\d+\b', content)
            if version_match:
                return version_match.group()
            else:
                return fallback_version
    except FileNotFoundError:
        return fallback_version
    except Exception:
        return fallback_version
