def validate(imo_number):
    if imo_number.startswith('IMO '):
        imo_number = imo_number[4:]  # Extract the 7-digit number
    if len(imo_number) != 7 or not imo_number.isdigit():
        raise ValueError("Invalid IMO number format")

    check_digit = int(imo_number[-1])
    number_digits = [int(digit) for digit in imo_number[:-1]]

    for i in range(0, 6, 2):
        number_digits[i] *= 2
        if number_digits[i] > 9:
            number_digits[i] -= 9

    total = sum(number_digits)
    if (total + check_digit) % 10 != 0:
        raise ValueError("Invalid check digit")

    return imo_number
