#include <vector>
#include <queue>
#include <cmath>

std::pair<std::vector<size_t>, std::vector<int>> processHeap(const std::vector<int>& values, int k) {
    std::priority_queue<int, std::vector<int>, std::greater<int>> heap;

    for (int i = 0; i < k; i++) {
        heap.push(values[i]);
    }

    for (int i = k; i < values.size(); i++) {
        int val = values[i];
        if (std::abs(val) > std::abs(heap.top())) {
            heap.pop();
            heap.push(val);
        }
    }

    const size_t len = heap.size();
    std::vector<size_t> nzind(len);
    std::vector<int> nzval(len);

    for (size_t i = len; i > 0; i--) {
        nzind[i - 1] = i - 1;
        nzval[i - 1] = heap.top();
        heap.pop();
    }

    return std::make_pair(nzind, nzval);
}
```

