from flask import Flask, jsonify, request

def create_app():
    app = Flask(__name__)
    products = {
        "product1": {"name": "Product 1", "price": 10.0, "quantity": 100},
        "product2": {"name": "Product 2", "price": 20.0, "quantity": 50},
        "product3": {"name": "Product 3", "price": 15.0, "quantity": 75}
    }
    shopping_cart = {}

    @app.route('/products', methods=['GET'])
    def get_products():
        return jsonify(products)

    @app.route('/cart/add', methods=['POST'])
    def add_to_cart():
        data = request.get_json()
        product_name = data.get('name')
        quantity = data.get('quantity')
        if product_name in products and products[product_name]['quantity'] >= quantity:
            if product_name in shopping_cart:
                shopping_cart[product_name] += quantity
            else:
                shopping_cart[product_name] = quantity
            products[product_name]['quantity'] -= quantity
            return jsonify({"message": "Product added to cart successfully"})
        else:
            return jsonify({"error": "Invalid product or insufficient quantity"})

    @app.route('/cart/checkout', methods=['POST'])
    def checkout_cart():
        total_cost = 0
        for product, quantity in shopping_cart.items():
            total_cost += products[product]['price'] * quantity
            products[product]['quantity'] += quantity
        shopping_cart.clear()
        return jsonify({"message": f"Checkout successful. Total cost: ${total_cost:.2f}"})

    return app

