func calculateDistancesBetweenPoints(_ points: [SCNVector3]) -> [[Float]] {
    let n = points.count
    var distances = Array(repeating: Array(repeating: Float(0.0), count: n), count: n)

    for i in 0..<n {
        for j in 0..<n {
            let point1 = points[i]
            let point2 = points[j]
            let distance = sqrt(pow(point2.x - point1.x, 2) + pow(point2.y - point1.y, 2) + pow(point2.z - point1.z, 2))
            distances[i][j] = distance
        }
    }

    return distances
}
