        hueFilter?.setDefaults()
        hueFilter?.setValue(inputImage, forKey: kCIInputImageKey)
        hueFilter?.setValue(angle, forKey: kCIInputAngleKey)

        if let outputImage = hueFilter?.outputImage {
            return outputImage
        } else {
            // Return the original input image if the filter fails
            return inputImage
        }
    }
}

