    func saveItem(_ password: String) throws {
        let passwordData = password.data(using: .utf8)!

        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecValueData as String: passwordData
        ]

        let status = SecItemAdd(query as CFDictionary, nil)
        guard status == errSecSuccess else {
            throw KeychainError.saveError(status)
        }
    }

    func retrievePassword() -> String? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: kCFBooleanTrue!,
            kSecMatchLimit as String: kSecMatchLimitOne
        ]

        var dataTypeRef: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &dataTypeRef)

        guard status == errSecSuccess, let retrievedData = dataTypeRef as? Data else {
            return nil
        }

        return String(data: retrievedData, encoding: .utf8)
    }
}

enum KeychainError: Error {
    case saveError(OSStatus)
}

// Usage
let bundleID = "com.example.app"
let keychainItem = KeychainItem(service: bundleID, account: "userIdentifier")

do {
    try keychainItem.saveItem("securePassword123")
} catch (let error) {
    print(error)
}

let savedPassword = keychainItem.retrievePassword()
print("Retrieved password: \(savedPassword ?? "No password saved")")
```

In the solution, the KeychainItem class is implemented to securely save and retrieve passwords using the Keychain. The saveItem method uses the Security framework to add the password to the Keychain, and it throws a KeychainError in case of failure. The retrievePassword method retrieves the saved password from the Keychain. The usage example demonstrates how to handle errors when saving the password and retrieve the saved password from the Keychain.

