const fs = require('react-native-fs');

function manageDatabase(action) {
  const { FILE_NAME, BACKUP_FILE_NAME } = DATABASE;

  if (action === "backup") {
    return fs.copyFile(FILE_NAME, BACKUP_FILE_NAME)
      .then(() => {
        console.log("Database backup created successfully.");
      })
      .catch(error => {
        console.error("Error creating database backup:", error);
      });
