class Schwarzschild:
    def __init__(self, mass, ureg):
        self.mass = mass * ureg.Msolar
        self.ureg = ureg

    @property
    def mass(self):
        return self._mass

    @mass.setter
    def mass(self, value):
        self._mass = value.to_base_units()

    @property
    def ureg(self):
        return self._ureg

    @ureg.setter
    def ureg(self, value):
        self._ureg = value

    def schwarz(self):
        """ Find the Schwarzschild radius for the class """
        G = 6.67430e-11  # Gravitational constant in m^3 kg^-1 s^-2
        c = 3.00e8  # Speed of light in m/s
        rs = (2 * G * self.mass) / (c ** 2)
        return rs
