def parse_options(opts):
    parsed_options = {}
    i = 0
    while i < len(opts):
        opt = opts[i]
        if opt.startswith('--'):
            key = opt[2:]
            if i + 1 < len(opts) and not opts[i + 1].startswith('-'):
                parsed_options[key] = opts[i + 1]
                i += 1
            else:
                parsed_options[key] = True
        elif opt.startswith('-'):
