class Node:
    def __init__(self, node_type, content, refuri=None, children=None):
        self.node_type = node_type
        self.content = content
        self.refuri = refuri
        self.children = children if children is not None else []

def generate_toc(root_node):
    toc = []

    def process_node(node, indentlevel=0):
        if node.node_type == 'section':
            link = node.refuri
            title = htmlescape(node.content).replace('"', '&quot;')
            item = f"{' ' * 4 * indentlevel}* [{title}]({link})"
            toc.append(item)
        elif node.node_type == 'bullet_list':
            for subnode in node.children:
                process_node(subnode, indentlevel + 1)
        elif node.node_type == 'compact_paragraph':
            # Handle compact paragraph node type
            pass

    process_node(root_node)
    return '\n'.join(toc)

# Example usage
