public class DVDMgr {
    private ArrayList<DVD> dvdCollection;
    private Scanner scanner;

    public DVDMgr() {
        dvdCollection = new ArrayList<>();
        scanner = new Scanner(System.in);
    }

    public void initial() {
        // Already implemented: Initializes the DVD management system by creating an empty collection of DVDs.
    }

    public void startMenu() {
        int choice;
        do {
            System.out.println("DVD Management System Menu:");
            System.out.println("1. Add a DVD");
            System.out.println("2. Remove a DVD");
            System.out.println("3. Display all DVDs");
            System.out.println("4. Exit");
            System.out.print("Enter your choice: ");
            choice = scanner.nextInt();
            scanner.nextLine(); // Consume the newline character

            switch (choice) {
                case 1:
                    System.out.print("Enter DVD title: ");
                    String title = scanner.nextLine();
                    System.out.print("Enter director: ");
                    String director = scanner.nextLine();
                    System.out.print("Enter release year: ");
                    int releaseYear = scanner.nextInt();
                    addDVD(title, director, releaseYear);
                    break;
                case 2:
                    System.out.print("Enter DVD title to remove: ");
                    String titleToRemove = scanner.nextLine();
                    removeDVD(titleToRemove);
                    break;
                case 3:
                    displayDVDs();
                    break;
                case 4:
                    System.out.println("Exiting DVD Management System. Goodbye!");
                    break;
                default:
                    System.out.println("Invalid choice. Please try again.");
            }
        } while (choice != 4);
    }

    public void addDVD(String title, String director, int releaseYear) {
        DVD newDVD = new DVD(title, director, releaseYear);
        dvdCollection.add(newDVD);
        System.out.println("DVD added successfully: " + title);
    }

    public void removeDVD(String title) {
        for (DVD dvd : dvdCollection) {
            if (dvd.getTitle().equalsIgnoreCase(title)) {
                dvdCollection.remove(dvd);
                System.out.println("DVD removed successfully: " + title);
                return;
            }
        }
        System.out.println("DVD not found: " + title);
    }

    public void displayDVDs() {
        if (dvdCollection.isEmpty()) {
            System.out.println("No DVDs in the collection.");
        } else {
            System.out.println("DVD Collection:");
            for (DVD dvd : dvdCollection) {
                System.out.println(dvd);
            }
        }
    }

    public static void main(String[] args) {
        DVDMgr dm = new DVDMgr();
        dm.initial();
        dm.startMenu();
    }
}

