        self.voter_access = {}  # Dictionary to store voter access to places
        self.voted_voters = set()  # Set to store voted voters
        self.places_capacity = [PLACES_TO_ACCESS_VOTING] * PLACES_TO_ACCESS_VOTING  # List to track places capacity

    def grant_access_to_place(self, voter_id, place_id):
        if voter_id in self.voter_access or voter_id in self.voted_voters:
            return False  # Voter has already been granted access or has already voted
        if self.places_capacity[place_id] > 0:
            self.voter_access[voter_id] = place_id
            self.places_capacity[place_id] -= 1
            return True  # Access granted successfully
        else:
            return False  # Place is at full capacity

    def has_voted(self, voter_id):
        return voter_id in self.voted_voters
