// Define a generic Lazy class to encapsulate lazy initialization logic
class Lazy<T> {
    private let initializer: () -> T
    private var value: T?

    init(initializer: @escaping () -> T) {
        self.initializer = initializer
    }

    // Access the service, ensuring it is lazily initialized and reused for subsequent accesses
    func get() -> T {
        if let value = value {
            return value
        } else {
            let newValue = initializer()
            value = newValue
            return newValue
        }
    }
}

// Usage example
class AppDeepLinkService: DeepLinkService {
    // Implementation of DeepLinkService
}

// Usage of Lazy class to lazily initialize DeepLinkService
let deepLinkLazy = Lazy {
    return AppDeepLinkService()
}

// Access the DeepLinkService using the lazy initialization mechanism
let deepLinkService = deepLinkLazy.get()
```

