def processBuildConfig(build_config: str) -> dict:
    config_dict = {
        "resource_directories": [],
        "asset_directories": [],
        "dependencies": [],
        "default_config": "",
        "manifest_chunk": "",
        "permissions_chunk": ""
    }

    lines = build_config.split("\n")
    for line in lines:
        if line.startswith("env.android_add_res_dir"):
            directory = line.split("(")[1].split(")")[0].strip('\"')
            config_dict["resource_directories"].append(directory)
        elif line.startswith("env.android_add_asset_dir"):
            directory = line.split("(")[1].split(")")[0].strip('\"')
            config_dict["asset_directories"].append(directory)
        elif line.startswith("env.android_add_dependency"):
            dependency = line.split("(")[1].split(")")[0].strip('\"')
            config_dict["dependencies"].append(dependency)
        elif line.startswith("env.android_add_default_config"):
            config = line.split("(")[1].split(")")[0].strip()
            config_dict["default_config"] = config
        elif line.startswith("env.android_add_to_manifest"):
            manifest_chunk = line.split("(")[1].split(")")[0].strip()
            config_dict["manifest_chunk"] = manifest_chunk
        elif line.startswith("env.android_add_to_permissions"):
            permissions_chunk = line.split("(")[1].split(")")[0].strip()
            config_dict["permissions_chunk"] = permissions_chunk

    return config_dict
```

The `processBuildConfig` function parses the input build configuration string and populates the `config_dict` with the extracted information. It iterates through each line of the input, identifies the type of configuration command, and extracts the relevant data into the appropriate fields of the dictionary. Finally, it returns the structured representation of the build configuration.

