pub struct ResourceStorage(HashMap<String, ResourceInner>);

impl ResourceStorage {
    /// Create a new ResourceStorage instance
    pub fn new() -> Self {
        ResourceStorage(HashMap::new())
    }

    /// Insert a resource with the provided logical id.
    pub fn set<R: Resource>(&mut self, id: &str, resource: R) {
        let inner = ResourceInner {
            tag: std::any::type_name::<R>().to_owned(),
            properties: serde_json::to_value(resource.properties()).unwrap()
        };
        self.0.insert(id.to_owned(), inner);
    }

    /// Retrieve a resource by its logical ID
    pub fn get(&self, id: &str) -> Option<&ResourceInner> {
        self.0.get(id)
