// Define the CustomCollection struct
pub struct CustomCollection<T> {
    elements: Vec<T>,
}

// Implement methods for CustomCollection
impl<T> CustomCollection<T> {
    // Create a new empty CustomCollection
    pub fn new() -> Self {
        CustomCollection { elements: Vec::new() }
    }

    // Add an item to the collection
    pub fn add(&mut self, item: T) {
        self.elements.push(item);
    }

    // Remove the first occurrence of the specified item from the collection
    pub fn remove(&mut self, item: &T) {
        if let Some(index) = self.elements.iter().position(|x| x == item) {
            self.elements.remove(index);
        }
    }

    // Return an iterator over the elements in the collection
    pub fn iter(&self) -> Iter<'_, T> {
        self.elements.iter()
    }
}

// Define the Iter struct to support iterating over the elements
pub struct Iter<'a, T> {
    iter: std::slice::Iter<'a, T>,
}

// Implement methods for Iter
impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<Self::Item> {
        self.iter.next()
    }
}

