import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class SimpleCache {
    private Map<String, String> cacheMap;
    private AtomicLong cacheHits;

    public SimpleCache() {
        cacheMap = new ConcurrentHashMap<>();
        cacheHits = new AtomicLong(0);
    }

    public void put(String key, String value) {
        cacheMap.put(key, value);
    }

    public String get(String key) {
        String value = cacheMap.get(key);
        if (value != null) {
            cacheHits.incrementAndGet();
        }
        return value;
    }

    public void remove(String key) {
        cacheMap.remove(key);
    }

    public long getCacheHits() {
        return cacheHits.get();
    }
}
```

This solution provides a simple cache system implemented in Java using ConcurrentHashMap for thread safety and AtomicLong to track cache hits. The cache supports insertion, retrieval, removal, and tracking of cache hits.

