            std::string logMessage = getTimestamp() + " " + logLevelToString(level) + ": " + message;
            if (outputToConsole) {
                std::cout << logMessage << std::endl;
            }
            if (outputToFile) {
                logToFile(logMessage);
            }
            if (!serverAddress.empty()) {
                logToServer(logMessage);
            }
        }
    }

