```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* prev;
    struct Node* next;
    void* tmp;
};

typedef struct Node Node;

void unmarkEndAndBegin(Node* head) {
    if (head == NULL) {
        return; // Empty list
    }

    Node* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    // Set tmp pointer of the last node to NULL
    current->tmp = NULL;

    // Reset current to head
    current = head;
    // Set tmp pointer of the first node to NULL
    current->tmp = NULL;
}
```

