void customSort(std::vector<int>& a) {
    bool change = true;
    while (change) {
        change = false;
        for (int i = 0; i < a.size() - 1; i++) {
            if (a[i] > a[i + 1]) {
                std::swap(a[i], a[i + 1]);
                change = true;
            }
        }
        if (change) {
            sleep();
        }
    }
}
