```typescript
import { Injectable, OnDestroy } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, Subscription } from 'rxjs';
import { map } from 'rxjs/operators';

@Injectable()
export class Cie10Service implements OnDestroy {
  private lastRequest: Subscription;

  constructor(private plex: Plex, private httpClient: HttpClient) {}

  fetchDiagnosticCodes(query: string): Observable<string[]> {
    const url = `https://api.cie10.com/diagnostic-codes?query=${query}`;

    // Cancel any previous request before making a new one
    if (this.lastRequest && !this.lastRequest.closed) {
      this.lastRequest.unsubscribe();
    }

    this.lastRequest = this.httpClient.get(url).pipe(
      map((response: any) => {
        // Process the response to extract the diagnostic codes
        return response.data.map((item: any) => item.code);
      })
    ).subscribe(
      (codes: string[]) => {
        // Process the retrieved diagnostic codes
        console.log('Retrieved diagnostic codes:', codes);
      },
      (error: any) => {
        // Handle error from the API request
        console.error('Error fetching diagnostic codes:', error);
      }
    );

    return this.lastRequest;
  }

  ngOnDestroy() {
    if (this.lastRequest && !this.lastRequest.closed) {
      this.lastRequest.unsubscribe();
    }
  }
}
```

