```cpp
#include <vector>

class CircularBuffer {
private:
    std::vector<int> buffer;
    int capacity;
    int front;
    int rear;
    int size;

public:
    CircularBuffer(int capacity) : capacity(capacity), front(0), rear(0), size(0) {
        buffer.resize(capacity, -1);
    }

    bool isEmpty() {
        return size == 0;
    }

    bool isFull() {
        return size == capacity;
    }

    void enqueue(int value) {
        if (isFull()) {
            front = (front + 1) % capacity;  // Overwrite the oldest element
        } else {
            size++;
        }
        buffer[rear] = value;
        rear = (rear + 1) % capacity;
    }

    int dequeue() {
        if (isEmpty()) {
            return -1;
        } else {
            int value = buffer[front];
            front = (front + 1) % capacity;
            size--;
            return value;
        }
    }
};
```

