def perform_operation(graph: Dict[int, List[int]], identifier: str, input_vertex_id: int, data: List[str]) -> Dict[int, List[int]]:
    if identifier == "i":
        if input_vertex_id in graph:
            new_vertex_id = input_vertex_id + 1
            graph[new_vertex_id] = graph.pop(input_vertex_id)
            for vertex, edges in graph.items():
                graph[vertex] = [new_vertex_id if x == input_vertex_id else x for x in edges]
    elif identifier == "f":
        if input_vertex_id in graph:
            graph[input_vertex_id] = [int(val) for val in data]
    return graph
