```typescript
function generateArrowCircleDownIcon(props: IconProps): string {
  const { width, height, fill, stroke, strokeWidth } = props;

  // Calculate the position and size of the circle and arrow
  const circleSize = Math.min(width, height);
  const circleCenterX = width / 2;
  const circleCenterY = height / 2;
  const arrowSize = circleSize * 0.6;
  const arrowX = circleCenterX - arrowSize / 2;
  const arrowY = circleCenterY - arrowSize / 2;

  // Generate the SVG code for the arrow inside a circle
  const svgCode = `
    <svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" xmlns="http://www.w3.org/2000/svg">
      <circle cx="${circleCenterX}" cy="${circleCenterY}" r="${circleSize / 2}" fill="${fill}" stroke="${stroke}" stroke-width="${strokeWidth}" />
      <path d="M${arrowX},${arrowY + arrowSize / 2} L${arrowX + arrowSize},${arrowY + arrowSize / 2} L${arrowX + arrowSize / 2},${arrowY + arrowSize * 0.8} Z" fill="none" stroke="${fill}" stroke-width="${strokeWidth}" />
    </svg>
  `;

  return svgCode;
}
```

This solution calculates the position and size of the circle and arrow based on the provided `IconProps`, then generates the SVG code for the arrow inside a circle using the calculated values. The resulting SVG code represents an arrow inside a circle based on the input icon properties.

