class FileSystem:
    def __init__(self):
        self.root = {'type': 'directory', 'contents': {}}
        self.current_directory = self.root

    def create_directory(self, path):
        directories = path.split('/')[1:]
        current = self.root
        for directory in directories:
            if directory not in current['contents']:
                current['contents'][directory] = {'type': 'directory', 'contents': {}}
            current = current['contents'][directory]

    def create_file(self, path, content):
        directories = path.split('/')[1:-1]
        file_name = path.split('/')[-1]
        current = self.root
        for directory in directories:
            current = current['contents'][directory]
        current['contents'][file_name] = {'type': 'file', 'content': content}

    def list_directory_contents(self, path):
        directories = path.split('/')[1:]
        current = self.root
        for directory in directories:
            current = current['contents'][directory]
        return list(current['contents'].keys())

    def navigate_to_directory(self, path):
        directories = path.split('/')[1:]
        current = self.root
        for directory in directories:
            current = current['contents'][directory]
        self.current_directory = current
