import socket
import os

class HTTPServer:
    def __init__(self, port):
        self.port = port
        self.host = '127.0.0.1'
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(1)

    def serve_file(self, file_path):
        try:
            with open(file_path, 'rb') as file:
                return file.read()
        except FileNotFoundError:
            return b'File Not Found'

    def handle_request(self, request):
        request_lines = request.split(b'\r\n')
        request_line = request_lines[0].decode('utf-8')
        method, path, _ = request_line.split(' ')

        if method == 'GET':
            file_path = path.lstrip('/')
            response = self.serve_file(file_path)
            if response:
                return b'HTTP/1.1 200 OK\r\n\r\n' + response
            else:
                return b'HTTP/1.1 404 Not Found\r\n\r\nFile Not Found'
        else:
            return b'HTTP/1.1 501 Not Implemented\r\n\r\nMethod Not Implemented'

# Test Case
def test_http_server():
    server = HTTPServer(8080)
    response = server.handle_request(b'GET /index.html HTTP/1.1\r\nHost: localhost\r\n\r\n')
