use libc::{c_void, size_t};
use std::mem;

extern "C" {
    fn getrandom(buf: *mut c_void, buflen: size_t, flags: u32) -> isize;
}

pub struct OsRng;

impl OsRng {
    pub fn new() -> Self {
        OsRng
    }

    pub fn next_u32(&self) -> u32 {
        let mut random_bytes: [u8; 4] = [0; 4];
        unsafe {
            if getrandom(
                random_bytes.as_mut_ptr() as *mut c_void,
                4,
                0, // No special flags
            ) != 4
            {
                panic!("Failed to obtain random bytes");
            }
        }
        u32::from_ne_bytes(random_bytes)
    }
}

