import UIKit

protocol GLBaseTableViewDelegate: AnyObject {
    func didSelectCell(at indexPath: IndexPath)
    // Add any other required delegate methods here
}

class GLBaseTableView: UIScrollView {
    weak var glDelegate: GLBaseTableViewDelegate?

    var numberOfRows: Int = 0
    var numberOfColumns: Int = 0
    var cellSize: CGSize = CGSize(width: 100, height: 100)

    private var reusableCells: [String: [UIView]] = [:]
    private var visibleCells: [UIView] = []

    func reloadData() {
        // Remove all visible cells
        visibleCells.forEach { $0.removeFromSuperview() }
        visibleCells.removeAll()

        // Calculate content size based on number of rows and columns
        let contentWidth = CGFloat(numberOfColumns) * cellSize.width
        let contentHeight = CGFloat(numberOfRows) * cellSize.height
        contentSize = CGSize(width: contentWidth, height: contentHeight)

        // Create and layout cells
        for row in 0..<numberOfRows {
            for column in 0..<numberOfColumns {
                let indexPath = IndexPath(row: row, column: column)
                let cell = dequeueReusableCell(withIdentifier: "CellIdentifier", for: indexPath)
                cell.frame = CGRect(x: CGFloat(column) * cellSize.width, y: CGFloat(row) * cellSize.height, width: cellSize.width, height: cellSize.height)
                addSubview(cell)
                visibleCells.append(cell)
            }
        }
    }

    func dequeueReusableCell(withIdentifier identifier: String, for indexPath: IndexPath) -> UIView {
        if let reusableCell = reusableCells[identifier]?.popLast() {
            // Reuse existing cell
            return reusableCell
        } else {
            // Create new cell
            let newCell = UIView()
            newCell.backgroundColor = .lightGray
            return newCell
        }
    }

    override func layoutSubviews() {
        super.layoutSubviews()

        // Update visible cells' frames during scrolling
        for cell in visibleCells {
            let cellFrameInSuperview = convert(cell.frame, to: superview)
            if bounds.intersects(cellFrameInSuperview) {
                // Cell is visible, no action needed
            } else {
                // Cell is not visible, reuse or remove it
                cell.removeFromSuperview()
                if let identifier = cell.reuseIdentifier {
                    reusableCells[identifier, default: []].append(cell)
                }
            }
        }
    }

    override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
        super.touchesEnded(touches, with: event)

        // Handle cell selection
        if let touch = touches.first {
            let location = touch.location(in: self)
            for cell in visibleCells {
                if cell.frame.contains(location) {
                    if let index = visibleCells.firstIndex(of: cell) {
                        let row = index / numberOfColumns
                        let column = index % numberOfColumns
                        glDelegate?.didSelectCell(at: IndexPath(row: row, column: column))
                    }
                    break
                }
            }
        }
    }
}
```

This solution provides a custom table view component `GLBaseTableView` that supports both horizontal and vertical scrolling, allows specifying the number of rows and columns, and supports reusing cells for memory optimization. It also includes a delegate protocol for handling cell selection and customizing cell appearance. The `reloadData` method calculates the content size and creates/positions cells, while the `dequeueReusableCell` method manages cell reusability. The `layoutSubviews` method updates visible cells' frames during scrolling, and the `touchesEnded` method handles cell selection based on touch location.

