- `data`: The fetched data of type `T`.
- `isLoading`: A boolean indicating whether the data is currently being fetched.
- `children`: The component or function to render with the fetched data.
- `error`: An object representing any error that occurred during the fetch.
- `loadingComponent`: An optional component to render while the data is being fetched.

Your task is to complete the implementation of the `FetchHandler` component, ensuring that it correctly handles the different states (loading, error, and success) and renders the appropriate UI based on these states.

You should use TypeScript for this implementation and ensure that the component is generic, allowing it to handle different types of fetched data.

```typescript
import React from 'react'

interface IApiError {
  // Define the structure of the API error object
}

interface IFetchHandlerProps<T> {
  data?: T
  isLoading: boolean
  children: JSX.Element | JSX.Element[] | ((data: T) => JSX.Element)
  error: IApiError | null
  loadingComponent?: JSX.Element | JSX.Element[]
}

const FetchHandler = <T extends any>({
  isLoading,
  data,
  children,
  error,
  loadingComponent,
}: IFetchHandlerProps<T>): JSX.Element => {
  if (isLoading) {
    return loadingComponent || <CircularProgress />; // Render the loading component or default CircularProgress
  }

  if (error) {
    return <FetchError error={error} />; // Render the FetchError component with the error object
  }

  if (typeof children === 'function') {
    return (children as (data: T) => JSX.Element)(data as T); // If children is a function, call it with the data
  }

  return <>{children}</>; // Render the children as JSX elements
}

export default FetchHandler;
