import os
import sys

def replace_header(source_header_path, target_directory, file_pattern):
    try:
        with open(source_header_path, 'r') as source_file:
            header_content = source_file.read()

        for root, _, files in os.walk(target_directory):
            for file in files:
                if file.endswith(file_pattern):
                    file_path = os.path.join(root, file)
                    with open(file_path, 'r') as target_file:
                        content = target_file.read()
                    content = content.split('\n', 1)[1]  # Remove existing header
                    with open(file_path, 'w') as target_file:
                        target_file.write(header_content + '\n' + content)

        print("Header replacement completed successfully.")

    except FileNotFoundError:
        print("File or directory not found.")
    except Exception as e:
        print("An error occurred:", e)

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python replace_header.py <source_header_path> <target_directory> <file_pattern>")
    else:
        source_header_path = sys.argv[1]
        target_directory = sys.argv[2]
        file_pattern = sys.argv[3]
        replace_header(source_header_path, target_directory, file_pattern)
```
