#include <string>
#include <vector>

std::string longestCommonPrefix(const std::vector<std::string>& strs) {
    if (strs.empty()) {
        return "";
    }

    std::string prefix = strs[0];
    for (const std::string& str : strs) {
        while (str.find(prefix) != 0) {
            prefix = prefix.substr(0, prefix.size() - 1);
            if (prefix.empty()) {
                return "";
            }
        }
    }
    return prefix;
}
```

The `longestCommonPrefix` function first checks if the input array is empty and returns an empty string if so. It then initializes the `prefix` with the first string in the array. It iterates through the array of strings and continuously updates the `prefix` by removing characters from the end until it becomes the longest common prefix among all strings. If at any point the `prefix` becomes empty, it means there is no common prefix, and the function returns an empty string. Finally, the function returns the longest common prefix found.

```cpp
#include <stack>
#include <string>

bool isBalancedBraces(std::string s) {
    std::stack<char> stack;
    for (char c : s) {
        if (c == '{') {
            stack.push(c);
        } else if (c == '}') {
            if (stack.empty() || stack.top() != '{') {
                return false;
            }
            stack.pop();
        }
    }
    return stack.empty();
}
```

