class ContentTypeGuard {
    public function contentTypeIsValid($contentType) {
        // Rule 1: It must start with "application/"
        if (strpos($contentType, 'application/') !== 0) {
            return false;
        }

        // Rule 2: It must contain at least one sub-type denoted by "+"
        if (strpos($contentType, '+') === false) {
            return false;
        }

        // Rule 3: It may optionally contain parameters separated by semicolons
        $contentTypeParts = explode(';', $contentType);
        $subType = explode('+', $contentTypeParts[0]);
        if (count($subType) < 2) {
            return false;
        }

        return true;
    }
}

