```typescript
function hsvToRgb(hsv: number[]): number[] {
  let h = hsv[0];
  let s = hsv[1];
  let v = hsv[2];
  let rgb: number[] = [0, 0, 0];

  let i = Math.floor(h * 6);
  let f = h * 6 - i;
  let p = v * (1 - s);
  let q = v * (1 - f * s);
  let t = v * (1 - (1 - f) * s);

  switch (i % 6) {
    case 0: rgb[0] = v, rgb[1] = t, rgb[2] = p; break;
    case 1: rgb[0] = q, rgb[1] = v, rgb[2] = p; break;
    case 2: rgb[0] = p, rgb[1] = v, rgb[2] = t; break;
    case 3: rgb[0] = p, rgb[1] = q, rgb[2] = v; break;
    case 4: rgb[0] = t, rgb[1] = p, rgb[2] = v; break;
    case 5: rgb[0] = v, rgb[1] = p, rgb[2] = q; break;
  }

  return rgb;
}

// Test the function
console.log(hsvToRgb([0.5, 1, 1])); // Output: [1, 0, 0] (represents pure red in RGB color space)
```

The `hsvToRgb` function takes an array of three numbers representing the HSV color values and returns an array of three numbers representing the corresponding RGB color values. It follows the logic provided in the code snippet to perform the conversion from HSV to RGB. The function first extracts the HSV components, calculates intermediate values, and then uses a switch statement to handle different cases based on the value of `h * 6`. Finally, it returns the resulting RGB color values.

