import requests

class GitHubRepoFetcher:
    def __init__(self, access_token):
        self.access_token = access_token

    def fetch_repositories(self, query, stars_range):
        min_stars, max_stars = map(int, stars_range.split('-'))
        headers = {
            'Authorization': f'token {self.access_token}'
        }
        params = {
            'q': query,
            'per_page': 10,  # Number of results per page
            'sort': 'stars',
            'order': 'desc',
            'q': f'stars:{min_stars}..{max_stars}'
        }
        response = requests.get('https://api.github.com/search/repositories', headers=headers, params=params)
        if response.status_code == 200:
            repositories = response.json()['items']
            result = []
            for repo in repositories:
                result.append({
                    'name': repo['name'],
                    'url': repo['html_url'],
                    'stars': repo['stargazers_count']
                })
            return result
        else:
            raise Exception(f'Failed to fetch repositories: {response.status_code} - {response.text}')

# Example usage
