function calculatePagination(pagination, PAGINATION_OFFSET) {
    let start = pagination.currentPage - PAGINATION_OFFSET;
    let diff = 0;
    if (start < 1) {
        diff = Math.abs(start) + 1;
        start = 1;
    }
    let end = (start === 1
        ? pagination.currentPage + PAGINATION_OFFSET + diff
        : pagination.currentPage + PAGINATION_OFFSET);
    return { start, end };
}
```

