class UniqueStack:
    def __init__(self):
        self.stack = []
        self.unique_set = set()

    def push(self, value):
        if value not in self.unique_set:
            self.stack.append(value)
            self.unique_set.add(value)

    def pop(self):
        if self.stack:
            value = self.stack.pop()
            self.unique_set.remove(value)
            return value
        return None

    def peek(self):
        if self.stack:
            return self.stack[-1]
        return None

    def is_empty(self):
        return len(self.stack) == 0
```

