class BinaryTree:
    def __init__(self, root):
        self.root = Node(root)

    def remove_children(self, value):
        self._remove_children_helper(self.root, value)

    def _remove_children_helper(self, current, value):
        if current is None:
            return
        if current.left and current.left.value == value:
            current.left = None
        if current.right and current.right.value == value:
            current.right = None
        self._remove_children_helper(current.left, value)
        self._remove_children_helper(current.right, value)
```

