    public partial class ImagePreviewView : UserControl
    {
        private double _scale = 1.0;
        private Point _origin;
        private Point _start;

        public string ImagePath
        {
            get { return (string)GetValue(ImagePathProperty); }
            set { SetValue(ImagePathProperty, value); }
        }

        public static readonly DependencyProperty ImagePathProperty =
            DependencyProperty.Register("ImagePath", typeof(string), typeof(ImagePreviewView), new PropertyMetadata(string.Empty, OnImagePathChanged));

        public ImagePreviewView()
        {
            InitializeComponent();
        }

        private static void OnImagePathChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
        {
            if (d is ImagePreviewView imagePreviewView && e.NewValue is string imagePath)
            {
                imagePreviewView.LoadImage(imagePath);
            }
        }

        private void LoadImage(string imagePath)
        {
            if (!string.IsNullOrEmpty(imagePath))
            {
                BitmapImage bitmap = new BitmapImage(new Uri(imagePath));
                ImageControl.Source = bitmap;
            }
        }

        private void ImageControl_MouseWheel(object sender, MouseWheelEventArgs e)
        {
            if (e.Delta > 0)
            {
                _scale *= 1.1;
            }
            else
            {
                _scale /= 1.1;
            }

            Matrix matrix = ImageControl.RenderTransform.Value;
            matrix.ScaleAtPrepend(_scale, _scale, _origin.X, _origin.Y);
            ImageControl.RenderTransform = new MatrixTransform(matrix);
        }

        private void ImageControl_MouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            ImageControl.CaptureMouse();
            _start = e.GetPosition(this);
            _origin.X = ImageControl.RenderTransform.Value.OffsetX;
            _origin.Y = ImageControl.RenderTransform.Value.OffsetY;
        }

        private void ImageControl_MouseLeftButtonUp(object sender, MouseButtonEventArgs e)
        {
            ImageControl.ReleaseMouseCapture();
        }

        private void ImageControl_MouseMove(object sender, MouseEventArgs e)
        {
            if (ImageControl.IsMouseCaptured)
            {
                Point p = e.MouseDevice.GetPosition(this);
                Matrix matrix = ImageControl.RenderTransform.Value;
                matrix.OffsetX = _origin.X + (p.X - _start.X);
                matrix.OffsetY = _origin.Y + (p.Y - _start.Y);
                ImageControl.RenderTransform = new MatrixTransform(matrix);
            }
        }

        private void ResetButton_Click(object sender, RoutedEventArgs e)
        {
            _scale = 1.0;
            ImageControl.RenderTransform = new MatrixTransform(Matrix.Identity);
        }
    }
}
