from collections import deque

class StackQueue:
    def __init__(self):
        self.stack = []
        self.queue = deque()

    def push(self, item):
        self.stack.append(item)

    def pop(self):
        if not self.stack:
            while self.queue:
                self.stack.append(self.queue.pop())
        return self.stack.pop()

    def peek(self):
        if not self.stack:
            while self.queue:
                self.stack.append(self.queue.pop())
        return self.stack[-1]

    def enqueue(self, item):
        self.queue.appendleft(item)

    def dequeue(self):
        if not self.stack:
            return self.queue.pop()
        else:
            while self.stack:
                self.queue.appendleft(self.stack.pop())
            return self.queue.pop()
```

The `StackQueue` class is implemented using a list as a stack and a deque as a queue. The `push` and `pop` methods are used for stack operations, while the `enqueue` and `dequeue` methods are used for queue operations. The `peek` method is implemented to return the top element of the stack without removing it. The implementation ensures that the specified operations are supported efficiently.

