function calculateFinalPosition(initialPosition, cssStyles) {
  let finalPosition = { ...initialPosition };

  if (cssStyles.position === 'absolute') {
    if (cssStyles.left) {
      finalPosition.x = initialPosition.x - parseInt(cssStyles.left);
    }
    if (cssStyles.right) {
      finalPosition.x = initialPosition.x + parseInt(cssStyles.right);
    }
    if (cssStyles.top) {
      finalPosition.y = initialPosition.y - parseInt(cssStyles.top);
    }
    if (cssStyles.bottom) {
      finalPosition.y = initialPosition.y + parseInt(cssStyles.bottom);
    }
  }

  return finalPosition;
}
```

