use std::fs;

fn load_file(file_path: &str) -> String {
    fs::read_to_string(file_path)
        .expect("Failed to read file")
}

mod day1 {
    pub fn part1(input: &str) -> i32 {
        let mut floor = 0;
        for c in input.chars() {
            if c == '(' {
                floor += 1;
            } else if c == ')' {
                floor -= 1;
            }
        }
        floor
    }
}

fn main() {
    let base_path = "/path/to/input/files/";
    println!(
        "Solution of Day 1, Part 1: {}",
        day1::part1(&load_file(&(base_path.to_string() + "day1.txt")))
    );
}
```

In this solution, the `load_file` function uses the `fs::read_to_string` method to read the content of the file specified by the file path. The `day1::part1` function calculates the final floor level based on the input string, where '(' indicates going up one floor and ')' indicates going down one floor. The `main` function demonstrates how to use these functions to print the solution for Day 1, Part 1.

