class TaskScheduler {
    var willResignActiveTask: (() -> Void)?
    var didEnterBackgroundTask: (() -> Void)?
    var willEnterForegroundTask: (() -> Void)?

    func taskForWillResignActive(_ task: @escaping () -> Void) {
        willResignActiveTask = task
    }

    func taskForDidEnterBackground(_ task: @escaping () -> Void) {
        didEnterBackgroundTask = task
    }

    func taskForWillEnterForeground(_ task: @escaping () -> Void) {
        willEnterForegroundTask = task
    }

    func applicationWillResignActive() {
        willResignActiveTask?()
    }

    func applicationDidEnterBackground() {
        didEnterBackgroundTask?()
    }

    func applicationWillEnterForeground() {
        willEnterForegroundTask?()
    }
}

// Example usage
let taskScheduler = TaskScheduler()
taskScheduler.taskForWillResignActive {
    print("Pausing ongoing tasks and disabling timers")
}
taskScheduler.taskForDidEnterBackground {
    print("Releasing shared resources and saving user data")
}
taskScheduler.taskForWillEnterForeground {
    print("Undoing changes made during background state")
}

// Simulate application state transitions
taskScheduler.applicationWillResignActive()
taskScheduler.applicationDidEnterBackground()
taskScheduler.applicationWillEnterForeground()
