using Microsoft.Extensions.DependencyInjection;
using Microsoft.Azure.Cosmos;
using System;

public class CosmosDBServiceOperationProvider
{
    private readonly CosmosClient _cosmosClient;
    private readonly Database _database;
    private readonly Container _container;

    public CosmosDBServiceOperationProvider(string connectionString, string databaseName, string containerName)
    {
        _cosmosClient = new CosmosClient(connectionString);
        _database = _cosmosClient.CreateDatabaseIfNotExistsAsync(databaseName).Result;
        _container = _database.CreateContainerIfNotExistsAsync(containerName, "/partitionKey").Result;
    }

    public async Task<T> GetItemAsync<T>(string id, string partitionKey)
    {
        try
        {
            ItemResponse<T> response = await _container.ReadItemAsync<T>(id, new PartitionKey(partitionKey));
            return response.Resource;
        }
        catch (CosmosException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return default(T);
        }
    }

    public async Task<T> CreateItemAsync<T>(T item, string partitionKey)
    {
        ItemResponse<T> response = await _container.CreateItemAsync<T>(item, new PartitionKey(partitionKey));
        return response.Resource;
    }

    public async Task<T> UpdateItemAsync<T>(string id, T item, string partitionKey)
    {
        ItemResponse<T> response = await _container.ReplaceItemAsync<T>(item, id, new PartitionKey(partitionKey));
        return response.Resource;
    }

    public async Task DeleteItemAsync(string id, string partitionKey)
    {
        await _container.DeleteItemAsync<object>(id, new PartitionKey(partitionKey));
    }
}

