def extractValue(json_obj: dict, path: str) -> any:
    keys = path.split('.')  # Split the path into individual keys
    current = json_obj  # Start with the entire JSON object

    for key in keys:
        if isinstance(current, dict) and key in current:
            current = current[key]  # Move to the next level in the JSON object
        else:
            return None  # Path does not exist, return None

    return current  # Return the value located at the specified path
```

