```python
from typing import List, Dict, Union, Any, Set

def filter_tree(tree: List[Dict[str, Union[int, List[Dict[str, Any]]]], selected_ids: Set[int]) -> List[Dict[str, Union[int, List[Dict[str, Any]]]]:
    filtered_replies = []

    for subtree in tree:
        filtered_subtree = filter_subtree(subtree, selected_ids)

        if filtered_subtree is not None:
            filtered_replies.append(filtered_subtree)

    return filtered_replies

def filter_subtree(node: Dict[str, Union[int, List[Dict[str, Any]]]], selected_ids: Set[int]) -> Dict[str, Union[int, List[Dict[str, Any]]]]:
    if node['id'] in selected_ids:
        filtered_children = [filter_subtree(child, selected_ids) for child in node['children']]
        return {"id": node['id'], "children": filtered_children}
    else:
        return None
```

