class ApplyMask(ApplyMaskBase):
    def apply_mask(self, input_data, mask_type, *args, **kwargs):
        if mask_type == "binary":
            bit_position = kwargs.get('bit_position')
            if bit_position is None:
                raise ValueError("bit_position is required for binary mask")
            return input_data ^ (1 << bit_position)  # Applying binary mask using XOR operation

        elif mask_type == "decimal":
            decimal_value = kwargs.get('decimal_value')
            if decimal_value is None:
                raise ValueError("decimal_value is required for decimal mask")
            return input_data & decimal_value  # Applying decimal mask using bitwise AND operation

        elif mask_type == "custom":
            if not args:
                raise ValueError("custom_mask is required for custom mask")
            custom_mask = args[0]
            return input_data | custom_mask  # Applying custom mask using bitwise OR operation

        else:
            raise ValueError("Unsupported mask_type")

# Example usage
apply_mask_obj = ApplyMask()
print(apply_mask_obj.apply_mask(10, "binary", bit_position=2))  # Output: 14 (10 ^ 2 = 14)
print(apply_mask_obj.apply_mask(10, "decimal", decimal_value=5))  # Output: 0 (10 & 5 = 0)
print(apply_mask_obj.apply_mask(10, "custom", 3))  # Output: 11 (10 | 3 = 11)
```

