import java.io.StringReader;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class PackageLicenseAnalyzer {

    public Map<String, Map<String, List<String>>> analyzePackageLicenses(String pomXmlContent) {
        Map<String, Map<String, List<String>>> licenseSummary = new HashMap<>();

        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(new InputSource(new StringReader(pomXmlContent)));

            NodeList dependencyNodes = document.getElementsByTagName("dependency");
            for (int i = 0; i < dependencyNodes.getLength(); i++) {
                Element dependencyElement = (Element) dependencyNodes.item(i);
                String groupId = dependencyElement.getElementsByTagName("groupId").item(0).getTextContent();
                String artifactId = dependencyElement.getElementsByTagName("artifactId").item(0).getTextContent();
                String version = dependencyElement.getElementsByTagName("version").item(0).getTextContent();
                String license = "Unknown";
                if (dependencyElement.getElementsByTagName("license").getLength() > 0) {
                    license = dependencyElement.getElementsByTagName("license").item(0).getTextContent();
                }

                licenseSummary.computeIfAbsent(license, k -> new HashMap<>())
                        .computeIfAbsent(groupId + ":" + artifactId + ":" + version, k -> List.of())
                        .add(groupId + ":" + artifactId + ":" + version);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return licenseSummary;
    }

    public static void main(String[] args) {
        String pomXmlContent = "<project>\n" +
                "    <dependencies>\n" +
                "        <dependency>\n" +
                "            <groupId>org.springframework</groupId>\n" +
                "            <artifactId>spring-core</artifactId>\n" +
                "            <version>5.2.8.RELEASE</version>\n" +
                "            <license>Apache License, Version 2.0</license>\n" +
                "        </dependency>\n" +
                "        <dependency>\n" +
                "            <groupId>junit</groupId>\n" +
                "            <artifactId>junit</artifactId>\n" +
                "            <version>4.12</version>\n" +
                "            <license>Eclipse Public License - v 1.0</license>\n" +
                "        </dependency>\n" +
                "        <dependency>\n" +
                "            <groupId>com.google.guava</groupId>\n" +
                "            <artifactId>guava</artifactId>\n" +
                "            <version>29.0-jre</version>\n" +
                "            <license>Apache-2.0</license>\n" +
                "        </dependency>\n" +
                "        <dependency>\n" +
                "            <groupId>org.apache.commons</groupId>\n" +
                "            <artifactId>commons-lang3</artifactId>\n" +
                "            <version>3.11</version>\n" +
                "        </dependency>\n" +
                "    </dependencies>\n" +
                "</project>";

        PackageLicenseAnalyzer analyzer = new PackageLicenseAnalyzer();
        Map<String, Map<String, List<String>>> result = analyzer.analyzePackageLicenses(pomXmlContent);
        result.forEach((license, dependencies) -> {
            System.out.println(license + ":");
            dependencies.forEach((dependency, versions) -> {
                System.out.println("\t" + dependency + " - " + versions.stream().collect(Collectors.joining(", ")));
            });
        });
    }
}
