from typing import List

def file_manager(file_paths: List[str], commands: List[str]) -> List[str]:
    current_directory = file_paths  # Start with the initial list of file paths

    for command in commands:
        if command.startswith('cd'):
            directory = command.split(' ')[1]
            current_directory = [path for path in current_directory if path.startswith(directory+'/')]
        elif command == 'ls':
            print(current_directory)
        elif command == 'sort':
            current_directory.sort()
        elif command.startswith('head'):
            num = int(command.split(' ')[-1])
            current_directory = current_directory[:num]
        elif command.startswith('tail'):
            num = int(command.split(' ')[-1])
            current_directory = current_directory[-num:]
        elif command.startswith('rm -f'):
            file_to_remove = command.split(' ')[-1]
            current_directory = [path for path in current_directory if path != file_to_remove]

    return current_directory
