#include <iostream>
#include <unordered_map>

enum class tok {
  plusplus,
  plusequal,
  minus,
  arrow,
  minusminus,
  minusequal,
  tilde,
  exclaim,
  exclaimequal,
  slash,
  slashequal,
  percent,
  percentequal
};

std::string getTokenString(tok tokenType) {
  static const std::unordered_map<tok, std::string> tokenMap = {
    {tok::plusplus, "++"},
    {tok::plusequal, "+="},
    {tok::minus, "-"},
    {tok::arrow, "->"},
    {tok::minusminus, "--"},
    {tok::minusequal, "-="},
    {tok::tilde, "~"},
    {tok::exclaim, "!"},
    {tok::exclaimequal, "!="},
    {tok::slash, "/"},
    {tok::slashequal, "/="},
    {tok::percent, "%"},
    {tok::percentequal, "%="}
  };

  auto it = tokenMap.find(tokenType);
  if (it != tokenMap.end()) {
    return it->second;
  } else {
    return "Unknown token type";
  }
}

int main() {
