fn transform_data_to_sql_insert(batch: Vec<Tag>) -> String {
    let mut buffer = String::new();
    buffer.push_str("INSERT INTO tags(id, ts, value) FORMAT TabSeparated\n");
    for tag in batch {
        buffer.push_str(format!("{}\t{}\t{}\n",
                                tag.id,
                                tag.timestamp as f64 / 1e3,
                                tag.value)
                            .as_str());
    }
    buffer.pop(); // Remove the trailing newline
    buffer
}

