class Account {
    let accountNumber: Int
    var balance: Double
    let name: String

    init(accountNumber: Int, name: String, initialBalance: Double) {
        self.accountNumber = accountNumber
        self.name = name
        self.balance = initialBalance
    }
}

class BankingSystem {
    var accounts: [Int: Account]
    var nextAccountNumber: Int

    init() {
        accounts = [:]
        nextAccountNumber = 1
    }

    func createAccount(name: String, initialBalance: Double) -> Int {
        let newAccountNumber = nextAccountNumber
        let newAccount = Account(accountNumber: newAccountNumber, name: name, initialBalance: initialBalance)
        accounts[newAccountNumber] = newAccount
        nextAccountNumber += 1
        return newAccountNumber
    }

    func deposit(accountNumber: Int, amount: Double) -> Bool {
        if let account = accounts[accountNumber] {
            account.balance += amount
            return true
        }
        return false
    }

    func withdraw(accountNumber: Int, amount: Double) -> Bool {
        if let account = accounts[accountNumber], account.balance >= amount {
            account.balance -= amount
            return true
        }
        return false
    }

    func transfer(fromAccount: Int, toAccount: Int, amount: Double) -> Bool {
        if let from = accounts[fromAccount], let to = accounts[toAccount], from.balance >= amount {
            from.balance -= amount
            to.balance += amount
            return true
        }
        return false
    }

    func getAccountBalance(accountNumber: Int) -> Double {
        return accounts[accountNumber]?.balance ?? 0.0
    }
}
