import os
from typing import List

class FileSystem:
    def __init__(self):
        self.current_directory = os.getcwd()

    def create_file(self, file_name: str) -> str:
        file_path = os.path.join(self.current_directory, file_name)
        try:
            open(file_path, 'a').close()
            return f"File '{file_name}' created successfully."
        except Exception as e:
            return f"Failed to create file '{file_name}': {str(e)}"

    def create_directory(self, dir_name: str) -> str:
        dir_path = os.path.join(self.current_directory, dir_name)
        try:
            os.makedirs(dir_path, exist_ok=True)
            return f"Directory '{dir_name}' created successfully."
        except Exception as e:
            return f"Failed to create directory '{dir_name}': {str(e)}"

    def list_contents(self) -> List[str]:
        contents = os.listdir(self.current_directory)
        return contents

    def change_directory(self, dir_name: str) -> str:
        new_dir = os.path.join(self.current_directory, dir_name)
        if os.path.exists(new_dir) and os.path.isdir(new_dir):
            self.current_directory = new_dir
            return f"Changed directory to '{dir_name}'."
        else:
            return f"Failed to change directory to '{dir_name}': Directory does not exist."

    def trace_system_calls(self, operation: str) -> List[str]:
        # Simulated system calls for demonstration purposes
        if operation == "create_file":
            return ["open", "write", "close"]
        elif operation == "create_directory":
            return ["mkdir"]
        elif operation == "list_contents":
            return ["readdir"]
        elif operation == "change_directory":
            return ["chdir"]
        else:
            return []

def main():
    fs = FileSystem()
    print(fs.create_file("example.txt"))
    print(fs.create_directory("docs"))
    print(fs.list_contents())
    print(fs.change_directory("docs"))
    print(fs.list_contents())
    print(fs.trace_system_calls("create_file"))
    print(fs.trace_system_calls("create_directory"))
    print(fs.trace_system_calls("list_contents"))
    print(fs.trace_system_calls("change_directory"))

if __name__ == "__main__":
    main()
```

