#include <vector>

namespace ex {
    class buffer {
    private:
        std::vector<int> data;
        size_t size;
        size_t readIndex;
        size_t writeIndex;
        bool full;

    public:
        buffer(size_t size) : data(size), size(size), readIndex(0), writeIndex(0), full(false) {}

        void write(int value) {
            data[writeIndex] = value;
            writeIndex = (writeIndex + 1) % size;
            if (full) {
                readIndex = (readIndex + 1) % size;
            }
            if (writeIndex == readIndex) {
                full = true;
            }
        }

        int read() {
            if (readIndex == writeIndex && !full) {
                return -1;  // Buffer is empty
            }
            int value = data[readIndex];
            readIndex = (readIndex + 1) % size;
            full = false;
            return value;
        }
    };
}
