from typing import List

def calculate_unique_answers(lines: List[str]) -> int:
    total_unique_answers = 0
    group_answers = set()

    for line in lines:
        if line == "\n":
            total_unique_answers += len(group_answers)
            group_answers = set()
        else:
            for answer in line.strip("\n"):
                group_answers.add(answer)

