import datetime

class Commit:
    def __init__(self, commit_id, message):
        self.commit_id = commit_id
        self.message = message
        self.timestamp = datetime.datetime.now()

class VersionControlSystem:
    def __init__(self):
        self.commit_history = []

    def commit(self, message):
        commit_id = len(self.commit_history) + 1
        new_commit = Commit(commit_id, message)
        self.commit_history.append(new_commit)

    def checkout(self, commit_id):
        if commit_id <= len(self.commit_history):
            self.commit_history = self.commit_history[:commit_id]

    def log(self):
        for commit in self.commit_history:
            print(f"Commit ID: {commit.commit_id}, Message: {commit.message}, Timestamp: {commit.timestamp}")

# Example usage
vcs = VersionControlSystem()
vcs.commit("Initial commit")
vcs.commit("Add feature A")
vcs.log()
vcs.checkout(1)
vcs.log()
```

