import ast

def extract_metadata(file_path):
    with open(file_path, 'r') as file:
        setup_code = file.read()

    setup_dict = {}
    setup_ast = ast.parse(setup_code)

    for node in setup_ast.body:
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call) and node.value.func.id == 'setup':
            for keyword in node.value.keywords:
                if keyword.arg:
                    if isinstance(keyword.value, ast.Str):
                        setup_dict[keyword.arg] = keyword.value.s
                    elif isinstance(keyword.value, ast.List):
                        setup_dict[keyword.arg] = [elem.s for elem in keyword.value.elts]
                    elif isinstance(keyword.value, ast.NameConstant) and keyword.value.value is not None:
                        setup_dict[keyword.arg] = keyword.value.value
                    # Handle long_description as a special case
                    elif keyword.arg == 'long_description' and isinstance(keyword.value, ast.Str):
                        setup_dict[keyword.arg] = keyword.value.s.strip()

    return setup_dict
```

The `extract_metadata` function reads the setup.py file, parses it using the `ast` module, and extracts the metadata fields into a dictionary. It handles different data types for the metadata fields and ensures that the long description is properly formatted.

