from typing import List
import itertools

def get_seat_layout_from_file(file_path="../../resources/year2020_day11_input.txt"):
    with open(file_path) as f:
        return string_to_seat_layout(f.read())

def simulate_seating(seat_layout: List[List[str]]) -> List[List[str]]:
    directions = [pos for pos in itertools.product((-1, 0, +1), repeat=2) if pos != (0, 0)]
    rows, cols = len(seat_layout), len(seat_layout[0])

    def count_occupied_adjacent_seats(row, col):
        count = 0
        for dr, dc in directions:
            r, c = row + dr, col + dc
            if 0 <= r < rows and 0 <= c < cols and seat_layout[r][c] == '#':
                count += 1
        return count

    def apply_rules_and_update_layout():
        new_layout = [row[:] for row in seat_layout]
        for r in range(rows):
            for c in range(cols):
                if seat_layout[r][c] == 'L' and count_occupied_adjacent_seats(r, c) == 0:
                    new_layout[r][c] = '#'
                elif seat_layout[r][c] == '#' and count_occupied_adjacent_seats(r, c) >= 4:
                    new_layout[r][c] = 'L'
        return new_layout

    while True:
        new_seat_layout = apply_rules_and_update_layout()
        if new_seat_layout == seat_layout:
            return new_seat_layout
        seat_layout = new_seat_layout
