# util.py

import numpy as np

def rms(data):
    return np.sqrt(np.mean(data**2))

def moving_average(data, window_size):
    return np.convolve(data, np.ones(window_size)/window_size, mode='valid')

def moving_avg_conv(data, window_size):
    return np.convolve(data, np.ones(window_size)/window_size, mode='same')

def moving_avg_fft(data, window_size):
    kernel = np.ones(window_size)/window_size
    return np.fft.ifft(np.fft.fft(data) * np.fft.fft(kernel)).real

def normalize(data):
    mean = np.mean(data)
    std = np.std(data)
    return (data - mean) / std

def next_pow2(num):
    return 2**int(np.ceil(np.log2(num)))

def top_and_tail(data, top, tail):
    return data[top:-tail]

def extrapolate(data, n, degree):
    x = np.arange(len(data))
    p = np.polyfit(x, data, degree)
    extended_x = np.arange(len(data), len(data) + n)
    return np.polyval(p, extended_x)
```

