import datetime

class BankAccount:
    def __init__(self, account_holder, initial_balance):
        self.account_holder = account_holder
        self.balance = initial_balance
        self.daily_withdrawal_total = 0
        self.daily_withdrawal_limit = None
        self.last_transaction_date = datetime.date.today()

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        today = datetime.date.today()
        if today > self.last_transaction_date:
            self.daily_withdrawal_total = 0
            self.last_transaction_date = today

        if self.daily_withdrawal_limit is not None and self.daily_withdrawal_total + amount > self.daily_withdrawal_limit:
            return "Withdrawal limit exceeded"
        else:
            self.balance -= amount
            self.daily_withdrawal_total += amount
            return "Withdrawal successful"

    def get_balance(self):
        return self.balance

    def set_withdrawal_limit(self, limit):
        self.daily_withdrawal_limit = limit
