function findUnusedImports(declarations: string[], imports: string[]): string[] {
    const usedImports = new Set<string>();

    for (const declaration of declarations) {
        const regex = new RegExp(`${declaration},?`, 'g');
        for (const importName of imports) {
            if (regex.test(importName)) {
                usedImports.add(importName);
