class NodePatcher {
  key: string;
  expression: NodePatcher | null;

  constructor(patcherContext: PatcherContext, key: string, expression: NodePatcher) {
    this.key = key;
    this.expression = expression;
  }
}

class ConditionalNodePatcher extends NodePatcher {
  patchCondition(condition: NodePatcher): void {
    if (condition instanceof BinaryExpressionPatcher) {
      if (condition.operator === '&&') {
        condition.operator = 'and';
      } else if (condition.operator === '||') {
        condition.operator = 'or';
      }
