from typing import List, Tuple
from sympy import mod_inverse
from functools import reduce

class Shamir:
    @staticmethod
    def split_secret(secret: int, num_shares: int, threshold: int) -> List[Tuple[int, int]]:
        shares = []
        coefficients = [secret] + [randint(1, 100) for _ in range(threshold - 1)]
        for x in range(1, num_shares + 1):
            share = sum(coefficients[i] * (x ** i) for i in range(threshold)) % 257  # prime number for finite field
            shares.append((x, share))
        return shares

    @staticmethod
    def combine_shares(shares: List[Tuple[int, int]]) -> int:
        secret = 0
        for i, (x_i, y_i) in enumerate(shares):
            num = den = 1
            for j, (x_j, _) in enumerate(shares):
                if i != j:
                    num *= -x_j
                    den *= (x_i - x_j)
            secret += y_i * num * mod_inverse(den, 257)
        return int(secret) % 257

    @staticmethod
    def combine_shares_group(groups: List[List[Tuple[int, int]]]) -> int:
        secrets = [Shamir.combine_shares(group) for group in groups]
        moduli = [reduce(lambda x, y: x * y, [x[0] for x in group]) for group in groups]
        total_secret = sum(s * m * mod_inverse(m, p) for s, m, p in zip(secrets, moduli, [257] * len(groups)))
        return int(total_secret) % reduce(lambda x, y: x * y, [257] * len(groups))
```

