def generate_salary_summary(employee_records):
    department_salaries = {}
    department_counts = {}

    for record in employee_records:
        department = record["department"]
        salary = record["salary"]

        if department in department_salaries:
            department_salaries[department] += salary
            department_counts[department] += 1
        else:
            department_salaries[department] = salary
            department_counts[department] = 1

    summary_report = {}
    for department, total_salary in department_salaries.items():
        average_salary = total_salary / department_counts[department]
        summary_report[department] = average_salary

    return summary_report
