from django.core.exceptions import ValidationError
from django.db import models
from hashlib import sha256

from model_utils.models import TimeStampedModel

from .settings import FILE_LIMIT


def hash_upload(instance, filename):
    return 'uploads/{}/{}'.format(instance.user.id, filename)


class FileStorage(TimeStampedModel):
    user = models.ForeignKey(AUTH_USER_MODEL, on_delete=models.CASCADE)
    file = models.FileField(upload_to=hash_upload, validators=[FileExtensionValidator(allowed_extensions=['pdf', 'doc', 'docx'])])

