```typescript
function validatePassword(password: string): boolean {
  const minLength = 8;
  const specialChars = new Set(['!', '@', '#', '$', '%', '^', '&', '*']);

  if (password.length < minLength) {
    return false;
  }

  let hasUpperCase = false;
  let hasLowerCase = false;
  let hasDigit = false;
  let hasSpecialChar = false;

  for (const char of password) {
    if (char >= 'A' && char <= 'Z') {
      hasUpperCase = true;
    } else if (char >= 'a' && char <= 'z') {
      hasLowerCase = true;
    } else if (char >= '0' && char <= '9') {
      hasDigit = true;
    } else if (specialChars.has(char)) {
      hasSpecialChar = true;
    }
  }

  return hasUpperCase && hasLowerCase && hasDigit && hasSpecialChar;
}
```

The `validatePassword` function first checks if the password meets the minimum length requirement. Then, it iterates through each character of the password to check for the presence of uppercase letters, lowercase letters, digits, and special characters. If all criteria are met, the function returns `true`; otherwise, it returns `false`.

