import re

def validate_etcd_config(config_str: str) -> bool:
    config_params = {}
    for param in config_str.split()[1:]:
        key, value = param.split('=')
        config_params[key.strip('-')] = value

    if not config_params['data-dir'] or not config_params['name']:
        return False

    if not re.match(r'^https?://\S+', config_params['initial-advertise-peer-urls']):
        return False

    if not re.match(r'^https?://\S+', config_params['listen-peer-urls']):
        return False

    if not re.match(r'^https?://\S+', config_params['advertise-client-urls']):
        return False

    if not re.match(r'^https?://\S+', config_params['listen-client-urls']):
        return False

    if not re.match(r'^(\S+=https?://\S+)(,\S+=https?://\S+)*$', config_params['initial-cluster']):
        return False

    if config_params['initial-cluster-state'] not in ['new', 'existing']:
        return False

    if not config_params['initial-cluster-token']:
        return False

    return True
