public class Machine {
    public boolean displayUI;
    public boolean check;
    public int[] registers;
    public int pc;

    public Machine() {
        displayUI = true;
        check = false;
        registers = new int[16]; // Assuming 16 general-purpose registers
        pc = 0;
    }

    public void executeInstruction(String instruction) {
        String[] parts = instruction.split(" ");
        if (parts.length == 4 && parts[0].equals("ADD")) {
            int destReg = parseRegister(parts[1]);
            int srcReg1 = parseRegister(parts[2]);
            int srcReg2 = parseRegister(parts[3]);
            if (destReg != -1 && srcReg1 != -1 && srcReg2 != -1) {
                registers[destReg] = registers[srcReg1] + registers[srcReg2];
            }
        }
        // Add more cases for other instructions like SUB, MUL, etc.
    }

    public void displayState() {
        System.out.println("Register values:");
        for (int i = 0; i < registers.length; i++) {
            System.out.println("R" + i + ": " + registers[i]);
        }
        System.out.println("Program Counter (pc): " + pc);
    }

    private int parseRegister(String reg) {
        if (reg.startsWith("R") && reg.length() == 2) {
            int regNum = Character.getNumericValue(reg.charAt(1));
            if (regNum >= 0 && regNum < 16) {
                return regNum;
            }
        }
        return -1; // Invalid register
    }
}
