from typing import List

def findMedian(sizes: List[int]) -> float:
    sizes.sort()
    n = len(sizes)
    if n % 2 == 0:
        return (sizes[n // 2 - 1] + sizes[n // 2]) / 2
    else:
        return sizes[n // 2]
