You are given a class `QuickSort` that contains a method `quickSort` for sorting a vector of integers using the Quick Sort algorithm. The `quickSort` method takes three parameters: the vector of integers `nums`, the starting index `beg`, and the ending index `end`. Additionally, the class contains a method `swap` that takes a vector of integers `nums` and two indices `p` and `q`, and swaps the elements at those indices.

Your task is to implement the `quickSort` method using the Quick Sort algorithm and the `swap` method to sort the given vector of integers in non-decreasing order.

You need to write the `quickSort` method and use the `swap` method to sort the vector of integers in-place.

```cpp
#include <iostream>
#include <vector>

class QuickSort {
public:
    void quickSort(std::vector<int>& nums, int beg, int end) {
        if (beg < end) {
            int q = partition(nums, beg, end);
            quickSort(nums, beg, q - 1);
            quickSort(nums, q + 1, end);
        }
    }

private:
    int partition(std::vector<int>& nums, int beg, int end) {
        int pivot = nums[end];
        int i = beg - 1;
        for (int j = beg; j < end; j++) {
            if (nums[j] <= pivot) {
                i++;
                swap(nums, i, j);
            }
        }
        swap(nums, i + 1, end);
        return i + 1;
    }

    void swap(std::vector<int>& nums, int p, int q) {
        int tmp = nums[p];
        nums[p] = nums[q];
        nums[q] = tmp;
    }
};

int main() {
    std::vector<int> arr = {5, 2, 9, 1, 5, 6};
    QuickSort qs;
    qs.quickSort(arr, 0, arr.size() - 1);
    for (int num : arr) {
        std::cout << num << " ";
    }
    return 0;
}
```

