from typing import List

def is_descending(input_list: List[int], step: int) -> bool:
    if not isinstance(input_list, list):
        raise TypeError('\'input_list\' must be \'list\'')
    if not isinstance(step, int):
        raise TypeError('\'step\' must be \'int\'')

    if step > 0:
        return all(input_list[i] - input_list[i+1] >= 0 for i in range(len(input_list)-1))
    elif step < 0:
        return all(abs(input_list[i] - input_list[i+1]) >= abs(step) for i in range(len(input_list)-1))
    else:
        raise ValueError('\'step\' must be non-zero for descending order comparison')

# Test cases
