print(is_descending([7, 5, 3, 1], 2))   # Output: False
print(is_descending([7, 5, 3, 1], 0))   # Raises ValueError
print(is_descending("invalid", -2))      # Raises TypeError
print(is_descending([7, 5, 3, 1], "invalid"))  # Raises TypeError
