struct Camera {
    x: f64,
    y: f64,
    width: f64,
    height: f64,
}

impl Camera {
    fn new(x: f64, y: f64, width: f64, height: f64) -> Camera {
        Camera { x, y, width, height }
    }

    fn is_rect_within_view(&self, rect_x: f64, rect_y: f64, rect_width: f64, rect_height: f64) -> bool {
        let rect_right = rect_x + rect_width;
        let rect_bottom = rect_y + rect_height;
        let camera_right = self.x + self.width;
        let camera_bottom = self.y + self.height;

        rect_x >= self.x && rect_right <= camera_right && rect_y >= self.y && rect_bottom <= camera_bottom
    }
}

