    let x = 0.0;
    let y = 1.0;
    let width = 50.0;
    let height = 100.0;
    let camera = Camera::new(x, y, width, height);

    assert_eq!(camera.x, x);
    assert_eq!(camera.y, y);
    assert_eq!(camera.width, width);
    assert_eq!(camera.height, height);

