function parseSlugReference(slugReference, lang, type) {
  const conditionRegex = /_type == '(.+?)'/;
  const slugRegex = /slug\[(.+?)\]\.current/;

  const matchCondition = slugReference.match(conditionRegex);
  const matchSlug = slugReference.match(slugRegex);

  if (matchCondition && matchSlug) {
    const conditionType = matchCondition[1];
    const slugLang = matchSlug[1];

    if (conditionType === type) {
      return slugLang === lang ? `slug[${lang}].current` : 'slug.current';
    } else {
      return 'slug.current';
    }
  } else {
    return 'Invalid slugReference format';
  }
}
