class Cartesian:
    @staticmethod
    def product(set_a, set_b):
        return [[a, b] for a in set_a for b in set_b]

    @staticmethod
    def list_comprehension(set_a, set_b):
        return [[a, b] for a in set_a for b in set_b]

    @staticmethod
    def product_n(*args):
        if len(args) == 0:
            yield ()
        else:
            for result in Cartesian.product_n(*args[1:]):
                for item in args[0]:
                    yield (item,) + result
```

