class Job {
    private $status;

    public function __construct($initialStatus) {
        $this->status = $initialStatus;
    }

    public function updateStatus($newStatus) {
        if ($this->status === JobStatus::Open && $newStatus === JobStatus::InProgress) {
            $this->status = $newStatus;
        } elseif ($this->status === JobStatus::InProgress && $newStatus === JobStatus::Closed) {
            $this->status = $newStatus;
        } else {
            throw new Exception("Invalid status transition from " . $this->status . " to " . $newStatus);
        }
    }

    public function getStatus() {
        return $this->status;
    }
}

// Usage
$job = new Job(JobStatus::Open);
