try {
    $job->updateStatus(JobStatus::InProgress);
    echo "Updated status: " . $job->getStatus() . "\n";
    $job->updateStatus(JobStatus::Closed);
    echo "Updated status: " . $job->getStatus() . "\n";
    // Attempting an invalid transition
    $job->updateStatus(JobStatus::Open);
} catch (Exception $e) {
