public class BankingSystem {
    private Map<Integer, BankAccount> accounts;
    private int accountNumberCounter;

    public BankingSystem() {
        accounts = new HashMap<>();
        accountNumberCounter = 1;
    }

    public int createAccount(String accountHolderName, double initialBalance) {
        int accountNumber = accountNumberCounter++;
        BankAccount newAccount = new BankAccount(accountNumber, accountHolderName, initialBalance);
        accounts.put(accountNumber, newAccount);
        return accountNumber;
    }

    public void deposit(int accountNumber, double amount) {
        BankAccount account = accounts.get(accountNumber);
        if (account != null) {
            account.deposit(amount);
        } else {
            System.out.println("Account not found");
        }
    }

    public void withdraw(int accountNumber, double amount) {
        BankAccount account = accounts.get(accountNumber);
        if (account != null) {
            if (!account.withdraw(amount)) {
                System.out.println("Insufficient funds");
            }
        } else {
            System.out.println("Account not found");
        }
    }

    public void transfer(int fromAccountNumber, int toAccountNumber, double amount) {
        BankAccount fromAccount = accounts.get(fromAccountNumber);
        BankAccount toAccount = accounts.get(toAccountNumber);
        if (fromAccount != null && toAccount != null) {
            if (fromAccount.withdraw(amount)) {
                toAccount.deposit(amount);
            } else {
                System.out.println("Insufficient funds");
            }
        } else {
            System.out.println("Account not found");
        }
    }

    public double getBalance(int accountNumber) {
        BankAccount account = accounts.get(accountNumber);
        if (account != null) {
            return account.getBalance();
        } else {
            System.out.println("Account not found");
            return -1; // Indicates account not found
        }
    }
}
