func main() {
	index := make(map[string]bool)

	if len(os.Args) < 3 {
		fmt.Println("Usage: fi <command> <file_name>")
		return
	}

	command := os.Args[1]
	fileName := os.Args[2]

	switch command {
	case "add":
		index[fileName] = true
		fmt.Printf("%s added to index.\n", fileName)
	case "remove":
		if _, exists := index[fileName]; exists {
			delete(index, fileName)
			fmt.Printf("%s removed from index.\n", fileName)
		} else {
			fmt.Printf("%s is not in the index.\n", fileName)
		}
	case "list":
		fmt.Printf("Indexed files: %s\n", strings.Join(getKeys(index), ", "))
	default:
		fmt.Println("Invalid command.")
	}
}

func getKeys(m map[string]bool) []string {
