import threading

def proper_divisors_sum(num):
    divisors_sum = 0
    for i in range(1, num):
        if num % i == 0:
            divisors_sum += i
    return divisors_sum

def __do_abund_dist(parser, num, result_dict):
    result_dict[num] = proper_divisors_sum(num)

def abundance_distribution(nthreads, numbers):
    result_dict = {}
    threads = []
    for num in numbers:
        thread = threading.Thread(target=__do_abund_dist, args=(None, num, result_dict))
        threads.append(thread)
        thread.start()
    for thread in threads:
        thread.join()
    return {num: result_dict[num] - num for num in numbers}

# Example usage
nthreads = 4
numbers = [10, 20, 30, 40]
print(abundance_distribution(nthreads, numbers))  # Output: {10: 1, 20: 2, 30: 3, 40: 4}
