#include <vector>
#include <iostream>
#include <algorithm>

int minHeightShelves(std::vector<std::vector<int>>& vec, int shelf_width) {
    int n = vec.size();
    std::vector<int> dp(n + 1, 0);  // dp[i] represents the minimum height to place books from 0 to i-1
    for (int i = 0; i < n; ++i) {
        int width = 0, max_height = 0;
        for (int j = i; j < n; ++j) {
            width += vec[j][0];
            if (width > shelf_width) break;
            max_height = std::max(max_height, vec[j][1]);
            dp[j + 1] = (i == 0) ? max_height : std::min(dp[j + 1], dp[i] + max_height);
        }
    }
    return dp[n];
}

int main() {
    std::vector<std::vector<int>> vec = {{1,1},{2,3},{2,3},{1,1},{1,1},{1,1},{1,2}};
    int shelf_width = 4;
    std::cout << "min height : " << minHeightShelves(vec, shelf_width);
    return 0;
}
