const redis = require('redis');
const { promisify } = require('util');
const client = redis.createClient();

// Function to implement rate limiting for the resolver function
async function rateLimitResolver(resolver, ctx) {
    const key = `rate_limit:${ctx.userId}:${ctx.operationName}`; // Unique key for rate limiting based on user and operation
    const limit = 100; // Maximum number of requests allowed within the time window
    const windowSeconds = 60; // Time window in seconds

    const incrAsync = promisify(client.incr).bind(client);
    const expireAsync = promisify(client.expire).bind(client);
    const ttlAsync = promisify(client.ttl).bind(client);

    const currentRequests = await incrAsync(key); // Increment the request count and get the current value
    if (currentRequests === 1) {
        // Set the expiration time for the key if it's a new entry
        await expireAsync(key, windowSeconds);
    }

    const requestsLeft = limit - currentRequests; // Calculate the remaining requests
    const timeLeft = await ttlAsync(key); // Get the time left for the key to expire

    if (currentRequests <= limit) {
        // If the limit is not exceeded, invoke the resolver function and return its result
        return resolver(ctx);
    } else {
        // If the limit is exceeded, return a rate-limiting message
        return `Rate limit exceeded. Please try again in ${timeLeft} seconds. Requests left: ${requestsLeft}`;
    }
}

// Example usage of rateLimitResolver
async function resolverFunction(ctx) {
    // Your resolver function logic here
    return "Resolver function result";
}

// Usage of rateLimitResolver with the resolver function
rateLimitResolver(resolverFunction, { userId: "user123", operationName: "getUser" })
    .then(result => {
        console.log(result);
    })
    .catch(error => {
        console.error(error);
    });
```

In the solution, the `rateLimitResolver` function uses Redis to store and manage the request count for each user and operation. It increments the request count for a specific key and sets an expiration time for the key based on the defined time window. If the request count exceeds the limit, the function returns a rate-limiting message; otherwise, it invokes the resolver function and returns its result.

