use serde::de::DeserializeOwned;
use serde_json::Value;

struct RpcCaller {
    name: String,
    current: usize,
    arguments: Vec<Value>,
}

impl RpcCaller {
    fn new(name: &str) -> RpcCaller {
        RpcCaller {
            name: name.to_string(),
            current: 0,
            arguments: Vec::new(),
        }
    }

    fn call<T: DeserializeOwned>(&mut self, arg: T) -> Option<T> {
        if self.current < self.arguments.len() {
            let val = serde_json::from_value(std::mem::take(&mut self.arguments[self.current])).unwrap();
            self.current += 1;
            Some(val)
        } else {
            panic!("not enough arguments for rpc call {:?}", self.name);
        }
    }

    pub fn arg_opt<T: DeserializeOwned>(&mut self) -> Option<T> {
        if self.current < self.arguments.len() {
            let val = serde_json::from_value(std::mem::take(&mut self.arguments[self.current])).unwrap();
            self.current += 1;
            Some(val)
        } else {
            None
        }
    }
}

fn main() {
    let mut rpc_caller = RpcCaller::new("example_rpc");

    // Simulate adding arguments to the RPC caller
    rpc_caller.arguments.push(serde_json::json!(10));
    rpc_caller.arguments.push(serde_json::json!("hello"));

    // Make an RPC call with an argument
    let result1: Option<i32> = rpc_caller.call(0);
    println!("Result 1: {:?}", result1);  // Output: Result 1: Some(10)

    // Parse an optional argument
    let result2: Option<String> = rpc_caller.arg_opt();
    println!("Result 2: {:?}", result2);  // Output: Result 2: Some("hello")

    // Try to make an RPC call with insufficient arguments
    let result3: Option<i32> = rpc_caller.call(0);  // This will panic
}
```

