import re

def parse_credentials_file(file_path):
    access_key = None
    secret_key = None
    _spliter = r"\s*=\s*"
    _removal = re.compile(r"[\'\"\s\r]")

    with open(file_path, 'r') as credentials_file:
        for line in credentials_file:
            if line and not line.startswith("#"):
                data = re.split(_spliter, line)
                if line.startswith("access_key"):
                    access_key = _removal.sub("", data[1])
                if line.startswith("secret_key"):
                    secret_key = _removal.sub("", data[1])

    return {'access_key': access_key, 'secret_key': secret_key}
