class EmailServer:
    def __init__(self):
        self.inbox = []
        self.outbox = []

    def handle_inbox(self):
        while self.inbox:
            sender, content = self.inbox.pop(0)
            recipients = [message[0] for message in self.outbox]
            if sender in recipients:
                self.send_message(sender, content)
            else:
                for recipient, _ in self.outbox:
                    if recipient == "broadcast":
                        self.send_message(sender, content)
                    elif recipient == sender:
                        self.send_message(sender, content)
                        break

    def handle_outbox(self):
        if self.outbox:
            recipient, content = self.outbox.pop(0)
            print(f"Sending message to {recipient}: {content}")

    def send_message(self, recipient, content):
        self.outbox.append((recipient, content))

    def receive_message(self, sender, content):
        self.inbox.append((sender, content))

