func minIndicesToChange(_ s: String, _ words: [String]) -> Int {
    var map: [Character : [Int]] = [:]
    for (index, c) in s.enumerated() {
        map[c, default: []].append(index)
    }

    var result = 0
    for word in words {
        var indices = map[word.first!, default: []]
        var found = false
        for i in indices {
            if i + word.count <= s.count {
                let substring = s[s.index(s.startIndex, offsetBy: i)..<s.index(s.startIndex, offsetBy: i + word.count)]
                if substring == word {
                    found = true
                    break
                }
            }
        }
        if !found {
            result += word.count
        }
    }
    return result
}

