from sklearn.cluster import DBSCAN
import numpy as np

def run(data, epsilon=0.001, min_samples=200):
    X = np.array(data)
    clustering = DBSCAN(eps=epsilon, min_samples=min_samples).fit(X)
    labels = clustering.labels_

    res = {}
    for i, label in enumerate(labels):
