```java
public class AngleConverter {
    private double angleInRadians;

    public AngleConverter(double angleInRadians) {
        this.angleInRadians = angleInRadians;
    }

    public String toHMS() {
        double deg = angleInRadians * 180 / Math.PI;

        int hours = (int) Math.floor(deg / 15.0);
        double rest = deg - (hours * 15);

        double md = rest * 60.0 / 15;
        int min = (int) Math.floor(md);
        rest = rest - (min / 60.0 * 15);

        double sd = rest * 3600.0 / 15;
        int sec = (int) Math.round(sd);

        return hours + ":" + min + ":" + sec;
    }

    public static void main(String[] args) {
        AngleConverter angleConverter = new AngleConverter(2.0944);
        System.out.println(angleConverter.toHMS()); // Output: 2:5:40
    }
}
```

