You are tasked with implementing a breadth-first search algorithm to find the shortest path between two nodes in a graph. The graph is represented using an adjacency list. Your goal is to write a function that takes the graph, start node, and end node as input and returns the shortest path between the start and end nodes.

You are given the following code snippet as a starting point:

```cpp
#include <iostream>
#include <queue>
#include <vector>
#include <unordered_map>

std::vector<int> bfsShortestPath(const std::unordered_map<int, std::vector<int>>& graph, int start, int end) {
    std::queue<int> q;
    std::unordered_map<int, int> parent;
    std::unordered_map<int, bool> visited;

    q.push(start);
    visited[start] = true;

    while (!q.empty()) {
        int current = q.front();
        q.pop();

        if (current == end) {
            std::vector<int> path;
            while (current != start) {
                path.push_back(current);
                current = parent[current];
            }
            path.push_back(start);
            std::reverse(path.begin(), path.end());
            return path;
        }

        for (int neighbor : graph.at(current)) {
            if (!visited[neighbor]) {
                q.push(neighbor);
                visited[neighbor] = true;
                parent[neighbor] = current;
            }
        }
    }

    return {}; // If no path is found
}

int main() {
    std::unordered_map<int, std::vector<int>> graph = {
        {1, {2, 3}},
        {2, {1, 4, 5}},
        {3, {1, 6}},
        {4, {2, 7}},
        {5, {2, 7}},
        {6, {3, 8}},
        {7, {4, 5, 8}},
        {8, {6, 7}}
    };

    std::vector<int> shortestPath = bfsShortestPath(graph, 1, 8);
    for (int node : shortestPath) {
        std::cout << node << " ";
    }
    return 0;
}
```

