    $htmlContent = file_get_contents($filePath);

    // Use DOMDocument to parse the HTML content
    $dom = new DOMDocument();
    @$dom->loadHTML($htmlContent); // Suppress warnings for potentially malformed HTML

    // Find the div with class "fill"
    $fillDiv = $dom->getElementsByTagName('div')->item(0);
    if ($fillDiv && $fillDiv->getAttribute('class') === 'fill') {
        // Extract the text content within the "fill" div
        $fillContent = '';
        foreach ($fillDiv->childNodes as $node) {
            if ($node->nodeType === XML_TEXT_NODE) {
                $fillContent .= $node->wholeText;
            }
        }
        return trim($fillContent); // Return the extracted text content
    } else {
        return 'Error: <div class="fill"> not found in the HTML file';
    }
}

