class Logger:
    def __init__(self, file_only_logger, logger, single_log_map):
        self._file_only_logger = file_only_logger
        self.logger = logger
        self._single_log_map = single_log_map

    def single_write(self, x, level="info"):
        if x + "_" + level in self._single_log_map:
            if level in ["debug", "info", "warning", "error", "critical"]:
                if self._single_log_map[x + "_" + level] == "file_only":
                    getattr(self._file_only_logger, level)(str(x))
                else:
