using System;
using System.Collections.Generic;

public enum PickupType
{
    DollarBill,  // Corresponds to prefab name "DollarBill"
    Medkit,      // Corresponds to prefab name "Medkit"
    // ... other enum values
}

public class PickupMapper
{
    public Dictionary<PickupType, string> MapEnumToPrefabName()
    {
        Dictionary<PickupType, string> prefabMap = new Dictionary<PickupType, string>();
        PickupType[] enumValues = (PickupType[])Enum.GetValues(typeof(PickupType));
