    def __init__(self, name, children=None):
        super().__init__(name)
        self.children = children if children is not None else []

class Leaf(Treant):
    def __init__(self, name):
        super().__init__(name)

class Bundle:
    def __init__(self, components=None):
        self.components = components if components is not None else []

def discover(tree, component_type):
    discovered_components = []

    def _discover_helper(node, component_type):
        if isinstance(node, component_type):
            discovered_components.append(node)
        if isinstance(node, Tree):
            for child in node.children:
                _discover_helper(child, component_type)

    _discover_helper(tree, component_type)
    return discovered_components

class View:
    @staticmethod
    def display(components, format_type='default'):
        if format_type == 'default':
            for component in components:
                print(component.name)
        # Add support for other format types as needed
```

This solution provides the required classes and functions for working with tree-like data structures. The `Treant` class serves as the base class for all tree components, while `Tree` and `Leaf` represent the tree structure and leaf nodes, respectively. The `Bundle` class allows for the collection of tree components, and the `discover` function enables the discovery of specific components within a given tree. Finally, the `View` class offers a method for displaying tree components in a customizable format.

