function provideFeedback(sequence, guess) {
  const feedback = {
    correctPosition: [],
    inSequence: [],
    notInSequence: []
  };

  const sequenceMap = new Map();
  const guessMap = new Map();

  for (let i = 0; i < sequence.length; i++) {
    if (sequence[i] === guess[i]) {
      feedback.correctPosition.push(sequence[i]);
    } else {
      sequenceMap.set(sequence[i], sequenceMap.has(sequence[i]) ? sequenceMap.get(sequence[i]) + 1 : 1);
      guessMap.set(guess[i], guessMap.has(guess[i]) ? guessMap.get(guess[i]) + 1 : 1);
    }
  }

  for (let i = 0; i < guess.length; i++) {
    if (sequence[i] !== guess[i] && sequenceMap.has(guess[i]) && guessMap.get(guess[i]) > 0) {
      feedback.inSequence.push(guess[i]);
      guessMap.set(guess[i], guessMap.get(guess[i]) - 1);
    }
  }

  for (let color of guess) {
    if (!sequenceMap.has(color)) {
      feedback.notInSequence.push(color);
    }
  }

  return feedback;
}

