import java.util.Arrays;
import java.util.List;

public class Incident {
    private int incidentID;
    private String description;
    private String category;
    private String priority;

    public Incident(int incidentID, String description, String category, String priority) {
        this.incidentID = incidentID;
        this.description = description;
        this.category = category;
        this.priority = priority;
    }

    public void setIncidentID(int incidentID) {
        this.incidentID = incidentID;
    }

    public int getIncidentID() {
        return incidentID;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getDescription() {
        return description;
    }

    public void setCategory(String category) {
        this.category = category;
    }

    public String getCategory() {
        return category;
    }

    public void setPriority(String priority) {
        this.priority = priority;
    }

    public String getPriority() {
        return priority;
    }

    public boolean validateAttributes() {
        List<String> validCategories = Arrays.asList("Bug", "Feature Request", "Documentation", "Other");
        List<String> validPriorities = Arrays.asList("Low", "Medium", "High");

        return incidentID > 0 && !description.isEmpty() && validCategories.contains(category) && validPriorities.contains(priority);
    }

    public static void main(String[] args) {
        Incident incident = new Incident(1, "Issue with login functionality", "Bug", "High");
        System.out.println("Incident ID: " + incident.getIncidentID());
        System.out.println("Description: " + incident.getDescription());
        System.out.println("Category: " + incident.getCategory());
        System.out.println("Priority: " + incident.getPriority());

        System.out.println("Validating incident attributes...");
        if (incident.validateAttributes()) {
            System.out.println("Incident attributes are valid.");
        } else {
            System.out.println("Invalid incident attributes.");
        }
    }
}
