import re

class AsinNotFoundException(Exception):
    pass

def get_asin(url):
    if not url.startswith("https://www.amazon."):
        raise AsinNotFoundException("Invalid Amazon URL")

    asin_match = re.search(r'/([A-Z0-9]{10})(?:[/?]|$)', url)
    if asin_match:
        return asin_match.group(1)
    else:
        raise AsinNotFoundException("ASIN not found in the URL")

# Test cases
try:
    asin1 = get_asin("https://www.amazon.com/dp/B07H8MZC9C")
    print(asin1)  # Output: B07H8MZC9C
except AsinNotFoundException as e:
    print(e)

try:
    asin2 = get_asin("https://www.amazon.com/gp/product/B07H8MZC9C")
    print(asin2)  # Output: B07H8MZC9C
except AsinNotFoundException as e:
    print(e)

try:
    asin3 = get_asin("https://www.amazon.com/gp/")
    print(asin3)
except AsinNotFoundException as e:
    print(e)  # Output: ASIN not found in the URL

try:
    asin4 = get_asin("this is not even a URL")
    print(asin4)
except AsinNotFoundException as e:
    print(e)  # Output: Invalid Amazon URL
```

