```csharp
using System;
using System.Collections.Generic;

public class Category
{
    public int Id { get; set; }
    public string Name { get; set; }
}

public class CategoryManager
{
    private List<Category> categories;

    public CategoryManager()
    {
        categories = new List<Category>();
    }

    public Category CreateCategory(Category category)
    {
        if (category == null)
        {
            throw new ArgumentNullException(nameof(category), "Category object cannot be null.");
        }

        category.Id = GenerateUniqueId();
        categories.Add(category);
        return category;
    }

    public Category UpdateCategory(Category category)
    {
        if (category == null)
        {
            throw new ArgumentNullException(nameof(category), "Category object cannot be null.");
        }

        var existingCategory = categories.Find(c => c.Id == category.Id);
        if (existingCategory == null)
        {
            throw new InvalidOperationException($"Category with ID {category.Id} does not exist.");
        }

        existingCategory.Name = category.Name;
        return existingCategory;
    }

    public void DeleteCategory(int id)
    {
        var categoryToRemove = categories.Find(c => c.Id == id);
        if (categoryToRemove == null)
        {
            throw new InvalidOperationException($"Category with ID {id} does not exist.");
        }

        categories.Remove(categoryToRemove);
    }

    private int GenerateUniqueId()
    {
        int newId = 1;
        while (categories.Exists(c => c.Id == newId))
        {
            newId++;
        }
        return newId;
    }
}
```

This solution provides a complete implementation of the `CategoryManager` class with the required methods to manage categories effectively. It includes error handling for potential issues such as null input, non-existent categories, and generating unique identifiers.

