use serve::Server;
use serve::Request;
use serve::Response;
use std::fs;

fn serve_file(file_path: String, port: u16) {
    let server = Server::new(format!("127.0.0.1:{}", port));

    server.run(|request: Request| {
        match fs::read(&file_path) {
            Ok(contents) => {
                let response = Response::new(200, "OK", contents);
                response
            }
            Err(_) => {
                let response = Response::new(404, "Not Found", Vec::new());
                response
            }
        }
    });
}
```

