def folio(url, retry=0):
    '''Do HTTP GET on "url" & return results of calling result_producer on it.'''
    headers = {
        "x-okapi-token": config('FOLIO_OKAPI_TOKEN'),
        "x-okapi-tenant": config('FOLIO_OKAPI_TENANT_ID'),
    }

    for _ in range(retry + 1):
        try:
            response = requests.get(url, headers=headers)
            response.raise_for_status()  # Raise an exception for 4xx or 5xx status codes
            return result_producer(response.json())  # Assuming result_producer is a function that processes JSON response
        except requests.exceptions.RequestException as e:
            print(f"Request failed: {e}")
            if retry > 0:
                print(f"Retrying after 5 seconds...")
                time.sleep(5)
            else:
                break

    return None  # Return None if all retries fail
