import sys

def collatz(n):
    sequence = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        sequence.append(n)
    return sequence

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python collatz.py <number>")
    else:
        try:
            input_number = int(sys.argv[1])
            print(f"Calculating the collatz conjecture from the number {input_number}...")
            result_sequence = collatz(input_number)
            print("The results are in:", result_sequence)
        except ValueError:
            print("Invalid input. Please provide a valid integer.")
```

