import time

class meter:
    @staticmethod
    def runtime(REPORT_NAME):
        def decorator(func):
            def wrapper(*args, **kwargs):
                start_time = time.time()
                result = func(*args, **kwargs)
                end_time = time.time()
                execution_time = end_time - start_time
                print(f"{REPORT_NAME}: Execution time for {func.__name__} - {execution_time} seconds")
                return result
            return wrapper
        return decorator

# Example usage of the runtime decorator
@meter.runtime("Function Execution Report")
def a_slow_function(a, b):
    return a + b

# Test case to validate the runtime decorator
