```csharp
public class VersionComparer
{
    public int CompareStringVersions(string version1, string version2)
    {
        string[] v1Parts = version1.Split('.');
        string[] v2Parts = version2.Split('.');

        int maxLength = Math.Max(v1Parts.Length, v2Parts.Length);

        for (int i = 0; i < maxLength; i++)
        {
            int v1Part = i < v1Parts.Length ? int.Parse(v1Parts[i]) : 0;
            int v2Part = i < v2Parts.Length ? int.Parse(v2Parts[i]) : 0;

            if (v1Part < v2Part)
                return -1;
            if (v1Part > v2Part)
                return 1;
        }

        return 0;
    }

    public int CompareDetailedVersions(int[] version1, int[] version2)
    {
        int maxLength = Math.Max(version1.Length, version2.Length);

        for (int i = 0; i < maxLength; i++)
        {
            int v1Part = i < version1.Length ? version1[i] : 0;
            int v2Part = i < version2.Length ? version2[i] : 0;

            if (v1Part < v2Part)
                return -1;
            if (v1Part > v2Part)
                return 1;
        }

        return 0;
    }
}
```

The `CompareStringVersions` method compares two version numbers represented as strings, while the `CompareDetailedVersions` method compares two version numbers represented as arrays of integers. Both methods follow the specified rules for comparison and return the appropriate result.

