#include <string>
#include <vector>

struct Product {
    std::string name;
    double price;
};

std::vector<Product> extractProductInfo(const std::string& xmlData) {
    std::vector<Product> products;

    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(xmlData.c_str());

