class Application:
    def __init__(self):
        self.commands = {}

    def register_command(self, command_name):
        if command_name in self.commands:
            raise ValueError(f"Command '{command_name}' already exists.")
        self.commands[command_name] = {}

    def register_option(self, command_name, option_name, description):
        if command_name not in self.commands:
            raise ValueError(f"Command '{command_name}' does not exist.")
        if option_name in self.commands[command_name]:
            raise ValueError(f"Option '{option_name}' already exists for command '{command_name}'.")
        self.commands[command_name][option_name] = description

def register_cli(app, commands_and_options):
