class MultiAgentEnv:
    def __init__(self, world, reset_world, reward, observation):
        self.world = world
        self.reset_world = reset_world
        self.reward = reward
        self.observation = observation
        self.current_state = None

    def reset(self):
        self.current_state = self.reset_world()
        return self.current_state

    def step(self, actions):
        rewards = {}
        next_state = self.world.get_next_state(self.current_state, actions)
        for agent, action in actions.items():
            rewards[agent] = self.reward(self.current_state, action)
        self.current_state = next_state
        done = self.world.is_terminal(next_state)
        return next_state, rewards, done

    def observe(self, agent):
        return self.observation(self.current_state, agent)
```
