#include <stdio.h>
#include <stdbool.h>

// Define the size of the forest grid
#define ROWS 5
#define COLS 5

// Define the symbols for different elements in the forest
#define EMPTY_CELL '.'
#define PLAYER_CELL 'P'
#define DEER_CELL 'D'
#define BEAR_CELL 'B'
#define TREE_CELL 'T'

// Define the initial position of the player
int playerRow = 0;
int playerCol = 0;

// Define the forest grid
char forest[ROWS][COLS] = {
    {DEER_CELL, EMPTY_CELL, EMPTY_CELL, TREE_CELL, EMPTY_CELL},
    {EMPTY_CELL, EMPTY_CELL, BEAR_CELL, EMPTY_CELL, EMPTY_CELL},
    {EMPTY_CELL, EMPTY_CELL, EMPTY_CELL, EMPTY_CELL, EMPTY_CELL},
    {EMPTY_CELL, EMPTY_CELL, EMPTY_CELL, EMPTY_CELL, EMPTY_CELL},
    {EMPTY_CELL, EMPTY_CELL, EMPTY_CELL, EMPTY_CELL, EMPTY_CELL}
};

// Function to display the forest grid
void displayForest() {
    for (int i = 0; i < ROWS; i++) {
        for (int j = 0; j < COLS; j++) {
            if (i == playerRow && j == playerCol) {
                printf("%c ", PLAYER_CELL);
            } else {
                printf("%c ", forest[i][j]);
            }
        }
        printf("\n");
    }
}

// Function to handle player movement
void movePlayer(int newRow, int newCol) {
    if (newRow >= 0 && newRow < ROWS && newCol >= 0 && newCol < COLS) {
        if (forest[newRow][newCol] == EMPTY_CELL || forest[newRow][newCol] == DEER_CELL) {
            playerRow = newRow;
            playerCol = newCol;
            printf("Moved to row %d, col %d\n", playerRow, playerCol);
            if (forest[playerRow][playerCol] == DEER_CELL) {
                printf("You hunted a deer!\n");
            }
        } else if (forest[newRow][newCol] == BEAR_CELL) {
            printf("Encountered a bear! Game over.\n");
        } else if (forest[newRow][newCol] == TREE_CELL) {
            printf("Encountered a tree! Can't move there.\n");
        }
    } else {
        printf("Invalid move! Can't move outside the forest.\n");
    }
}

int main() {
    printf("Welcome to the forest hunt game!\n");
    displayForest();

    char move;
    bool gameRunning = true;

    while (gameRunning) {
        printf("Enter your move (u/d/l/r): ");
        scanf(" %c", &move);

        switch (move) {
            case 'u':
                movePlayer(playerRow - 1, playerCol);
                break;
            case 'd':
                movePlayer(playerRow + 1, playerCol);
                break;
            case 'l':
                movePlayer(playerRow, playerCol - 1);
                break;
            case 'r':
                movePlayer(playerRow, playerCol + 1);
                break;
            default:
                printf("Invalid move! Use u/d/l/r for up/down/left/right.\n");
        }

        displayForest();

        if (forest[playerRow][playerCol] == BEAR_CELL) {
            gameRunning = false;
        }
    }

    printf("Game over. Thanks for playing!\n");

    return 0;
}
```

