class Codec:
    def __init__(self):
        self.tinyTolong = {}
        self.longTotiny = {}
        self.base_url = "http://tinyurl.com/"

    def encode(self, longUrl):
        """Encodes a long URL to a shortened URL."""
        if longUrl in self.longTotiny:
            return self.base_url + self.longTotiny[longUrl]
        else:
            tiny_url = str(hash(longUrl))
            self.tinyTolong[tiny_url] = longUrl
            self.longTotiny[longUrl] = tiny_url
            return self.base_url + tiny_url

    def decode(self, shortUrl):
        """Decodes a shortened URL to its original URL."""
        tiny_url = shortUrl.replace(self.base_url, "")
        return self.tinyTolong[tiny_url]
```

