```csharp
public class CreateTableInfo
{
    public string TableName { get; set; }
    public List<string> Columns { get; set; }
}

public class CreateTableParser
{
    public CreateTableInfo ParseCreateTableScript(string createTableScript)
    {
        CreateTableInfo tableInfo = new CreateTableInfo();

        // Extract table name
        int tableNameStartIndex = createTableScript.IndexOf("CREATE TABLE") + "CREATE TABLE".Length;
        int tableNameEndIndex = createTableScript.IndexOf("(");
        tableInfo.TableName = createTableScript.Substring(tableNameStartIndex, tableNameEndIndex - tableNameStartIndex).Trim();

        // Extract columns
        string columnsPart = createTableScript.Substring(tableNameEndIndex + 1, createTableScript.Length - tableNameEndIndex - 2).Trim();
        tableInfo.Columns = columnsPart.Split(',').Select(c => c.Trim()).ToList();

        return tableInfo;
    }
}
```

