// PreferenceService class definition
class PreferenceService {
  private preferences: Map<string, any> = new Map();
  private preferenceChangeSubscribers: Map<string, ((e: PreferenceChangeEvent) => void)[]> = new Map();

  // Method to set a preference
  set<T>(name: string, value: T): void {
    this.preferences.set(name, value);
    this.notifyPreferenceChanged(name, value);
  }

  // Method to get a preference
  get<T>(name: string): T | undefined {
    return this.preferences.get(name);
  }

  // Method to subscribe to preference change events
  onPreferenceChanged(callback: (e: PreferenceChangeEvent) => void, preferenceName: string): void {
    if (!this.preferenceChangeSubscribers.has(preferenceName)) {
      this.preferenceChangeSubscribers.set(preferenceName, []);
    }
    this.preferenceChangeSubscribers.get(preferenceName)!.push(callback);
  }

  // Method to notify subscribers of preference change
  private notifyPreferenceChanged<T>(name: string, value: T): void {
    const subscribers = this.preferenceChangeSubscribers.get(name);
    if (subscribers) {
      const event: PreferenceChangeEvent = {
        preferenceName: name,
        newValue: value
      };
      subscribers.forEach(callback => callback(event));
    }
  }
}

// PreferenceChangeEvent interface
interface PreferenceChangeEvent {
  preferenceName: string;
  newValue: any;
}

// Example usage
