use std::path::Path;
use std::sync::{Once, Mutex};
static START: Once = Once::new();

mod utils {
    use std::collections::HashMap;
    use std::fs;
    use std::path::Path;
    use std::sync::Mutex;

    pub struct FileCache {
        cache: Mutex<HashMap<String, String>>,
    }

    impl FileCache {
        pub fn new() -> FileCache {
            FileCache {
                cache: Mutex::new(HashMap::new()),
            }
        }

        pub fn cache_file(&self, file_path: &str) {
            let file_content = fs::read_to_string(file_path).expect("Unable to read file");
            self.cache.lock().unwrap().insert(file_path.to_string(), file_content);
        }

        pub fn get_cached_file(&self, file_path: &str) -> Option<String> {
            self.cache.lock().unwrap().get(file_path).cloned()
        }
    }
}

#[test]
fn test_file_cache() {
    START.call_once(|| {
        let cache = utils::FileCache::new();
        cache.cache_file("example.txt");
        let content = cache.get_cached_file("example.txt").unwrap();
        assert_eq!(content, "Example file content");
    });
}
