#include <stddef.h>
#include <sys/atomics.h>
#include <bionic_futex.h>
#include <bionic_atomic_inline.h>

typedef struct {
    int volatile flag;
} spinlock;

void spinlock_init(spinlock* lock) {
    lock->flag = 0;
}

void spinlock_lock(spinlock* lock) {
    while (__atomic_cmpxchg(0, 1, &lock->flag) != 0) {
        // Spin until the lock becomes available
        while (lock->flag != 0) {
            // Use a memory barrier to prevent speculative execution
            ANDROID_MEMBAR_FULL();
        }
    }
}

void spinlock_unlock(spinlock* lock) {
    // Release the lock by setting the flag to 0
    __atomic_store_n(&lock->flag, 0, __ATOMIC_SEQ_CST);
}
```

In the solution, we define a `spinlock` structure with an atomic flag to indicate whether the lock is held or not. The `spinlock_init` function initializes the flag to 0. The `spinlock_lock` function uses a compare-and-swap loop to acquire the lock, spinning until the lock becomes available. The `spinlock_unlock` function simply releases the lock by setting the flag to 0 using an atomic store operation. This implementation ensures thread safety and efficient synchronization using atomic operations.

