public int FindNthDigit(int number, int index)
{
    if (index < 0)
    {
        return -1; // Invalid index
    }

    string numStr = Math.Abs(number).ToString(); // Convert number to string, ignoring the negative sign
    if (index >= numStr.Length)
    {
        return -1; // Index out of range
    }

    char digit = numStr[numStr.Length - 1 - index]; // Get the digit at the specified index from the right
    return number < 0 ? -int.Parse(digit.ToString()) : int.Parse(digit.ToString()); // Return the digit with the sign if applicable
}
```

This solution first converts the absolute value of the given number to a string, ignoring the negative sign. It then checks if the index is out of range for the number and returns -1 if so. If the index is valid, it retrieves the digit at the specified index from the right of the string representation of the number. Finally, it returns the digit with the sign if the original number was negative.

