class SubsetGenerator:
    def __init__(self):
        self.subsets = []

    def generate_subsets(self, input_set):
        input_list = list(input_set)
        n = len(input_list)
        for i in range(1 << n):
            subset = [input_list[j] for j in range(n) if (i & (1 << j))]
            self.subsets.append(set(subset))

# Example usage
sg = SubsetGenerator()
input_set = {1, 2, 3}
sg.generate_subsets(input_set)
print(sg.subsets)  # Output: [{}, {1}, {2}, {3}, {1, 2}, {1, 3}, {2, 3}, {1, 2, 3}]
