import java.io.File;
import java.io.IOException;
import java.nio.file.FileVisitOption;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.EnumSet;

class MacFileUtil {

    final static void deleteDirectory(final File dir) throws IOException {
        if (dir == null || !dir.exists()) {
            throw new IllegalArgumentException("Invalid directory");
        }

        Files.walk(dir.toPath(), EnumSet.of(FileVisitOption.FOLLOW_LINKS))
                .sorted((path1, path2) -> -path1.compareTo(path2))
                .forEach(path -> {
                    try {
                        Files.delete(path);
                    } catch (IOException e) {
                        System.err.println("Failed to delete: " + path);
                    }
                });
    }

    public static void main(String[] args) {
        File directory = new File("path_to_directory");
        try {
            deleteDirectory(directory);
            System.out.println("Directory deleted successfully");
        } catch (IOException e) {
            System.err.println("Failed to delete directory: " + e.getMessage());
        }
    }
}
```

In the solution, the `deleteDirectory` method uses the `Files.walk` method to traverse the directory tree and delete all files and subdirectories. It sorts the paths in reverse order to ensure that files and subdirectories are deleted before their parent directories. The method handles symbolic links by using `FileVisitOption.FOLLOW_LINKS` to follow symbolic links during the traversal. If an exception occurs during deletion, it prints an error message indicating the failure. The `main` method demonstrates how to use the `deleteDirectory` method and handle any potential `IOException` that may occur.

