from typing import List, Dict

def count_word_occurrences(file_path: str, words: List[str]) -> Dict[str, int]:
    word_counts = {}

    try:
        with open(file_path, 'r') as file:
            content = file.read().lower()  # Convert the content to lowercase for case-insensitive comparison
            for word in words:
                count = content.count(word.lower())  # Count the occurrences of the word in the content
                word_counts[word] = count  # Store the count in the dictionary

    except FileNotFoundError:
        print(f"File not found at path: {file_path}")
    except Exception as e:
        print(f"An error occurred while reading the file: {e}")

    return word_counts
