use clap::{App, Arg};

fn main() {
    let matches = App::new("Argument Parser")
        .arg(
            Arg::new("o")
                .short('o')
                .long("option")
                .takes_value(true)
                .default_value("default")
                .default_missing_value("default_missing"),
