public string ReverseSubstring(string originalString, int subStrIndex, int subStrLength)
{
    char[] charArray = originalString.ToCharArray();
    int left = subStrIndex;
    int right = subStrIndex + subStrLength - 1;

    while (left < right)
    {
        char temp = charArray[left];
        charArray[left] = charArray[right];
        charArray[right] = temp;
        left++;
        right--;
    }

    return new string(charArray);
}
