    in_single_line_comment = False
    in_multi_line_comment = False
    result = []
    lines = code.split('\n')

    for line in lines:
        line = line.strip()

        if in_multi_line_comment:
            if "'''" in line or '"""' in line:
                in_multi_line_comment = False
            result.append(line)
        else:
            if line.startswith('#'):
                result.append(line)
            elif "'''" in line or '"""' in line:
                in_multi_line_comment = True
                result.append(line)

