class WorkflowUpdate:
    def __init__(self, changes, deletions, additions):
        self.changes = changes
        self.deletions = deletions
        self.additions = additions

    def apply(self, snapshot, workflow_id):
        # Apply changes to the snapshot
        if workflow_id in self.changes:
            snapshot.core.states[workflow_id].update(self.changes[workflow_id])
        if workflow_id in self.deletions:
            del snapshot.core.states[workflow_id]
        if workflow_id in self.additions:
            snapshot.core.states[workflow_id] = self.additions[workflow_id]

        return snapshot

def update_workflow(snapshot, workflow_id):
