class BankingSystem:
    def __init__(self):
        self.accounts = {}

    def create_account(self, account_number, initial_balance):
        if account_number > 0 and account_number not in self.accounts and initial_balance >= 0:
            self.accounts[account_number] = initial_balance
            return f"Account {account_number} created with initial balance {initial_balance}."
        else:
            return "Invalid account number or initial balance."

    def deposit(self, account_number, amount):
        if account_number in self.accounts and amount >= 0:
            self.accounts[account_number] += amount
            return f"Deposited {amount} into account {account_number}. New balance is {self.accounts[account_number]}."
        else:
            return "Account not found or invalid deposit amount."

    def withdraw(self, account_number, amount):
        if account_number in self.accounts and amount >= 0 and self.accounts[account_number] >= amount:
            self.accounts[account_number] -= amount
            return f"Withdrew {amount} from account {account_number}. New balance is {self.accounts[account_number]}."
        else:
            return "Account not found, invalid withdrawal amount, or insufficient balance."

    def check_balance(self, account_number):
        if account_number in self.accounts:
            return f"Account {account_number} balance: {self.accounts[account_number]}."
        else:
            return "Account not found."
