function calculateSTOCH(prices, period) {
  const result = [];
  for (let i = 0; i < prices.length; i++) {
    if (i < period - 1) {
      result.push({ period: i + 1, %K: null, %D: null });
    } else {
      const currentPrices = prices.slice(i - period + 1, i + 1);
      const lowestLow = Math.min(...currentPrices);
      const highestHigh = Math.max(...currentPrices);
      const currentClose = prices[i];
      const %K = 100 * ((currentClose - lowestLow) / (highestHigh - lowestLow));
      if (i === period - 1) {
        result.push({ period: i + 1, %K, %D: null });
      } else {
        const prev%D = result[i - period].%D;
        const current%D = (prev%D !== null) ? (prev%D + %K) / 2 : %K;
        result.push({ period: i + 1, %K, %D: current%D });
      }
    }
  }
  return result;
}
