import java.math.BigInteger;
import java.util.ArrayList;

public class MemoizingDynamicFibonacciNumberGenerator {
    private ArrayList<BigInteger> cache;

    public MemoizingDynamicFibonacciNumberGenerator() {
        cache = new ArrayList<>();
        cache.add(BigInteger.ONE);
        cache.add(BigInteger.ONE);
    }

    public BigInteger generateFibonacciNumber(int n) {
        if (n < cache.size()) {
            return cache.get(n);
        } else {
            for (int i = cache.size(); i <= n; i++) {
                BigInteger fib = cache.get(i - 1).add(cache.get(i - 2));
                cache.add(fib);
            }
            return cache.get(n);
        }
    }
}
