class Graph:
    def __init__(self):
        self.d = {}

    def add_edge(self, bgn, end):
        if bgn not in self.d:
            self.d[bgn] = []
        self.d[bgn].append(end)

    def dfs(self, v0):
        stack = [v0]
        visited = set()
        connected_components = []

        while stack:
            v = stack.pop()
            if v not in visited:
                component = []
                self._dfs_helper(v, visited, component)
                connected_components.append(component)

        return connected_components

    def _dfs_helper(self, v, visited, component):
        visited.add(v)
        component.append(v)
        for neighbor in self.d.get(v, []):
            if neighbor not in visited:
                self._dfs_helper(neighbor, visited, component)
