namespace PropertyValidator;

class PropertyValidator {
    private $rules = [];

    public function addRule(string $propertyName, string $rule, $value = null) {
        $this->rules[$propertyName][] = ['rule' => $rule, 'value' => $value];
    }

    public function validate(object $object): array {
        $errors = [];

        foreach ($this->rules as $propertyName => $propertyRules) {
            foreach ($propertyRules as $rule) {
                if ($rule['rule'] === 'required' && empty($object->$propertyName)) {
                    $errors[$propertyName][] = 'The property is required.';
                } elseif ($rule['rule'] === 'min' && $object->$propertyName < $rule['value']) {
                    $errors[$propertyName][] = "The property value must be greater than or equal to {$rule['value']}.";
                } elseif ($rule['rule'] === 'max' && $object->$propertyName > $rule['value']) {
                    $errors[$propertyName][] = "The property value must be less than or equal to {$rule['value']}.";
                } elseif ($rule['rule'] === 'custom' && !$this->customValidation($object->$propertyName, $rule['value'])) {
                    $errors[$propertyName][] = 'The property value does not pass custom validation.';
                }
            }
        }

        return $errors;
    }

    private function customValidation($value, $validationFunction): bool {
        return $validationFunction($value);
    }
}
