function determineGrowthType(changeInfo: IChangeInfo): GrowthType {
  const { change } = changeInfo;
  const { range, text } = change;

  if (range.start.line === range.end.line && text.includes('\n')) {
    return GrowthType.Grow;
  }

  const lineText = change.document.lineAt(range.start.line).text;
  const changeStartIndex = change.document.offsetAt(range.start);
  const changeEndIndex = change.document.offsetAt(range.end);

  if (changeStartIndex === 0 && changeEndIndex === lineText.length) {
    return GrowthType.Grow;
  } else if (changeStartIndex === 0) {
    return GrowthType.FixLeft;
  } else if (changeEndIndex === lineText.length) {
    return GrowthType.FixRight;
  }

  return GrowthType.Grow; // Default to Grow if no specific condition is met
}
```

In the solution, the `determineGrowthType` function first extracts the range and text from the provided `changeInfo`. It then checks for specific conditions to determine the growth type:
- If the change spans multiple lines (indicated by the presence of '\n' in the text), it returns `GrowthType.Grow`.
- If the change affects the entire line (from the start to the end), it returns `GrowthType.Grow`.
- If the change only affects the start of the line, it returns `GrowthType.FixLeft`.
- If the change only affects the end of the line, it returns `GrowthType.FixRight`.
If none of the specific conditions are met, it defaults to returning `GrowthType.Grow`.

