import numpy as np

def transitive_reduce(A):
    n = len(A)
    A_red = np.copy(A)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if A_red[i][k] and A_red[k][j]:
                    A_red[i][j] = False

    return A_red

#test case
