class FileSystem:
    def __init__(self):
        self.root = {}

    def create_file(self, file_path):
        current = self.root
        directories = file_path.split('/')
        for directory in directories[:-1]:
            if directory not in current:
                current[directory] = {}
            current = current[directory]
        current[directories[-1]] = {}

    def delete_file(self, file_path):
        current = self.root
        directories = file_path.split('/')
        for directory in directories[:-1]:
            if directory not in current:
                return  # Directory does not exist
            current = current[directory]
        if directories[-1] in current:
            del current[directories[-1]]

    def move_file(self, source_path, destination_path):
        self.create_file(destination_path)
        self.root[destination_path] = self.root.pop(source_path, {})

    def print_file_system(self):
        self._print_helper(self.root, 0)

    def _print_helper(self, node, indent):
        for key, value in node.items():
            print('  ' * indent + key)
            if isinstance(value, dict):
                self._print_helper(value, indent + 1)

# Example usage
file_system = FileSystem()
file_system.create_file("bin/airpub-bootstrap.less")
