```typescript
export class Season {
  episodes: Video[]

  constructor(episodes: Video[]) {
    this.episodes = episodes
  }

  /**
   * Implement this method to filter and limit the episodes based on certain criteria.
   * @param filters An array of filter functions to apply to the episodes.
   * @param limit The maximum number of episodes to return.
   * @returns An array of filtered and limited episodes.
   */
  filterAndLimitEpisodes(filters: Resolver<Video, boolean>[], limit: number): Video[] {
    let filteredEpisodes = this.episodes.filter((episode) => {
