from typing import List

class SegmentTree:
    def __init__(self, arr: List[int]):
        self.n = len(arr)
        self.SEG = [0] * (2 * self.n - 1)
        self.construct_segment_tree(arr, 0, self.n - 1, 0)

    def construct_segment_tree(self, arr: List[int], start: int, end: int, pos: int) -> int:
        if start == end:
            self.SEG[pos] = arr[start]
            return self.SEG[pos]
        mid = (start + end) // 2
        self.SEG[pos] = self.construct_segment_tree(arr, start, mid, 2 * pos + 1) + self.construct_segment_tree(arr, mid + 1, end, 2 * pos + 2)
        return self.SEG[pos]

    def func(self, a: int, b: int) -> int:
        return a + b

    def apply_odd_operation(self, func) -> List[int]:
        resleft = [0] * self.n
        for left in range(1, 2 * self.n, 2):
            if left % 2 == 1:
                resleft[left // 2] = self.func(resleft[left // 2], self.SEG[left])
        return resleft
