BOOL GetPrinterName(
    IN OUT LPWSTR  pszPrinterName,
    OUT UINT*     pcchPrinterName,
    IN     LPCWSTR pszServerName
) {
    if (pszPrinterName == NULL || pcchPrinterName == NULL) {
        return FALSE; // Invalid input parameters
    }

    DWORD neededSize = 0;
    if (!GetPrinter(
        NULL,  // handle to the printer object
        2,     // level of information
        NULL,  // buffer that receives the printer data
        0,     // size, in bytes, of the buffer
        &neededSize  // receives the required size of the buffer
    )) {
        if (GetLastError() != ERROR_INSUFFICIENT_BUFFER) {
            return FALSE; // Failed to retrieve required buffer size
        }
    }

    if (*pcchPrinterName < neededSize) {
        *pcchPrinterName = neededSize;
        return FALSE; // Insufficient buffer size, return required size
    }

    if (!GetPrinter(
        NULL,  // handle to the printer object
        2,     // level of information
        (LPBYTE)pszPrinterName,  // buffer that receives the printer data
        *pcchPrinterName,  // size, in bytes, of the buffer
        &neededSize  // receives the required size of the buffer
    )) {
        return FALSE; // Failed to retrieve printer name
    }

    *pcchPrinterName = neededSize / sizeof(WCHAR); // Update actual size of printer name
    return TRUE;
}
