def ArrayAdditionI(arr):
    max_num = max(arr)  # Find the largest number in the array
    arr.remove(max_num)  # Remove the largest number from the array

    # Check if the sum of any combination of the remaining numbers equals the largest number
    def is_sum_combination(target, numbers):
        if target == 0:
            return True
        if not numbers:
            return False
        num = numbers[0]
        rest = numbers[1:]
        return is_sum_combination(target - num, rest) or is_sum_combination(target, rest)

    return is_sum_combination(max_num, arr)
```

