import dbus

class DBusMessagingSystem:
    def __init__(self):
        self.bus = None

    def open_connection(self):
        try:
            self.bus = dbus.SessionBus()
        except Exception as e:
            raise ConnectionError("Unable to open a connection to D-Bus")

    def send_message(self, destination, message):
        if self.bus is None:
            raise ConnectionError("D-Bus connection is not open")
        try:
            remote_object = self.bus.get_object(destination, '/path/to/destination')
            remote_object.send_message(message, dbus_interface='com.example.interface')
        except Exception as e:
            print("Error sending message:", e)

    def receive_message(self):
        if self.bus is None:
            raise ConnectionError("D-Bus connection is not open")
        try:
            remote_object = self.bus.get_object('com.example.service', '/com/example/service')
            message = remote_object.get_message(dbus_interface='com.example.interface')
            return message
        except Exception as e:
            print("Error receiving message:", e)

# Example script demonstrating the usage of DBusMessagingSystem
if __name__ == "__main__":
