#include <vector>

class Solution {
public:
    vector<int> sumZero(int n) {
        vector<int> ans;
        if (n % 2 != 0) {
            ans.push_back(0);
            --n;
        }
        for (int i = 1; i <= n / 2; ++i) {
            ans.push_back(i);
            ans.push_back(-i);
        }
        return ans;
    }
};
```

The `sumZero` function first checks if `n` is odd. If it is, it adds 0 to the result array and decrements `n` by 1. Then, it iterates from 1 to `n/2` and adds `i` and `-i` to the result array. Finally, it returns the resulting array, which satisfies the conditions of having a sum of zero and being sorted in non-decreasing order.

