#include <iostream>
#include <vector>
#include <sstream>

// Define the custom matrix class
template <typename T>
class _M {
private:
    std::vector<std::vector<T>> data;

public:
    _M() {}

    _M(const std::string& rawData) {
        std::istringstream iss(rawData);
        std::string line;
        while (std::getline(iss, line)) {
            std::vector<T> row;
            std::istringstream rowStream(line);
            T value;
            while (rowStream >> value) {
                row.push_back(value);
            }
            data.push_back(row);
        }
    }

    void Resize(int rows, int cols) {
        data.resize(rows, std::vector<T>(cols));
    }

    int numRows() const {
        return data.size();
    }

    int numCols() const {
        return data.empty() ? 0 : data[0].size();
    }

    const std::vector<T>& operator[](int index) const {
        return data[index];
    }

    std::vector<T>& operator[](int index) {
        return data[index];
    }
};

// Function to perform matrix multiplication
template <typename T>
_M<T> matrixMultiplication(const _M<T>& matrix1, const _M<T>& matrix2) {
    int m = matrix1.numRows();
    int n = matrix1.numCols();
    int p = matrix2.numCols();

    _M<T> result;
    result.Resize(m, p);

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < p; j++) {
            T sum = 0;
            for (int k = 0; k < n; k++) {
                sum += matrix1[i][k] * matrix2[k][j];
            }
            result[i][j] = sum;
        }
    }

    return result;
}

int main() {
    // Example usage
    _M<int> A, B, C, R;
    R.Resize(3, 3);
    A = _M<int>(R"(
        1 2 3
        4 5 6
        7 8 9
    )");
    B = _M<int>(R"(
        9 8 7
        6 5 4
        3 2 1
    )");
    C = matrixMultiplication(A, B);

    // Output the result
    for (int i = 0; i < C.numRows(); i++) {
        for (int j = 0; j < C.numCols(); j++) {
            std::cout << C[i][j] << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
```

