import { LoggerService } from 'path/to/logger.service';

interface DataProvider {
  name: string;
  configuration: any;
}

class ProviderRegistryService {
  private dataProviders: Map<string, DataProvider>;
  private logger: LoggerService;

  constructor(logger: LoggerService) {
    this.dataProviders = new Map();
    this.logger = logger;
  }

  registerDataProvider(name: string, configuration: any): void {
    if (this.dataProviders.has(name)) {
      this.logger.log(`Data provider with name '${name}' already exists.`);
    } else {
      this.dataProviders.set(name, { name, configuration });
      this.logger.log(`Registered data provider: ${name}`);
    }
  }

  getDataProvider(name: string): DataProvider | undefined {
    const dataProvider = this.dataProviders.get(name);
    if (dataProvider) {
      this.logger.log(`Retrieved data provider: ${name}`);
    } else {
      this.logger.log(`Data provider with name '${name}' does not exist.`);
    }
    return dataProvider;
  }
}

// Unit tests using a testing framework like Jasmine or Jest
describe('ProviderRegistryService', () => {
  let providerRegistryService: ProviderRegistryService;
  let logger: LoggerService;

  beforeEach(() => {
    logger = new LoggerService();
    providerRegistryService = new ProviderRegistryService(logger);
  });

  it('should register a data provider', () => {
    providerRegistryService.registerDataProvider('provider1', { config: 'value1' });
