import re

def process_arguments(**kwargs):
    types = {}
    keys = {}
    has_pos = False
    has_nonpos = False
    i = 0
    for k in kwargs.keys():
        m = re.match("(.+)_(\d+)", k)
        if m:
            if has_nonpos:
                raise Exception("Can't mix _n arguments with implicitly positioned arguments")
            pos = int(m.group(2))
            types[pos] = kwargs[k]
            keys[pos] = m.group(1)
            has_pos = True
        else:
            if has_pos:
                raise Exception("Can't mix _n arguments with implicitly positioned arguments")
            pos = i
            types[pos] = kwargs[k]
            keys[pos] = k
            i += 1
    return {pos: types[pos] for pos in sorted(types)}
```

