pub struct BitIter {
    num: u64,
    index: u32,
}

impl Iterator for BitIter {
    type Item = bool;

    fn next(&mut self) -> Option<Self::Item> {
        if self.index < 64 {
            let bit = (self.num >> self.index) & 1 == 1;
            self.index += 1;
            Some(bit)
        } else {
            None
        }
    }
}

