func calculateTotalLineLength(parentView: UIView) -> CGFloat {
    var totalLength: CGFloat = 0.0

    for subview in parentView.subviews {
        if let line = subview as? UIView, line.backgroundColor == UIColor.init(rgb: 0xf2f2f2) {
            for constraint in line.constraints {
                if constraint.firstAttribute == .left && constraint.secondAttribute == .right {
                    let width = abs(constraint.constant)
                    totalLength += width
                }
            }
        }
    }

    return totalLength
