```swift
import Foundation
import CommonCrypto

extension Data {
    func aesEncrypt(key: Data) -> Data? {
        var encryptedData = Data(count: self.count + kCCBlockSizeAES128)
        var encryptedLength: Int = 0

        let status = key.withUnsafeBytes { keyBytes in
            self.withUnsafeBytes { dataBytes in
                CCCrypt(CCOperation(kCCEncrypt),
                        CCAlgorithm(kCCAlgorithmAES),
                        CCOptions(kCCOptionPKCS7Padding),
                        keyBytes.baseAddress, key.count,
                        nil,
                        dataBytes.baseAddress, self.count,
                        encryptedData.withUnsafeMutableBytes { $0.baseAddress }, encryptedData.count,
                        &encryptedLength)
            }
        }

        if status == kCCSuccess {
            encryptedData.count = encryptedLength
            return encryptedData
        } else {
            return nil
        }
    }

    func aesDecrypt(key: Data) -> Data? {
        var decryptedData = Data(count: self.count + kCCBlockSizeAES128)
        var decryptedLength: Int = 0

        let status = key.withUnsafeBytes { keyBytes in
            self.withUnsafeBytes { dataBytes in
                CCCrypt(CCOperation(kCCDecrypt),
                        CCAlgorithm(kCCAlgorithmAES),
                        CCOptions(kCCOptionPKCS7Padding),
                        keyBytes.baseAddress, key.count,
                        nil,
                        dataBytes.baseAddress, self.count,
                        decryptedData.withUnsafeMutableBytes { $0.baseAddress }, decryptedData.count,
                        &decryptedLength)
            }
        }

        if status == kCCSuccess {
            decryptedData.count = decryptedLength
            return decryptedData
        } else {
            return nil
        }
    }
}

func aesEncryptDecrypt(message: Data, key: Data, encrypt: Bool) -> Data? {
    if encrypt {
        return message.aesEncrypt(key: key)
    } else {
        return message.aesDecrypt(key: key)
    }
}
```

The `aesEncryptDecrypt` function uses the provided AES encryption and decryption methods to perform the specified operation based on the `encrypt` flag. It returns the encrypted or decrypted message as a `Data` object, or `nil` if the operation fails.

