```python
import json

def count_log_messages(file_path, log_level):
    with open(file_path, 'r') as file:
        logs = json.load(file)

    log_messages = {}
    for log in logs:
        if log['level'] == log_level:
            message = log['message']
            log_messages[message] = log_messages.get(message, 0) + 1

    return log_messages
```

