    crop_count = {}

    for crop in crop_data:
        crop_type = crop[0]
        total_yield = crop[3]
        acreage = crop[4]

        if crop_type in crop_yield:
            crop_yield[crop_type] += total_yield / acreage
            crop_count[crop_type] += 1
        else:
            crop_yield[crop_type] = total_yield / acreage
