import os
import shutil

def backup_rsync(source_dir, dest_dir, excluded_files):
    sync_actions = []

    # Copy files and directories from source to destination
    for root, dirs, files in os.walk(source_dir):
        for d in dirs:
            src_path = os.path.join(root, d)
            dest_path = os.path.join(dest_dir, os.path.relpath(src_path, source_dir))
            if src_path not in excluded_files:
                shutil.copytree(src_path, dest_path)
                sync_actions.append(("COPY", src_path, dest_path))
        for f in files:
            src_path = os.path.join(root, f)
            dest_path = os.path.join(dest_dir, os.path.relpath(src_path, source_dir))
            if src_path not in excluded_files:
                shutil.copy2(src_path, dest_path)
                sync_actions.append(("COPY", src_path, dest_path))

    # Delete excluded files from destination
    for root, dirs, files in os.walk(dest_dir):
        for d in dirs:
            dest_path = os.path.join(root, d)
            src_path = os.path.join(source_dir, os.path.relpath(dest_path, dest_dir))
            if src_path in excluded_files:
                shutil.rmtree(dest_path)
                sync_actions.append(("DELETE", dest_path, ""))
        for f in files:
            dest_path = os.path.join(root, f)
            src_path = os.path.join(source_dir, os.path.relpath(dest_path, dest_dir))
            if src_path in excluded_files:
                os.remove(dest_path)
                sync_actions.append(("DELETE", dest_path, ""))

    return sync_actions
