import UIKit

func fetchAndProcessImage(from url: String, completion: @escaping (Result<UIImage, Error>) -> Void) {
    guard let url = URL(string: url) else {
        completion(.failure(NSError(domain: "InvalidURL", code: 0, userInfo: [NSLocalizedDescriptionKey: "Invalid URL provided"])))
        return
    }

    let task = URLSession.shared.dataTask(with: url) { data, _, error in
        if let error = error {
            completion(.failure(error))
            return
        }
        guard let data = data, let image = UIImage(data: data) else {
            completion(.failure(NSError(domain: "ImageProcessing", code: 0, userInfo: [NSLocalizedDescriptionKey: "Failed to process image data"])))
            return
        }
        completion(.success(image))
    }
    task.resume()
}
```

