```java
import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.List;

public class MotionPathSystem {
    private List<Point2D> points;

    public MotionPathSystem() {
        this.points = new ArrayList<>();
    }

    public void setLinearMotionPath(Point2D start, Point2D end) {
        points.clear();
        points.add(start);
        points.add(end);
    }

    public void setCircularMotionPath(Point2D center, double radius) {
        points.clear();
        // Generate points along the circumference of the circle
        for (double theta = 0; theta <= 2 * Math.PI; theta += Math.PI / 16) {
            double x = center.getX() + radius * Math.cos(theta);
            double y = center.getY() + radius * Math.sin(theta);
            points.add(new Point2D.Double(x, y));
        }
    }

    public void setCustomMotionPath(List<Point2D> waypoints) {
        points.clear();
        points.addAll(waypoints);
    }

    public double getTotalLength() {
        double totalLength = 0;
        for (int i = 1; i < points.size(); i++) {
            totalLength += points.get(i - 1).distance(points.get(i));
        }
        return totalLength;
    }

    public Point2D getPositionAtDistance(double distance) {
        double remainingDistance = distance;
        for (int i = 1; i < points.size(); i++) {
            double segmentLength = points.get(i - 1).distance(points.get(i));
            if (remainingDistance <= segmentLength) {
                double ratio = remainingDistance / segmentLength;
                double dx = points.get(i).getX() - points.get(i - 1).getX();
                double dy = points.get(i).getY() - points.get(i - 1).getY();
                double x = points.get(i - 1).getX() + ratio * dx;
                double y = points.get(i - 1).getY() + ratio * dy;
                return new Point2D.Double(x, y);
            } else {
                remainingDistance -= segmentLength;
            }
        }
        return points.get(points.size() - 1);
    }
}
```

