using System;
using System.Collections.Generic;

namespace Rs.Cache
{
    public class Cache<TKey, TValue>
    {
        private readonly Dictionary<TKey, (TValue value, DateTime expiration)> cache = new Dictionary<TKey, (TValue, DateTime)>();

        public void AddOrUpdate(TKey key, TValue value, int ttlInSeconds)
        {
            DateTime expiration = DateTime.Now.AddSeconds(ttlInSeconds);
            cache[key] = (value, expiration);
        }

        public TValue Get(TKey key)
        {
            if (cache.TryGetValue(key, out var cachedItem))
            {
                if (cachedItem.expiration > DateTime.Now)
                {
                    return cachedItem.value;
                }
                else
                {
                    cache.Remove(key);
                }
            }
            return default;
        }

        public void Remove(TKey key)
        {
            if (cache.ContainsKey(key))
            {
                cache.Remove(key);
            }
        }
    }
}
```

This implementation of the Cache class uses a dictionary to store key-value pairs along with their expiration times. The `AddOrUpdate` method adds or updates a key-value pair in the cache with the specified TTL. The `Get` method retrieves the value associated with the given key from the cache, handling expiration by removing expired items. The `Remove` method removes a key-value pair from the cache.

