def parseMarkup(markup):
    stack = []
    result = {}
    current = result
    i = 0
    while i < len(markup):
        if markup[i] == '<':
            if markup[i+1] == '/':
                stack.pop()
                current = stack[-1]
                i += 2
            else:
                tag, attrs, i = parseTag(markup, i+1)
                current[tag] = attrs
                current[tag]["text"] = ""
                current[tag]["children"] = {}
                stack.append(current)
                current = current[tag]["children"]
        else:
            text, i = parseText(markup, i)
            current["text"] += text
    return result

def parseTag(markup, start):
    tag = ""
    attrs = {}
    i = start
    while markup[i] not in [' ', '>']:
        tag += markup[i]
        i += 1
    while markup[i] != '>':
        key, value, i = parseAttr(markup, i+1)
        attrs[key] = value
    return tag, attrs, i+1

def parseAttr(markup, start):
    key = ""
    value = ""
    i = start
    while markup[i] != '=':
        key += markup[i]
        i += 1
    i += 2
    while markup[i] != "'":
        value += markup[i]
        i += 1
    return key, value, i+1

def parseText(markup, start):
    text = ""
    i = start
    while markup[i] != '<':
        text += markup[i]
        i += 1
    return text, i
```

