using UnityEngine;

public class MoverTextEnemy : MonoBehaviour
{
    public float speed = 2.0f; // Speed of the enemy movement
    public Vector3 direction = Vector3.right; // Initial movement direction

    private void Update()
    {
        MoveEnemy();
    }

    private void MoveEnemy()
    {
        // Move the enemy in the specified direction at the defined speed
        transform.Translate(direction * speed * Time.deltaTime);

        // Check if the enemy has moved off-screen, then reposition it to create a continuous loop
        if (IsOffScreen())
        {
            RepositionEnemy();
        }
    }

    private bool IsOffScreen()
    {
        // Check if the enemy has moved off-screen based on the screen boundaries
        Vector3 screenPos = Camera.main.WorldToScreenPoint(transform.position);
        return screenPos.x < 0 || screenPos.x > Screen.width || screenPos.y < 0 || screenPos.y > Screen.height;
    }

    private void RepositionEnemy()
    {
        // Reposition the enemy to the opposite side of the screen to create a continuous loop
        Vector3 newPosition = transform.position;
        Vector3 screenPos = Camera.main.WorldToScreenPoint(newPosition);

        if (screenPos.x < 0)
        {
            newPosition.x = Screen.width;
        }
        else if (screenPos.x > Screen.width)
        {
            newPosition.x = 0;
        }

        if (screenPos.y < 0)
        {
            newPosition.y = Screen.height;
        }
        else if (screenPos.y > Screen.height)
        {
            newPosition.y = 0;
        }

        transform.position = Camera.main.ScreenToWorldPoint(newPosition);
    }
}
