class BackgroundTaskQueue:
    def __init__(self, ordering='DESC'):
        self.queue = []
        self.ordering = ordering

    def add_task(self, task, niceness):
        if self.ordering == 'DESC':
            priority = -niceness  # Higher niceness values have higher priority
        else:
            priority = niceness  # Lower niceness values have higher priority
        self.queue.append((task, priority))
        self.queue.sort(key=lambda x: x[1], reverse=(self.ordering == 'DESC'))

    def get_next_task(self):
        if self.queue:
            return self.queue.pop(0)[0]
        else:
            return None

    def get_queue_size(self):
        return len(self.queue)
```

