public int longestIncreasingSubsequence(int[] nums) {
    int n = nums.length;
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n];
    Arrays.fill(dp, 1);
    int maxcount = 1;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] > nums[j]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
                maxcount = Math.max(maxcount, dp[i]);
            }
        }
    }
    return maxcount;
}
```

