def hide_message(image: List[List[Tuple[int, int, int]]], byte_arr: List[int]) -> List[List[Tuple[int, int, int]]]:
    bit_idx = 0
    for i in range(len(image)):
        for j in range(len(image[0])):
            ori_pixel = image[i][j]
            val = [ori_pixel[0], ori_pixel[1], ori_pixel[2]]
            for k in range(3):
                if bit_idx >= len(byte_arr):
                    break
                else:
                    val[k] = (val[k] & 254) + byte_arr[bit_idx]
                    bit_idx += 1
            image[i][j] = (val[0], val[1], val[2])
    return image
