from typing import Tuple

def optimal_alignment_score(string1: str, string2: str, match: int, mismatch: int, gap_extend_penalty: int) -> Tuple[int, Tuple[str, str]]:
    n = len(string1)
    m = len(string2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][0] = dp[i-1][0] + gap_extend_penalty
    for j in range(1, m + 1):
        dp[0][j] = dp[0][j-1] + gap_extend_penalty

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if string1[i-1] == string2[j-1]:
                score = match
            else:
                score = mismatch
            dp[i][j] = max(dp[i-1][j-1] + score, dp[i-1][j] + gap_extend_penalty, dp[i][j-1] + gap_extend_penalty)

    aligned_string1 = ""
    aligned_string2 = ""
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and string1[i-1] == string2[j-1]:
            aligned_string1 = string1[i-1] + aligned_string1
            aligned_string2 = string2[j-1] + aligned_string2
            i -= 1
            j -= 1
        elif i > 0 and dp[i][j] == dp[i-1][j] + gap_extend_penalty:
            aligned_string1 = string1[i-1] + aligned_string1
            aligned_string2 = "-" + aligned_string2
            i -= 1
        else:
            aligned_string1 = "-" + aligned_string1
            aligned_string2 = string2[j-1] + aligned_string2
            j -= 1

    return dp[n][m], (aligned_string1, aligned_string2)
```

