class SnakeGame:
    def __init__(self, grid_size, initial_position, initial_direction):
        self.grid_size = grid_size
        self.snake = [initial_position]
        self.direction = initial_direction
        self.food = self.generate_food()
        self.score = 0

    def move(self):
        head = self.snake[0]
        if self.direction == "up":
            new_head = (head[0], (head[1] - 1) % self.grid_size[1])
        elif self.direction == "down":
            new_head = (head[0], (head[1] + 1) % self.grid_size[1])
        elif self.direction == "left":
            new_head = ((head[0] - 1) % self.grid_size[0], head[1])
        else:  # right
            new_head = ((head[0] + 1) % self.grid_size[0], head[1])

        if new_head in self.snake[1:]:
            return False  # Game over, snake collided with itself
        self.snake.insert(0, new_head)
        if new_head == self.food:
            self.score += 1
            self.food = self.generate_food()
        else:
            self.snake.pop()
        return True

    def generate_food(self):
        # Generate random food position not occupied by the snake
        food = (random.randint(0, self.grid_size[0] - 1), random.randint(0, self.grid_size[1] - 1))
        while food in self.snake:
            food = (random.randint(0, self.grid_size[0] - 1), random.randint(0, self.grid_size[1] - 1))
        return food

    def step(self):
        if not self.move():
            return False  # Game over
        return True

    def change_direction(self, new_direction):
        # Ensure the snake cannot reverse its direction
        if new_direction == "up" and self.direction != "down":
            self.direction = new_direction
        elif new_direction == "down" and self.direction != "up":
            self.direction = new_direction
        elif new_direction == "left" and self.direction != "right":
            self.direction = new_direction
        elif new_direction == "right" and self.direction != "left":
            self.direction = new_direction
```
In this solution, the `SnakeGame` class is implemented with methods to initialize the game, move the snake, generate food, simulate game steps, and change the snake's direction. The `move` method handles the snake's movement, food consumption, and game over conditions. The `step` method calls the `move` method and returns the game state after a step. The `change_direction` method ensures that the snake cannot reverse its direction, preventing immediate collision with itself.

