class ShoppingCart:
    def __init__(self):
        self.items = {}

    def add_item(self, item, price, quantity):
        if item in self.items:
            self.items[item]['quantity'] += quantity
        else:
            self.items[item] = {'price': price, 'quantity': quantity}

    def remove_item(self, item):
        if item in self.items:
            del self.items[item]

    def calculate_total(self):
        total_cost = sum(item['price'] * item['quantity'] for item in self.items.values())
        return round(total_cost, 2)

    def apply_discount(self, discount_percent):
        total_cost = self.calculate_total()
        discounted_amount = total_cost * (1 - discount_percent / 100)
        return round(discounted_amount, 2)

# Example usage
cart = ShoppingCart()
cart.add_item('apple', 1.50, 2)
cart.add_item('banana', 0.75, 4)
print(cart.calculate_total())  # Output: 5.50
