use std::fs::File;
use std::io::prelude::*;

mod svg_generation {
    pub fn render_svg(filename: &str, title: &str, data: &Vec<f64>) {
        let mut file = File::create(filename).expect("Failed to create file");
        file.write_all(b"<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"no\"?>\n").expect("Failed to write to file");
        file.write_all(b"<svg xmlns=\"http://www.w3.org/2000/svg\" version=\"1.1\">\n").expect("Failed to write to file");
        file.write_all(format!("<title>{}</title>\n", title).as_bytes()).expect("Failed to write to file");
        file.write_all(b"<rect width=\"100%\" height=\"100%\" fill=\"white\"/>\n").expect("Failed to write to file");

        let mut x = 0.0;
        let width = 20.0;
        let height = 20.0;
        let padding = 5.0;

        for &y in data {
            file.write_all(format!("<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" fill=\"blue\"/>\n", x, height - y, width, y).as_bytes()).expect("Failed to write to file");
            x += width + padding;
        }

        file.write_all(b"</svg>").expect("Failed to write to file");
    }
}

