function countUniqueCSSClasses(cssCode: string): number {
    const classRegex = /\.([a-zA-Z0-9-]+)/g; // Regular expression to match CSS classes
    const matches = cssCode.match(classRegex); // Get all matches of CSS classes
    if (matches) {
        const uniqueClasses = new Set(matches.map(match => match.trim())); // Use Set to store unique classes
