function extractRoutePrefix(htmlCode) {
    const scriptTagStart = htmlCode.indexOf('<script>');
    const scriptTagEnd = htmlCode.indexOf('</script>', scriptTagStart);
    if (scriptTagStart !== -1 && scriptTagEnd !== -1) {
        const scriptContent = htmlCode.substring(scriptTagStart, scriptTagEnd);
        const routePrefixIndex = scriptContent.indexOf('var route_prefix');
        if (routePrefixIndex !== -1) {
            const routePrefixStart = scriptContent.indexOf('=', routePrefixIndex) + 1;
            const routePrefixEnd = scriptContent.indexOf(';', routePrefixStart);
            const routePrefix = scriptContent.substring(routePrefixStart, routePrefixEnd).trim();
            return routePrefix;
        }
    }
    return "Route prefix not found";
}
```

The `extractRoutePrefix` function first locates the `<script>` tag in the HTML code and then extracts the content within it. It then searches for the `var route_prefix` declaration and retrieves the value assigned to it. If found, the function returns the route prefix; otherwise, it returns a message indicating that the route prefix was not found.

