import numpy as np

def generate_random_array(shape, distribution, periodicity):
    ndim = len(shape)
    if distribution == "normal":
        array = np.random.normal(size=shape)
    elif distribution == "uniform":
        array = np.random.uniform(0.5, 1.5, size=shape)
    else:
        raise ValueError("Invalid distribution type")

    if periodicity == "random":
        for i in range(ndim):
            roll = np.random.randint(0, shape[i])
            array = np.roll(array, roll, axis=i)

    return array
```

