```java
public class ByteConversionUtil {

    /**
     * Performs conversion of a byte array to a long representation.
     * 
     * @param bytes the input byte array
     * @return the long representation of the input byte array
     */
    public static long bytesToLong(byte[] bytes) {
        long result = 0;
        for (int i = bytes.length - 1; i >= 0; i--) {
            result <<= 8;
            result |= (bytes[i] & 0xFF);
        }
        return result;
    }

    /**
     * Performs conversion of a long to a byte array representation.
     * 
     * @param value the input long value
     * @return the byte array representation of the input long value
     */
    public static byte[] longToBytes(long value) {
        byte[] bytes = new byte[8];
        for (int i = 0; i < 8; i++) {
            bytes[(bytes.length - 1) - i] = (byte) value;
            value >>>= 8;
        }
        return bytes;
    }
}
```

