        }
        if self.symlinks.is_none() {
            return Err(String::from("Symlinks setting is missing"));
        }
        if self.time_delta.is_none() {
            return Err(String::from("Time delta setting is missing"));
        }
        if self.sync_type.is_none() {
            return Err(String::from("Synchronization type is missing"));
        }
        Ok(())
    }
}

