        snapshot: Some(String::from("default")),
        symlinks: Some(true),
        time_delta: Some(0.5),
        sync_type: Some(String::from("two-way")),
    };

    match config.validate_config() {
        Ok(_) => println!("Server configuration is valid"),
        Err(err) => println!("Error: {}", err),
    }
}
