class SimpleGridOne:
    obstacle = "X"
    step = "O"

    def __init__(self, size, grid, start):
        self.size = size
        self.grid = grid
        self.player_position = start

    def move_up(self):
        new_row = self.player_position[0] - 1
        if 0 <= new_row < self.size and self.grid[new_row][self.player_position[1]] == self.step:
            self.player_position[0] = new_row

    def move_down(self):
        new_row = self.player_position[0] + 1
        if 0 <= new_row < self.size and self.grid[new_row][self.player_position[1]] == self.step:
            self.player_position[0] = new_row

    def move_left(self):
        new_col = self.player_position[1] - 1
        if 0 <= new_col < self.size and self.grid[self.player_position[0]][new_col] == self.step:
            self.player_position[1] = new_col

    def move_right(self):
        new_col = self.player_position[1] + 1
        if 0 <= new_col < self.size and self.grid[self.player_position[0]][new_col] == self.step:
            self.player_position[1] = new_col

    def is_goal_reached(self):
        return self.grid[self.player_position[0]][self.player_position[1]] == self.step
