extension UIButton {
    func loadImage(urlString: String, placeholder: UIImage?, controlState: UIControl.State = .normal, isBackground: Bool = false, completion: ((UIImage?) -> Void)? = nil) {
        guard let url = URL(string: urlString) else {
            // Handle invalid URL
            completion?(nil)
            return
        }

        let task = URLSession.shared.dataTask(with: url) { (data, response, error) in
            if let error = error {
                // Handle network error
                print("Error loading image: \(error.localizedDescription)")
                DispatchQueue.main.async {
                    self.setImage(placeholder, for: controlState)
                    completion?(nil)
                }
                return
            }

            if let data = data, let image = UIImage(data: data) {
                DispatchQueue.main.async {
                    if isBackground {
                        self.setBackgroundImage(image, for: controlState)
                    } else {
                        self.setImage(image, for: controlState)
                    }
                    completion?(image)
                }
            } else {
                // Handle invalid or nil data
                DispatchQueue.main.async {
                    self.setImage(placeholder, for: controlState)
                    completion?(nil)
                }
            }
        }
        task.resume()
    }
}
```

In the solution, the `loadImage` method uses `URLSession` to asynchronously load the image from the provided URL. It handles various scenarios such as invalid URLs, network errors, and nil or invalid image data. The method sets the loaded image as the background or foreground image for the button based on the `isBackground` parameter and also handles the placeholder image and completion closure appropriately.

