class FileProcessor:
    def __init__(self):
        self.file_data = []

    def add_file_entry(self, file_name, line_count):
        self.file_data.append((file_name, line_count))

    def remove_file_entry(self, file_name):
        self.file_data = [entry for entry in self.file_data if entry[0] != file_name]

    def calculate_total_lines(self):
        return sum(entry[1] for entry in self.file_data)

    def perform_operations(self, operations):
        results = []
        for operation, args in operations:
            if operation == 'add':
                file_name, line_count = args
                self.add_file_entry(file_name, line_count)
            elif operation == 'remove':
                file_name = args
                self.remove_file_entry(file_name)
            elif operation == 'calculate_total':
                total_lines = self.calculate_total_lines()
                results.append(total_lines)
        return results
