#include "modes/transOffOn.hpp"
#include "modes/transOnOff.hpp"
#include "modes/nightLight.hpp"
#include "modes/slowOn.hpp"
#include "modes/party.hpp"
#include "modes/transCrossfade.hpp"

class AnimationManager {
private:
    std::unordered_map<std::string, std::unique_ptr<Animation>> modes;

public:
    AnimationManager() {
        // Initialize the available modes
        modes["off"] = std::make_unique<Off>();
        modes["on"] = std::make_unique<On>();
        modes["transOffOn"] = std::make_unique<TransOffOn>();
        modes["transOnOff"] = std::make_unique<TransOnOff>();
        modes["nightLight"] = std::make_unique<NightLight>();
        modes["slowOn"] = std::make_unique<SlowOn>();
        modes["party"] = std::make_unique<Party>();
        modes["transCrossfade"] = std::make_unique<TransCrossfade>();
    }

    void activateMode(const std::string& modeName) {
        if (modes.find(modeName) != modes.end()) {
            modes[modeName]->activate();
        } else {
            std::cout << "Mode " << modeName << " not found." << std::endl;
        }
    }

    void transitionMode(const std::string& fromMode, const std::string& toMode) {
        if (modes.find(fromMode) != modes.end() && modes.find(toMode) != modes.end()) {
            modes[fromMode]->deactivate();
            modes[toMode]->activate();
        } else {
            std::cout << "Invalid mode transition." << std::endl;
        }
    }
};

int main() {
    AnimationManager manager;
    manager.activateMode("on");
    manager.transitionMode("on", "nightLight");
    manager.activateMode("party");
    return 0;
}
```

