import math

class WordVectorCollection:
    def __init__(self):
        self.word_vectors = {}

    def add_vector(self, word, vector):
        self.word_vectors[word] = vector

    def find_vector(self, word):
        return self.word_vectors.get(word, None)

    def calculate_similarity(self, word1, word2):
        vector1 = self.word_vectors.get(word1, None)
        vector2 = self.word_vectors.get(word2, None)

        if vector1 is None or vector2 is None:
            return None

        dot_product = sum(x * y for x, y in zip(vector1, vector2))
        norm1 = math.sqrt(sum(x ** 2 for x in vector1))
        norm2 = math.sqrt(sum(x ** 2 for x in vector2))

        similarity = dot_product / (norm1 * norm2)
        return similarity

# Example usage
word_collection = WordVectorCollection()
word_collection.add_vector('apple', [3.0, 4.0, 1.0])
word_collection.add_vector('banana', [1.0, 2.0, 5.0])

print(word_collection.find_vector('apple'))  # Output: [3.0, 4.0, 1.0]
print(word_collection.calculate_similarity('apple', 'banana'))  # Output: 0.7354655758598752
```

