class CurrencyDictionary {
  constructor() {
    this.currencyMap = new Map();
  }

  addCurrency(name, pluralForms, abbreviations) {
    this.currencyMap.set(name, { pluralForms, abbreviations });
    const pluralArray = pluralForms.split("|");
    pluralArray.forEach((plural) => {
      this.currencyMap.set(plural, { name, pluralForms });
    });
    const abbreviationArray = abbreviations.split("|");
    abbreviationArray.forEach((abbr) => {
      this.currencyMap.set(abbr, { name, pluralForms });
    });
  }

  getCurrencyInfo(query) {
    if (this.currencyMap.has(query)) {
      const currencyInfo = this.currencyMap.get(query);
      if (currencyInfo.abbreviations) {
        return `${currencyInfo.name}|${currencyInfo.pluralForms}|${currencyInfo.abbreviations}`;
      } else {
        return `${query}|${currencyInfo.pluralForms}`;
      }
    } else {
      return "Currency not found";
    }
  }
}
```

