class BankAccount:
    def __init__(self, account_number, account_holder):
        self.account_number = account_number
        self.account_holder = account_holder
        self.balance = 0

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            return f"Deposited {amount} successfully."
        else:
            return "Invalid deposit amount."

    def withdraw(self, amount):
        if amount > 0:
            if self.balance >= amount:
                self.balance -= amount
                return f"Withdrew {amount} successfully."
            else:
                return "Insufficient funds for withdrawal."
        else:
            return "Invalid withdrawal amount."

    def check_balance(self):
        return f"Current balance: {self.balance}"


class Bank:
    def __init__(self):
        self.accounts = {}

    def open_account(self, account_number, account_holder):
        if account_number not in self.accounts:
            self.accounts[account_number] = BankAccount(account_number, account_holder)
            return f"Account {account_number} opened for {account_holder}."
        else:
            return "Account number already exists. Please choose a different number."

    def close_account(self, account_number):
        if account_number in self.accounts:
            del self.accounts[account_number]
            return f"Account {account_number} closed successfully."
        else:
            return "Account number does not exist."

    def perform_transaction(self, account_number, transaction_type, amount=0):
        if account_number in self.accounts:
            account = self.accounts[account_number]
            if transaction_type == "deposit":
                return account.deposit(amount)
            elif transaction_type == "withdraw":
                return account.withdraw(amount)
            elif transaction_type == "check_balance":
                return account.check_balance()
            else:
                return "Invalid transaction type."
        else:
            return "Account number does not exist."
```

This solution provides the implementation of the `BankAccount` and `Bank` classes in Python, fulfilling the requirements outlined in the problem description. The classes handle account creation, deposit, withdrawal, balance checking, and error handling for various scenarios.

