def create_url_mapping(url_patterns):
    url_mapping = {}
    for pattern, view_function in url_patterns:
        if view_function in url_mapping:
            url_mapping[view_function].append(pattern)
        else:
            url_mapping[view_function] = [pattern]
    return url_mapping
```

