```csharp
using System;
using System.ComponentModel.DataAnnotations;

namespace CustomValidation
{
    public class AddressValidationAttribute : ValidationAttribute
    {
        public override bool IsValid(object value)
        {
            if (value is string address)
            {
                if (address.Length < 5 || address.Length > 100)
                {
                    ErrorMessage = "Address length must be between 5 and 100 characters.";
                    return false;
                }

                if (!System.Text.RegularExpressions.Regex.IsMatch(address, @"^[a-zA-Z0-9,.\s-]*$"))
                {
                    ErrorMessage = "Address can only contain letters, numbers, commas, periods, hyphens, and spaces.";
                    return false;
                }

                return true;
            }

            return false;
        }
    }

    public class UserProfile
    {
        [AddressValidation(ErrorMessage = "Invalid address format.")]
        public string Address { get; set; }
