    public class AddressValidationAttribute : ValidationAttribute
    {
        public override bool IsValid(object value)
        {
            if (value is string address)
            {
                if (address.Length < 5 || address.Length > 100)
                {
                    ErrorMessage = "Address length must be between 5 and 100 characters.";
                    return false;
                }

                if (!System.Text.RegularExpressions.Regex.IsMatch(address, @"^[a-zA-Z0-9,.\s-]*$"))
                {
                    ErrorMessage = "Address can only contain letters, numbers, commas, periods, hyphens, and spaces.";
                    return false;
                }

                return true;
            }

            return false;
        }
    }

    public class UserProfile
    {
        [AddressValidation(ErrorMessage = "Invalid address format.")]
        public string Address { get; set; }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var userProfile = new UserProfile { Address = "123 Main Street" };
            var validationContext = new ValidationContext(userProfile);
            var validationResults = new System.Collections.Generic.List<ValidationResult>();

            if (!Validator.TryValidateObject(userProfile, validationContext, validationResults, true))
            {
                foreach (var validationResult in validationResults)
                {
                    Console.WriteLine(validationResult.ErrorMessage);
                }
            }
            else
            {
                Console.WriteLine("Address is valid.");
            }
        }
    }
}
