```python
class TextEditor:
    def __init__(self, initial_text):
        self._line = initial_text
        self._point = len(initial_text)

    def keyPressEvent(self, key):
        if key == QtCore.Qt.Key_Left:
            if self._point > 0:
                self._point -= 1
        elif key == QtCore.Qt.Key_Right:
            if self._point < len(self._line):
                self._point += 1
        elif key == QtCore.Qt.Key_Backspace:
            if self._point > 0:
                self._line = self._line[:self._point-1] + self._line[self._point:]
                self._point -= 1
        elif key == QtCore.Qt.Key_Delete:
            if self._point < len(self._line):
                self._line = self._line[:self._point] + self._line[self._point+1:]
        else:
            # Handle other key events
            pass
