def isRobotBounded(commands: str) -> bool:
    # Define the initial position and direction
    x, y = 0, 0
    dx, dy = 0, 1  # Initial direction: up

    # Execute the commands for 4 cycles to check if the robot returns to the original position or faces a different direction
    for _ in range(4):
        for command in commands:
            if command == 'G':
                x, y = x + dx, y + dy
            elif command == 'L':
                dx, dy = -dy, dx  # Rotate left
            elif command == 'R':
                dx, dy = dy, -dx  # Rotate right

    # If the robot returns to the original position or faces a different direction, it is bounded in a circle
    if (x, y) == (0, 0) or (dx, dy) != (0, 1):
        return True
    else:
        return False
