class Arc:
    def __init__(self, input_label, output_label, weight, next_state):
        self.input_label = input_label
        self.output_label = output_label
        self.weight = weight
        self.next_state = next_state

class VectorFST:
    def __init__(self):
        self.states = {}  # Dictionary to store arcs for each state

    def AddArc(self, state, arc):
        if state in self.states:
            self.states[state].append(arc)
        else:
            self.states[state] = [arc]

    def Print(self):
        for state, arcs in self.states.items():
            print(f"State {state}:")
            for arc in arcs:
                print(f"  {arc.input_label} / {arc.output_label} : {arc.next_state} ({arc.weight})")

    def Info(self):
        num_states = len(self.states)
        num_arcs = sum(len(arcs) for arcs in self.states.values())
        return f"Number of states: {num_states}, Number of arcs: {num_arcs}"

    def Write(self, filename):
        with open(filename, 'w') as file:
            for state, arcs in self.states.items():
                for arc in arcs:
                    file.write(f"{state} {arc.next_state} {arc.input_label} {arc.output_label} {arc.weight}\n")

# Usage example
if __name__ == '__main__':
    vector_fst = VectorFST()
    arc1 = Arc(0, 1, 0.5, 1)
    arc2 = Arc(1, 2, 0.3, 2)
    vector_fst.AddArc(0, arc1)
    vector_fst.AddArc(1, arc2)
    vector_fst.Print()
    print(vector_fst.Info())
    vector_fst.Write('a.fst')
    # fstprint tests/a.fst
```

In this solution, the `Arc` class represents an arc in the FST, and the `VectorFST` class provides methods for adding arcs, printing the FST, retrieving information, and writing the FST to a file. The usage example demonstrates how to create an FST, add arcs, print the FST, retrieve information, and write the FST to a file.

