#include <algorithm>

class Layer {
public:
    static scoped_refptr<Layer> Create() {
        return new Layer();
    }

    void AddChildLayer(scoped_refptr<Layer> childLayer) {
        children_.push_back(childLayer);
    }

    int GetChildCount() const {
        return children_.size();
    }

    const std::vector<scoped_refptr<Layer>>& GetChildLayers() const {
        return children_;
    }

private:
    std::vector<scoped_refptr<Layer>> children_;
};

int CalculateLayerTreeDepth(Layer* rootLayer) {
    if (rootLayer == nullptr) {
        return 0;
    }

    int maxChildDepth = 0;
    const std::vector<scoped_refptr<Layer>>& childLayers = rootLayer->GetChildLayers();
    for (const auto& child : childLayers) {
        maxChildDepth = std::max(maxChildDepth, CalculateLayerTreeDepth(child.get()));
    }

    return 1 + maxChildDepth;
}
```

The `CalculateLayerTreeDepth` function recursively calculates the depth of the layer tree by traversing the hierarchy and finding the maximum depth of the child layers. It returns the maximum depth of the layer hierarchy.

