import threading
import queue

class ThreadPool:
    def __init__(self, num_threads):
        self.num_threads = num_threads
        self.task_queue = queue.Queue()
        self.threads = []

        for _ in range(num_threads):
            thread = threading.Thread(target=self._worker)
            thread.daemon = True
            thread.start()
            self.threads.append(thread)

    def submit(self, task):
        self.task_queue.put(task)

    def _worker(self):
        while True:
            task = self.task_queue.get()
            if task is None:
                break
            task()
            self.task_queue.task_done()

    def wait_completion(self):
        self.task_queue.join()
        for _ in range(self.num_threads):
            self.task_queue.put(None)
        for thread in self.threads:
            thread.join()
```

This `ThreadPool` class initializes a specified number of worker threads and allows tasks to be submitted for concurrent execution. The `submit` method adds tasks to a queue, and each worker thread continuously retrieves tasks from the queue and executes them. The `wait_completion` method ensures that all submitted tasks are completed before proceeding.

