import fs from 'fs';
import crypto from 'crypto';

async function encryptFile(inputFilePath: string, outputFilePath: string, key: string): Promise<void> {
  const inputBuffer = fs.readFileSync(inputFilePath);
  const cipher = crypto.createCipheriv('aes-256-ctr', key, Buffer.alloc(16, 0));
  const encryptedBuffer = Buffer.concat([cipher.update(inputBuffer), cipher.final()]);
  fs.writeFileSync(outputFilePath, encryptedBuffer);
}

async function decryptFile(inputFilePath: string, outputFilePath: string, key: string): Promise<void> {
  const encryptedBuffer = fs.readFileSync(inputFilePath);
  const decipher = crypto.createDecipheriv('aes-256-ctr', key, Buffer.alloc(16, 0));
  const decryptedBuffer = Buffer.concat([decipher.update(encryptedBuffer), decipher.final()]);
  fs.writeFileSync(outputFilePath, decryptedBuffer);
}

// Example usage
const inputFilePath = 'input.txt';
const outputFilePath = 'encrypted.txt';
const key = 'supersecretkey';

encryptFile(inputFilePath, outputFilePath, key)
  .then(() => {
    console.log('File encrypted successfully');
    return decryptFile(outputFilePath, 'decrypted.txt', key);
  })
  .then(() => {
    console.log('File decrypted successfully');
  })
  .catch((error) => {
    console.error('An error occurred:', error);
  });
