def navigate_directory(current_path: str, navigation_string: str) -> str:
    # Split the navigation string by '/' to get individual commands
    commands = navigation_string.split('/')

    # Split the current path into individual directories
    directories = current_path.split('/')

    # Iterate through the commands and update the directories accordingly
    for command in commands:
