            if directories and directories[-1] != '':
                directories.pop()
        elif command != '.':
            directories.append(command)

    # Join the updated directories to form the new path
    new_path = '/'.join(directories)

    # Handle the case when the new path is empty (root directory)
    if not new_path:
        new_path = '/'

    return new_path
