                None
            } else {
                let parts: Vec<&str> = s.splitn(2, ' ').collect();
                let quantity = parts[0].parse().unwrap();
                let bag_name = parts[1].rsplitn(2, ' ').last().unwrap();
                Some((bag_name.to_string(), quantity))
            }
        })
        .collect();
