fn compute_num_bags(
    bag: &str,
    graph: &HashMap<String, Vec<(String, i32)>>,
    num_bags: &mut HashMap<String, i32>,
) -> i32 {
    if let Some(&num) = num_bags.get(bag) {
        return num;
    }
    let num = 1 + graph[bag]
        .iter()
        .map(|(contained_bag, quantity)| quantity * compute_num_bags(contained_bag, graph, num_bags))
        .sum::<i32>();
    num_bags.insert(bag.to_string(), num);
    num
}

