class Color:
    def __init__(self, hue=0, saturation=0, brightness=0):
        self.hue = hue
        self.saturation = saturation
        self.brightness = brightness

    def set_hue(self, hue):
        self.hue = hue

    def get_hue(self):
        return self.hue

    def set_saturation(self, saturation):
        self.saturation = saturation

    def get_saturation(self):
        return self.saturation

    def set_brightness(self, brightness):
        self.brightness = brightness

    def get_brightness(self):
        return self.brightness

    def hsb_to_rgb(self):
        c = (1 - abs(2 * self.brightness - 1)) * self.saturation
        x = c * (1 - abs((self.hue / 60) % 2 - 1))
        m = self.brightness - c / 2

        if 0 <= self.hue < 60:
            r, g, b = c, x, 0
        elif 60 <= self.hue < 120:
            r, g, b = x, c, 0
        elif 120 <= self.hue < 180:
            r, g, b = 0, c, x
        elif 180 <= self.hue < 240:
            r, g, b = 0, x, c
        elif 240 <= self.hue < 300:
            r, g, b = x, 0, c
        else:
            r, g, b = c, 0, x

        r = int((r + m) * 255)
        g = int((g + m) * 255)
        b = int((b + m) * 255)

        return r, g, b
```

