using System;

namespace NExtents
{
    /// <summary>
    /// Extensions for type <see cref="Enum"/>
    /// </summary>
    public static class EnumExtensions
    {
        /// <summary>
        /// Counts the number of elements in the enumeration that have the specified flag set.
        /// </summary>
        /// <param name="enumValue">The enumeration value.</param>
        /// <returns>The count of elements with the specified flag set.</returns>
        public static int CountFlaggedElements(this Enum enumValue)
        {
            int count = 0;
            foreach (Enum value in Enum.GetValues(enumValue.GetType()))
