def encode_pheniqs_config(config):
    encoded_config = {}
    for key, value in config.items():
        if isinstance(value, list):
            encoded_config[key] = value
        elif isinstance(value, dict) and value.get('type') == 'object' and value.get('plural') and value.get('value'):
            encoded_config[key] = [encode_pheniqs_config(e) for e in value['value']]
        else:
            encoded_config[key] = value
    return encoded_config
