import os
import sys

def create_file(file_name):
    try:
        with open(file_name, 'w'):
            pass
        print(f"File '{file_name}' created successfully.")
    except OSError as e:
        print(f"Error creating file '{file_name}': {e}")

def update_file(file_name):
    if os.path.exists(file_name):
        try:
            with open(file_name, 'a') as file:
                file.write("Updated content\n")
            print(f"File '{file_name}' updated successfully.")
        except OSError as e:
            print(f"Error updating file '{file_name}': {e}")
    else:
        print(f"File '{file_name}' does not exist.")

def delete_file(file_name):
    if os.path.exists(file_name):
        try:
            os.remove(file_name)
            print(f"File '{file_name}' deleted successfully.")
        except OSError as e:
            print(f"Error deleting file '{file_name}': {e}")
    else:
        print(f"File '{file_name}' does not exist.")

def list_files():
    files = [f for f in os.listdir('.') if os.path.isfile(f)]
    if files:
        print("Files in the project directory:")
        for file in files:
            print(file)
    else:
        print("No files found in the project directory.")

def main():
    if len(sys.argv) < 2:
        print("Usage: python project_manager.py <command> [args]")
        return

    command = sys.argv[1]
    if command == '--create-file' and len(sys.argv) == 3:
        create_file(sys.argv[2])
    elif command == '--update-file' and len(sys.argv) == 3:
        update_file(sys.argv[2])
    elif command == '--delete-file' and len(sys.argv) == 3:
        delete_file(sys.argv[2])
    elif command == '--list-files':
        list_files()
    else:
        print("Invalid command or arguments.")

if __name__ == "__main__":
