use {
    fidl_fidl_examples_routing_echo as fecho, fuchsia_async as fasync,
    fuchsia_component::server::ServiceFs, futures::StreamExt,
};

enum ExposedServices {
    Echo(fecho::EchoRequestStream),
}

#[fasync::run_singlethreaded]
async fn main() {
    let mut fs = ServiceFs::new_local();
    fs.dir("svc").add_fidl_service(ExposedServices::Echo);
    fs.take_and_serve_directory_handle().expect("failed to serve outgoing directory");
    let ExposedServices::Echo(mut stream) = fs.next().await.unwrap();

    while let Some(request) = stream.next().await {
        match request {
            Ok(fecho::EchoRequest::EchoString { value, responder }) => {
                // Echo the received message back to the client
                let _ = responder.send(value);
            }
            Err(err) => {
                // Handle any potential errors that may occur during the communication process
                eprintln!("Error handling echo request: {:?}", err);
            }
        }
    }
}
```

