import numpy as np

def Rotate(angle):
    return np.array([[np.cos(angle), -np.sin(angle)], [np.sin(angle), np.cos(angle)]])

def Translate(translation):
    return np.array([[1, 0, translation[0]], [0, 1, translation[1]], [0, 0, 1]])

def Scale(factor):
    return np.array([[factor, 0, 0], [0, factor, 0], [0, 0, 1]])

# Apply transformations
M = np.eye(3)  # Identity matrix
M = M @ Rotate(0.1) @ Translate((3, 1)) @ Scale(1.01)

# Write transformation matrix to Ipe file
with open('matrix_fun.ipe', 'w') as file:
    file.write('<ipe version="70000">\n')
    file.write('<ipestyle name="transform" family="transform" extends="basic">\n')
    file.write('<transform name="M">\n')
    for row in M:
        file.write(' '.join(map(str, row)) + '\n')
    file.write('</transform>\n')
    file.write('</ipestyle>\n')
    file.write('</ipe>\n')
```

In this solution, we define the `Rotate`, `Translate`, and `Scale` functions to generate the corresponding transformation matrices. We then apply these transformations to the identity matrix `M` in the specified order. Finally, we write the resulting transformation matrix to an Ipe file in the required format.

