```python
import time

class ProfilerManager:
    def __init__(self):
        self.profiler_registry = {}

    def profiler_decorator(self, name=None):
        def decorator(func):
            def wrapper(*args, **kwargs):
                start_time = time.time()
                result = func(*args, **kwargs)
                end_time = time.time()
                execution_time = end_time - start_time
                if name:
                    print(f"{name} profiler: {func.__name__} executed in {execution_time} seconds")
                else:
                    print(f"Default profiler: {func.__name__} executed in {execution_time} seconds")
                return result
            return wrapper
        return decorator

    def get_profiler(self, name):
        builder = self.profiler_registry.get(name)
        if builder:
            return builder()
        else:
            raise ValueError("Profiler not found: {}".format(name))

# Example usage
profiler_manager = ProfilerManager()

@profiler_manager.profiler_decorator("Custom")
def example_function():
    time.sleep(2)

example_function()
```

