```
The function should perform the following validations:
1. Check if the JSON payload contains all the required fields: "description", "subject", and "notification".
2. Ensure that the "subject" field contains "entities" and "condition" subfields.
3. Verify that the "entities" subfield under "subject" contains at least one entity with "id" and "type" fields.
4. Confirm that the "condition" subfield under "subject" contains an "attrs" array with at least one attribute.

Your task is to implement the function `validateSubscription(payload)` that takes a JSON payload as input and returns `true` if the payload is valid according to the specified structure and requirements, and `false` otherwise.

Function Signature: `func validateSubscription(payload string) bool`

output:
```go
package main

import (
	"encoding/json"
	"fmt"
)

type Subscription struct {
	Description  string `json:"description"`
	Subject      struct {
		Entities  []struct {
			ID   string `json:"id"`
			Type string `json:"type"`
		} `json:"entities"`
		Condition struct {
			Attrs []string `json:"attrs"`
		} `json:"condition"`
	} `json:"subject"`
	Notification struct {
		Http struct {
			URL string `json:"url"`
		} `json:"http"`
	} `json:"notification"`
}

func validateSubscription(payload string) bool {
	var sub Subscription
	err := json.Unmarshal([]byte(payload), &sub)
	if err != nil {
		return false
	}

	if sub.Description == "" || sub.Subject.Entities == nil || len(sub.Subject.Entities) == 0 || sub.Subject.Condition.Attrs == nil || len(sub.Subject.Condition.Attrs) == 0 || sub.Notification.Http.URL == "" {
		return false
	}

	return true
}

func main() {
	validPayload := `{
		"description": "A subscription to get info about Room1",
		"subject": {
			"entities": [
				{
					"id": "Room1",
					"type": "Room"
				}
			],
			"condition": {
				"attrs": [
					"temperature"
				]
			}
		},
		"notification": {
			"http": {
				"url": "http://example.com/notify"
			}
		}
	}`

	invalidPayload := `{
		"description": "Invalid subscription payload",
		"subject": {
			"entities": [],
			"condition": {
				"attrs": []
			}
		},
		"notification": {
			"http": {
				"url": ""
			}
		}
	}`

	fmt.Println(validateSubscription(validPayload))   // Output: true
	fmt.Println(validateSubscription(invalidPayload)) // Output: false
}
```

