import java.util.*;

public class Index {
    private Map<String, Set<Document>> indexMap;

    public Index() {
        indexMap = new HashMap<>();
    }

    public void addDocument(Document document) {
        for (String key : document.getIndexKeys()) {
            indexMap.computeIfAbsent(key, k -> new HashSet<>()).add(document);
        }
    }

    public List<Document> searchDocuments(Set<String> indexKeys) {
        List<Document> result = new ArrayList<>();
        boolean firstKey = true;
        for (String key : indexKeys) {
            Set<Document> documents = indexMap.get(key);
            if (documents != null) {
                if (firstKey) {
                    result.addAll(documents);
                    firstKey = false;
                } else {
                    result.retainAll(documents);
                }
            } else {
                return Collections.emptyList(); // No documents match the given keys
            }
        }
        return result;
    }
}

class Document {
    private String title;
    private Set<String> indexKeys;

    public Document(String title, Set<String> indexKeys) {
        this.title = title;
        this.indexKeys = indexKeys;
    }

    public Set<String> getIndexKeys() {
        return indexKeys;
    }
}
```

