function findClosestAnchor(x, y, anchors) {
    let minDistance = Number.MAX_VALUE;
    let closestAnchor = null;

    for (const anchor of anchors) {
        const distance = Math.sqrt(Math.pow(x - anchor.x, 2) + Math.pow(y - anchor.y, 2));
