#include <iostream>
#include <thread>
#include <chrono>
#include <vector>
#include <mutex>
#include <condition_variable>

class Server {
public:
    static const int THREAD_COUNT = 5; // Number of threads in the thread pool
    std::vector<std::thread> thread_pool;
    std::mutex mtx;
    std::condition_variable cv;
    bool stop_server = false;

    void processRequest(int clientID) {
        // Process the incoming network request for the given clientID
        // Implement the request processing logic here
        std::cout << "Processing request for client " << clientID << std::endl;
    }

    void handleRequests() {
        while (!stop_server) {
            // Wait for a network request and process it
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock);
            if (stop_server) {
                break;
            }
            processRequest(getNextClientID());
        }
    }

    int getNextClientID() {
        // Simulate obtaining the next client ID from the network
        static int clientID = 1;
        return clientID++;
    }

    void startServer() {
        for (int i = 0; i < THREAD_COUNT; ++i) {
            thread_pool.emplace_back(&Server::handleRequests, this);
        }
    }

    void stopServer() {
        stop_server = true;
        cv.notify_all(); // Notify all threads to stop
        for (auto& thread : thread_pool) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }
};

int main() {
    Server srv;
    srv.startServer();

    // Simulate the server running for a period of time
    std::this_thread::sleep_for(std::chrono::seconds(10));

    // Stop the server
    srv.stopServer();

    return 0;
}
```

In the provided solution, the `Server` class encapsulates the server functionality, including the thread pool management and request handling. The `startServer` method initializes the thread pool and starts the server, while the `stopServer` method gracefully shuts down the server by notifying all threads to stop and joining them. The `handleRequests` method waits for incoming requests using a condition variable and processes them using the `processRequest` method. The main function demonstrates the usage of the `Server` class by starting the server, simulating its operation, and then stopping it after a specified duration.

