    let pairs = input.components(separatedBy: ",")
    var streamURL = ""

    for pair in pairs {
        let keyValue = pair.components(separatedBy: ":")
        if keyValue.count == 2 {
            let key = keyValue[0].trimmingCharacters(in: .whitespaces)
            let value = keyValue[1].trimmingCharacters(in: .whitespaces)
