def encodeList(list_to_encode):
    if not list_to_encode:
        return []
    else:
        tmp = []
        tmp.append(list_to_encode[0])
        tmp.append(1)
        i = 1
        while i < len(list_to_encode) and list_to_encode[i] == tmp[0]:
            tmp[1] += 1
            i += 1
        return tmp + encodeList(list_to_encode[i:])
```

