import subprocess

def compile_c_code(source, output_filename, args, remainder):
    cpp_args = ["cpp", "-nostdinc", "-undef"]

    if args['version']:
        cpp_args.append(f"-DVERSION={args['version']}")
    if args['preproc']:
        cpp_args.append(f"-I{args['preproc']}")
    if args['charmap']:
        cpp_args.append(f"-charset={args['charmap']}")

    cpp_args.append(source)

    if args['-S']:
        gcc_args = ["gcc", "-S"]
    else:
        gcc_args = ["gcc", "-c"]

    if args['no_parse']:
        gcc_args.append("-fno-asm")

    if args['-o']:
        gcc_args.extend(["-o", args['-o']])
    else:
        gcc_args.extend(["-o", output_filename])

    gcc_args.append(source)

    try:
        subprocess.run(cpp_args, check=True)
        subprocess.run(gcc_args, check=True)
        return True
    except subprocess.CalledProcessError:
        return False
```

This solution constructs the appropriate command-line arguments for the C preprocessor (`cpp`) and the C compiler (`gcc`) based on the parsed arguments and options. It then executes the commands using the `subprocess` module and returns a boolean indicating the success of the compilation.

