def parse_configuration(file_path):
    interfaces = {}
    instances = {}
    with open(file_path, 'r') as file:
        for line in file:
            tokens = line.split()
            if tokens[0] == 'set':
                if tokens[1] == 'interfaces':
                    if tokens[3] == 'subinterfaces':
                        interface_name = tokens[2]
                        sub_id = tokens[5]
                        if tokens[6] == 'vlan':
                            vlan_id = tokens[9]
                            if interface_name not in interfaces:
                                interfaces[interface_name] = Interface(interface_name)
                            interfaces[interface_name].add_subinterface(sub_id, vlan_id)
                        elif tokens[6] == 'config' and tokens[7] == 'enabled' and tokens[8] == 'true':
                            if sub_id not in interfaces[interface_name].subinterfaces:
                                interfaces[interface_name].add_subinterface(sub_id, None)
                    elif tokens[3] == 'config' and tokens[4] == 'enabled' and tokens[5] == 'true':
                        interface_name = tokens[2]
                        if interface_name not in interfaces:
                            interfaces[interface_name] = Interface(interface_name)
                elif tokens[1] == 'network-instances':
                    instance_name = tokens[2]
                    if tokens[3] == 'config' and tokens[4] == 'type':
                        instance_type = tokens[6]
                        if instance_name not in instances:
                            instances[instance_name] = NetworkInstance(instance_name)
                    elif tokens[3] == 'config' and tokens[4] == 'enabled' and tokens[5] == 'true':
                        if instance_name not in instances:
                            instances[instance_name] = NetworkInstance(instance_name)
                    elif tokens[3] == 'vlans' and tokens[4] == 'vlan':
                        vlan_id = tokens[5]
                        if tokens[6] == 'config' and tokens[7] == 'status':
                            status = tokens[9]
                            instances[instance_name].add_vlan_status(vlan_id, status)

    return interfaces, instances

def analyze_configuration(file_path):
    interfaces, instances = parse_configuration(file_path)

    print("Enabled Interfaces:")
    for interface in interfaces.values():
        if interface.is_enabled():
            print(interface.name)

    print("\nInterfaces with Configured VLANs:")
    for interface, subinterfaces in interfaces.items():
        for sub_id, vlan_id in subinterfaces.subinterfaces.items():
            if vlan_id is not None:
                print(f"{interface} subinterface {sub_id} - VLAN ID: {vlan_id}")

    print("\nEnabled Network Instances:")
    for instance in instances.values():
        if instance.is_enabled():
            print(instance.name)

    print("\nNetwork Instances with VLAN Status:")
    for instance, vlans in instances.items():
        for vlan_id, status in vlans.vlans.items():
            print(f"{instance} - VLAN {vlan_id} - Status: {status}")

