struct CustomJSONEncodingStrategy: JSONEncoder {
    override func encode<T>(_ value: T) throws -> Data where T : Encodable {
        var container = self.container()
        let user = value as! UserProfile

        try container.encode(user.name.uppercased(), forKey: .name)
        try container.encode("Age: \(user.age)", forKey: .age)
