class CtorLookupC {
public:
    template <typename T>
    CtorLookupC(T&& callable) {
        if constexpr (std::is_function<std::remove_pointer_t<std::decay_t<T>>>::value) {
            callableType = "function pointer";
        } else if constexpr (std::is_class<std::remove_reference_t<std::decay_t<T>>>::value) {
            callableType = "function object";
        } else if constexpr (std::is_invocable<T>::value) {
            callableType = "lambda";
        } else {
            callableType = "invalid callable";
        }
    }

    std::string getCallableType() const {
        return callableType;
    }

private:
    std::string callableType;
};

int main() {
    int x = 5;
    auto lambda = [&x]() { return x; };
    CtorLookupC lambdaLookup(lambda);
    std::cout << "Lambda type: " << lambdaLookup.getCallableType() << std::endl;

    struct Functor {
        int operator()() const { return 42; }
    };
    Functor functor;
    CtorLookupC functorLookup(functor);
    std::cout << "Functor type: " << functorLookup.getCallableType() << std::endl;

    int (*funcPtr)() = []() { return 0; };
    CtorLookupC funcPtrLookup(funcPtr);
    std::cout << "Function pointer type: " << funcPtrLookup.getCallableType() << std::endl;

    CtorLookupC invalidLookup(42);
    std::cout << "Invalid callable type: " << invalidLookup.getCallableType() << std::endl;

    return 0;
}
