class Queue {
    private var elements: [Character] = []

    /**
     Add a character to the start of the queue (will be the next character retrieved).
     @param c character to add
     */
    func addFirst(_ c: Character) {
        elements.insert(c, at: 0)
    }

    /**
     Remove and return the character at the front of the queue. If the queue is empty, return nil.
     @return the character at the front of the queue, or nil if the queue is empty
     */
    func removeFirst() -> Character? {
        return elements.isEmpty ? nil : elements.removeFirst()
    }

    /**
     Add a character to the end of the queue.
     @param c character to add
     */
    func addLast(_ c: Character) {
        elements.append(c)
    }

    /**
     Remove and return the character at the end of the queue. If the queue is empty, return nil.
     @return the character at the end of the queue, or nil if the queue is empty
     */
    func removeLast() -> Character? {
        return elements.isEmpty ? nil : elements.removeLast()
    }

    /**
     Return the character at the front of the queue without removing it. If the queue is empty, return nil.
     @return the character at the front of the queue, or nil if the queue is empty
     */
    func peekFirst() -> Character? {
        return elements.first
    }

    /**
     Return the character at the end of the queue without removing it. If the queue is empty, return nil.
     @return the character at the end of the queue, or nil if the queue is empty
     */
    func peekLast() -> Character? {
        return elements.last
    }
}
