import java.util.HashMap;
import java.util.Map;
import java.util.ArrayList;
import java.util.List;

public class EventListenerSystem {
    private Map<EventType, List<EventListener>> listeners;

    public EventListenerSystem() {
        this.listeners = new HashMap<>();
        for (EventType type : EventType.values()) {
            this.listeners.put(type, new ArrayList<>());
        }
    }

    public void registerListener(EventListener listener, EventType eventType) {
        List<EventListener> eventListeners = listeners.get(eventType);
        eventListeners.add(listener);
    }

    public void unregisterListener(EventListener listener, EventType eventType) {
        List<EventListener> eventListeners = listeners.get(eventType);
        eventListeners.remove(listener);
    }

    public void triggerEvent(EventType eventType, Event event) {
        List<EventListener> eventListeners = listeners.get(eventType);
        for (EventListener listener : eventListeners) {
            listener.onEvent(event);
        }
    }
}
