package com.drive.monitor.service.mapstruct;

import java.lang.reflect.Field;

public abstract class BaseMapStruct<S, T> {

    public T map(S source, Class<T> targetType) throws IllegalAccessException, InstantiationException {
        T target = targetType.newInstance();
        Field[] sourceFields = source.getClass().getDeclaredFields();
        Field[] targetFields = targetType.getDeclaredFields();

        for (Field sourceField : sourceFields) {
            for (Field targetField : targetFields) {
                if (sourceField.getName().equals(targetField.getName()) && sourceField.getType().equals(targetField.getType())) {
                    sourceField.setAccessible(true);
                    targetField.setAccessible(true);
                    targetField.set(target, sourceField.get(source));
                }
            }
        }
        return target;
    }
}
```

