You are tasked with implementing a C++ class that simulates a simple stack data structure. The stack should support the following operations:
1. `push(int val)`: Add an integer `val` to the top of the stack.
2. `pop()`: Remove the element at the top of the stack and return its value. If the stack is empty, return -1.
3. `top()`: Return the value of the element at the top of the stack without removing it. If the stack is empty, return -1.
4. `isEmpty()`: Return a boolean indicating whether the stack is empty.

Your task is to implement the `Stack` class with the above operations using an array as the underlying data structure. You should also ensure that the stack has a maximum capacity and handle the case where the stack is full.

You are provided with a code snippet for inspiration, but you are not required to use it in your solution.

```cpp
#include <iostream>

class Stack {
private:
    int *arr;
    int topIndex;
    int capacity;

public:
    Stack(int size) {
        capacity = size;
        arr = new int[capacity];
        topIndex = -1;
    }

    void push(int val) {
        if (topIndex == capacity - 1) {
            std::cout << "Stack overflow" << std::endl;
            return;
        }
        arr[++topIndex] = val;
    }

    int pop() {
        if (topIndex == -1) {
            std::cout << "Stack underflow" << std::endl;
            return -1;
        }
        return arr[topIndex--];
    }

    int top() {
        if (topIndex == -1) {
            std::cout << "Stack is empty" << std::endl;
            return -1;
        }
        return arr[topIndex];
    }

    bool isEmpty() {
        return topIndex == -1;
    }

    ~Stack() {
        delete[] arr;
    }
};

int main() {
    Stack stack(5);
    stack.push(1);
    stack.push(2);
    stack.push(3);
    std::cout << stack.pop() << std::endl;
    std::cout << stack.top() << std::endl;
    std::cout << stack.isEmpty() << std::endl;
    return 0;
}
```

