class TextEditor:
    def __init__(self):
        self.lines = [""]
        self.current_line = 0

    def type(self, text):
        while len(text) > 80:
            self.lines[self.current_line] += text[:80]
            text = text[80:]
            self.lines.append("")
            self.current_line += 1
        self.lines[self.current_line] += text
        if len(self.lines[self.current_line]) > 80:
            self.lines.append(self.lines[self.current_line][80:])
            self.lines[self.current_line] = self.lines[self.current_line][:80]
            self.current_line += 1

    def backspace(self):
        if len(self.lines[self.current_line]) == 0 and self.current_line > 0:
            self.current_line -= 1
            self.lines[self.current_line] += self.lines.pop()
        else:
            self.lines[self.current_line] = self.lines[self.current_line][:-1]

    def moveUp(self):
        if self.current_line > 0:
            self.current_line -= 1

    def moveDown(self):
        if self.current_line < len(self.lines) - 1:
            self.current_line += 1

    def getCurrentLine(self):
        return self.lines[self.current_line]
```

