class Signal:
    def __init__(self):
        self._callbacks = {}

    def connect(self, signal, address, subnet, callback):
        if signal not in self._callbacks:
            self._callbacks[signal] = {}
        if (address, subnet) not in self._callbacks[signal]:
            self._callbacks[signal][(address, subnet)] = []
        self._callbacks[signal][(address, subnet)].append(callback)

    def disconnect(self, signal, address, subnet):
        try:
            del self._callbacks[signal][(address, subnet)]
        except KeyError:
            pass
