    private bool CanModifyActivities { get; set; }
    private List<DiscountRule> discountRules;

    public DiscountPolicyWorkflow()
    {
        CanModifyActivities = true;
        discountRules = new List<DiscountRule>();
    }

    public void AddDiscountRule(Func<Item, bool> condition, double discountPercentage)
    {
        discountRules.Add(new DiscountRule(condition, discountPercentage));
    }

    public double CalculateDiscountedPrice(Item item)
    {
        double discountedPrice = item.OriginalPrice;
        foreach (var rule in discountRules)
        {
            if (rule.Condition(item))
            {
                discountedPrice -= (discountedPrice * rule.DiscountPercentage / 100);
            }
        }
        return discountedPrice;
    }
}

public class Item
