import re

def parse_code_snippet(code_snippet):
    module_ratings = {}
    star_range = re.search(r'<gh_stars>(\d+)-(\d+)', code_snippet)
    if star_range:
        start, end = int(star_range.group(1)), int(star_range.group(2))
        modules = re.findall(r'pub mod (\w+);', code_snippet)
        for module in modules:
            module_ratings[module] = list(range(start, end + 1))
    return module_ratings

