protected void transformBodyElements(Keyframes keyframes, Keyframes transformed, EvaluationContext context) {
    EvaluationContext mediaContext = new EvaluationContext();

    // Iterate through the body elements of the keyframes
    for (BodyElement element : keyframes.getBodyElements()) {
        // Apply transformations based on the evaluation context
        if (context.shouldTransform(element)) {
            BodyElement transformedElement = context.applyTransformation(element);
            transformed.addBodyElement(transformedElement);
