import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class JavaSourceFileProcessor {
    public static void main(String[] args) {
        String sourceCode = "/*\n" +
                " * This file was automatically generated by com.microsoft.tfs.core.ws.generator.Generator\n" +
                " * from the /complexType.vm template.\n" +
                " */\n" +
                "package ms.tfs.build.buildservice._03;\n" +
                "\n" +
                "import com.microsoft.tfs.core.ws.runtime.*;";

        extractPackageAndLicense(sourceCode);
    }

    public static void extractPackageAndLicense(String sourceCode) {
        Pattern packagePattern = Pattern.compile("package\\s+(\\S+);");
        Matcher packageMatcher = packagePattern.matcher(sourceCode);
        if (packageMatcher.find()) {
            String packageName = packageMatcher.group(1);
            System.out.println("Package Name: " + packageName);
        }

        Pattern licensePattern = Pattern.compile("/\\*.*?\\*/", Pattern.DOTALL);
        Matcher licenseMatcher = licensePattern.matcher(sourceCode);
        if (licenseMatcher.find()) {
            String licenseComment = licenseMatcher.group();
            String license = extractLicenseType(licenseComment);
            System.out.println("License: " + license);
        }
    }

    public static String extractLicenseType(String licenseComment) {
        if (licenseComment.contains("MIT license")) {
            return "MIT license";
        } else if (licenseComment.contains("Apache license")) {
            return "Apache license";
        } else {
            return "Unknown license";
        }
    }
}
