You are tasked with implementing a custom `Iota` class that represents a sequence of consecutive integers and a `Model` class that provides various operations on the sequence. The `Iota` class should support the following functionalities:
1. Constructing an `Iota` object with a starting value and a count of elements.
2. Accessing the elements of the sequence using the subscript operator `[]`.
3. Iterating over the elements using range-based for loop.

The `Model` class should provide the following operations on the `Iota` sequence:
1. `sum`: Calculate the sum of all elements in the sequence.
2. `product`: Calculate the product of all elements in the sequence.
3. `average`: Calculate the average of all elements in the sequence.

You need to implement the `Iota` and `Model` classes with the specified functionalities.

```cpp
#include <iostream>
#include <vector>

namespace iota {
    class Iota {
    private:
        int start;
        int count;
    public:
        Iota(int start, int count) : start(start), count(count) {}

        int operator[](int index) const {
            return start + index;
        }

        int size() const {
            return count;
        }

        class iterator {
        private:
            int current;
        public:
            iterator(int start) : current(start) {}

            int operator*() const {
                return current;
            }

            iterator& operator++() {
                ++current;
                return *this;
            }

            bool operator!=(const iterator& other) const {
                return current != other.current;
            }
        };

        iterator begin() const {
            return iterator(start);
        }

        iterator end() const {
            return iterator(start + count);
        }
    };

    class Model {
    public:
        static int sum(const Iota& sequence) {
            int result = 0;
            for (int i = 0; i < sequence.size(); ++i) {
                result += sequence[i];
            }
            return result;
        }

        static int product(const Iota& sequence) {
            int result = 1;
            for (int i = 0; i < sequence.size(); ++i) {
                result *= sequence[i];
            }
            return result;
        }

        static double average(const Iota& sequence) {
            return static_cast<double>(sum(sequence)) / sequence.size();
        }
    };
}

int main() {
    using namespace iota;
    using namespace model;

    Iota sequence(1, 5);
    std::cout << "Sum: " << Model::sum(sequence) << std::endl;
    std::cout << "Product: " << Model::product(sequence) << std::endl;
    std::cout << "Average: " << Model::average(sequence) << std::endl;

    return 0;
}
```

