using System.Collections.Concurrent;

public interface ITelemetrySink
{
    void ReportMetric(string name, double value);
    void ReportMeter(string name, double value);
}

public class Telemetry
{
    private ConcurrentDictionary<string, MetricTracker> metricDictionary = new ConcurrentDictionary<string, MetricTracker>();
    private ConcurrentDictionary<string, MeterTracker> meterDictionary = new ConcurrentDictionary<string, MeterTracker>();
    private ITelemetrySink[] _sinks;

    public Telemetry(ITelemetrySink[] sinks)
    {
        _sinks = sinks;
    }

    public void TrackMetric(string name, double value)
    {
        metricDictionary.AddOrUpdate(name, new MetricTracker(), (key, existing) =>
        {
            existing.Track(value);
            return existing;
        });
    }

    public void TrackMeter(string name, double value)
    {
        meterDictionary.AddOrUpdate(name, new MeterTracker(), (key, existing) =>
        {
            existing.Track(value);
            return existing;
        });
    }

    public void ReportToSinks()
    {
        foreach (var sink in _sinks)
        {
            foreach (var entry in metricDictionary)
            {
                sink.ReportMetric(entry.Key, entry.Value.GetReportedValue());
            }
            foreach (var entry in meterDictionary)
            {
                sink.ReportMeter(entry.Key, entry.Value.GetReportedValue());
            }
        }
    }
}

public class MetricTracker
{
    private double total;
    private int count;

    public void Track(double value)
    {
        total += value;
        count++;
    }

    public double GetReportedValue()
    {
        if (count == 0) return 0;
        return total / count;
    }
}

public class MeterTracker
{
    private double total;
    private int count;

    public void Track(double value)
    {
        total += value;
        count++;
    }

    public double GetReportedValue()
    {
        return count;
    }
}
```

