```python
def process_migrations(dependencies, operations):
    dependency_graph = {}
    for dependency in dependencies:
        if dependency[1] not in dependency_graph:
            dependency_graph[dependency[1]] = []
        dependency_graph[dependency[1]].append(dependency[0])

    def dfs(node, visited, result):
        visited.add(node)
        if node in dependency_graph:
            for dependency in dependency_graph[node]:
                if dependency not in visited:
                    dfs(dependency, visited, result)
        result.append(node)

    visited = set()
    result = []
    for dependency in dependency_graph:
        if dependency not in visited:
            dfs(dependency, visited, result)

    ordered_operations = []
    for migration_file in result:
        for operation in operations:
            if migration_file in str(operation):
                ordered_operations.append(operation)

    return ordered_operations
```

