function extractFileName(filePath) {
    // Split the file path by the directory separator '/'
    const pathParts = filePath.split('/');
    // Get the last part of the path which represents the file name
    const fileNameWithExtension = pathParts[pathParts.length - 1];
    // Split the file name by the period to separate the name and extension
    const fileNameParts = fileNameWithExtension.split('.');
    // Join all parts except the last one to get the file name without the extension
    const fileName = fileNameParts.slice(0, -1).join('.');
    return fileName;
}

