const sqlite3 = require('sqlite3');

class CliDatabase {
    constructor(sqliteModule, dbPath, errorCallback) {
        this.db = new sqliteModule.Database(dbPath, (err) => {
            if (err) {
                errorCallback(err);
            }
        });
    }

    insert(tableName, data) {
        return new Promise((resolve, reject) => {
            const columns = Object.keys(data).join(', ');
            const placeholders = Object.keys(data).map(() => '?').join(', ');
            const values = Object.values(data);

            const sql = `INSERT INTO ${tableName} (${columns}) VALUES (${placeholders})`;

            this.db.run(sql, values, function (err) {
                if (err) {
                    reject(err);
                } else {
                    resolve(this.lastID);
                }
            });
        });
    }

    query(sql) {
        return new Promise((resolve, reject) => {
            this.db.all(sql, (err, rows) => {
                if (err) {
                    reject(err);
                } else {
                    resolve(rows);
                }
            });
        });
    }

    update(tableName, newData, condition) {
        return new Promise((resolve, reject) => {
            const columns = Object.keys(newData).map(column => `${column} = ?`).join(', ');
            const values = Object.values(newData);
            const conditions = Object.keys(condition).map(column => `${column} = ?`).join(' AND ');
            const conditionValues = Object.values(condition);

            const sql = `UPDATE ${tableName} SET ${columns} WHERE ${conditions}`;

            this.db.run(sql, [...values, ...conditionValues], function (err) {
                if (err) {
                    reject(err);
                } else {
                    resolve(this.changes);
                }
            });
        });
    }

    delete(tableName, condition) {
        return new Promise((resolve, reject) => {
            const conditions = Object.keys(condition).map(column => `${column} = ?`).join(' AND ');
            const conditionValues = Object.values(condition);

            const sql = `DELETE FROM ${tableName} WHERE ${conditions}`;

            this.db.run(sql, conditionValues, function (err) {
                if (err) {
                    reject(err);
                } else {
                    resolve(this.changes);
                }
            });
        });
    }
}

module.exports = CliDatabase;
```
In this solution, the `CliDatabase` class is implemented to handle CRUD operations on a SQLite database using the provided SQLite3 module. The class constructor initializes the database connection and handles any initialization errors by invoking the provided callback function.

The `insert`, `query`, `update`, and `delete` methods are implemented to provide a clean and intuitive API for interacting with the SQLite database through the command line. Each method returns a promise to handle asynchronous database operations and properly handle errors.

The `insert` method constructs and executes an SQL INSERT statement to insert data into the specified table, while the `query` method executes the provided SQL query and returns the results. The `update` and `delete` methods similarly construct and execute SQL UPDATE and DELETE statements, respectively, to update and delete records from the specified table based on the provided conditions.

Overall, this solution demonstrates proper error handling, asynchronous operation, and a clean API for interacting with a SQLite database through a command-line interface.

