fn convert_fp_mmx_registers(from: &SourceStruct, fpu_state: &mut DestinationStruct) -> DestinationStruct {
    for idx in 0..NUM_FPMMX_REGS {
        let from_idx = WinFpRegIndex::FpMmx0 as usize + idx;
