using System;
using System.Collections.Generic;

public class DependencyResolver
{
    private Dictionary<Type, object> _dependencies = new Dictionary<Type, object>();

    public void Register<T>(T instance)
    {
        _dependencies[typeof(T)] = instance;
    }

    public T Resolve<T>() where T : class
    {
        if (_dependencies.TryGetValue(typeof(T), out object instance))
        {
            return (T)instance;
        }
        else
        {
            throw new InvalidOperationException($"Dependency of type {typeof(T).Name} is not registered.");
        }
    }

    public T Resolve<T>(string name)
    {
        if (_dependencies.TryGetValue(typeof(T), out object instance))
        {
            // Assume the named instances are stored in a dictionary
            if (instance is Dictionary<string, T> namedInstances)
            {
                if (namedInstances.TryGetValue(name, out T namedInstance))
                {
                    return namedInstance;
                }
                else
                {
                    throw new InvalidOperationException($"Named instance '{name}' of type {typeof(T).Name} is not registered.");
                }
            }
        }
        throw new InvalidOperationException($"Dependency of type {typeof(T).Name} is not registered.");
    }
}

// Usage scenario
public class Program
{
    public static void Main()
    {
        DependencyResolver resolver = new DependencyResolver();

        // Registering a named instance
        Dictionary<string, IService> namedServices = new Dictionary<string, IService>
        {
            { "service1", new Service1() },
            { "service2", new Service2() }
        };
        resolver.Register(namedServices);

        // Resolving named instances
        IService service1 = resolver.Resolve<IService>("service1");
        IService service2 = resolver.Resolve<IService>("service2");

        Console.WriteLine(service1.GetName()); // Output: Service 1
        Console.WriteLine(service2.GetName()); // Output: Service 2
    }
}

public interface IService
{
    string GetName();
}

public class Service1 : IService
{
    public string GetName()
    {
        return "Service 1";
    }
}

public class Service2 : IService
{
    public string GetName()
    {
        return "Service 2";
    }
}
```

In the solution, the `DependencyResolver` class is completed with the `Register` method to register dependencies and the implementation of the `Resolve` methods to resolve dependencies. Additionally, a usage scenario is provided to demonstrate the usage of the `DependencyResolver` class for resolving named instances of services.

