import RxSwift
import MaterialComponents

struct Book {
    let title: String
    let author: String
    let thumbnailURL: URL
}

func searchBooks(query: String) -> Observable<[Book]> {
    guard let url = URL(string: "https://www.googleapis.com/books/v1/volumes?q=\(query)") else {
        return Observable.error(NSError(domain: "Invalid URL", code: 0, userInfo: nil))
    }

    return URLSession.shared.rx.data(request: URLRequest(url: url))
        .map { data in
            let decoder = JSONDecoder()
            do {
                let response = try decoder.decode(GoogleBooksResponse.self, from: data)
                return response.items.map { item in
                    let volumeInfo = item.volumeInfo
                    return Book(title: volumeInfo.title, author: volumeInfo.authors.joined(separator: ", "), thumbnailURL: URL(string: volumeInfo.imageLinks.thumbnail)!)
                }
            } catch {
                throw error
            }
        }
        .asObservable()
}

struct GoogleBooksResponse: Decodable {
    let items: [GoogleBookItem]
}

struct GoogleBookItem: Decodable {
    let volumeInfo: VolumeInfo
}

struct VolumeInfo: Decodable {
    let title: String
    let authors: [String]
    let imageLinks: ImageLinks
}

struct ImageLinks: Decodable {
    let thumbnail: String
}
```

