void printadj(const std::vector<std::string>& table, const std::map<std::string, std::string>& g) {
    for (const auto& key : table) {
        std::cout << key << " " << g.at(key) << std::endl;
    }
}

void processInput(const std::vector<std::string>& input) {
    std::map<std::string, std::string> g;
    std::vector<std::string> table;

    for (const auto& i : input) {
        if (i.find(' ') != std::string::npos) {
            std::string first = i.substr(0, i.find(' '));
            std::string second = i.substr(i.find(' ') + 1);
            if (g.find(first) != g.end()) {
                g[first] += second;
            } else {
                g[first] = second;
            }
            if (std::find(table.begin(), table.end(), first) == table.end()) {
                table.push_back(first);
            }
            if (std::find(table.begin(), table.end(), second) == table.end()) {
                table.push_back(second);
            }
        }
    }

    std::sort(table.begin(), table.end());
    printadj(table, g);
}

