use std::collections::HashMap;

struct Bank {
    name: String,
    accounts: HashMap<u32, f64>,
}

impl Bank {
    fn new(name: &str) -> Bank {
        Bank {
            name: name.to_string(),
            accounts: HashMap::new(),
        }
    }

    fn create_account(&mut self, account_number: u32) {
        self.accounts.entry(account_number).or_insert(0.0);
    }

    fn deposit(&mut self, account_number: u32, amount: f64) {
        if let Some(balance) = self.accounts.get_mut(&account_number) {
            *balance += amount;
        }
    }

    fn withdraw(&mut self, account_number: u32, amount: f64) {
        if let Some(balance) = self.accounts.get_mut(&account_number) {
            if *balance >= amount {
                *balance -= amount;
            }
        }
    }

    fn balance(&self, account_number: u32) -> Option<f64> {
        self.accounts.get(&account_number).cloned()
    }

    fn total_deposits(bank: &Bank) -> f64 {
        bank.accounts.values().sum()
    }
}

fn main() {
    let mut bank = Bank::new("MyBank");
    bank.create_account(1001);
    bank.deposit(1001, 500.0);
    bank.withdraw(1001, 200.0);
    println!("Account balance: {:?}", bank.balance(1001)); // Output: Some(300.0)
    println!("Total deposits: {}", Bank::total_deposits(&bank)); // Output: 300.0
}
```

