use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Debug)]
enum Message {
    ACK(u128),
    Payload(PayloadMsg),
}

#[derive(Debug)]
struct PayloadMsg {
    id: u128,
    data: Vec<u8>,
}

fn get_unix_ts() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("Time went backwards")
        .as_millis() as u128
}

