import requests

class ImageProcessor:
    def __init__(self, api_key: str, base_url: str):
        self.api_key = api_key
        self.base_url = base_url

    def upload_image(self, image_path: str) -> str:
        upload_url = f"{self.base_url}/upload"
        files = {'file': open(image_path, 'rb')}
        headers = {'Authorization': f"Bearer {self.api_key}"}
        response = requests.post(upload_url, files=files, headers=headers)
        if response.status_code == 200:
            return response.json()['image_id']
        else:
            raise Exception(f"Failed to upload image: {response.text}")

    def process_image(self, image_id: str, operation: str) -> str:
        process_url = f"{self.base_url}/process"
        payload = {'image_id': image_id, 'operation': operation}
        headers = {'Authorization': f"Bearer {self.api_key}"}
        response = requests.post(process_url, json=payload, headers=headers)
        if response.status_code == 200:
            return response.json()['processed_image_id']
        else:
            raise Exception(f"Failed to process image: {response.text}")

    def download_image(self, image_id: str, destination_path: str) -> None:
        download_url = f"{self.base_url}/download/{image_id}"
        headers = {'Authorization': f"Bearer {self.api_key}"}
        response = requests.get(download_url, headers=headers)
        if response.status_code == 200:
            with open(destination_path, 'wb') as file:
                file.write(response.content)
        else:
            raise Exception(f"Failed to download image: {response.text}")

# Example usage
api_key = "fpfGmGL99O+3bM1BpV8vSQLeHxxocf+IeLMcKHFwfXU="
base_url = "http://localhost:5000"
processor = ImageProcessor(api_key, base_url)
image_id = processor.upload_image("grayscale.jpg")
processed_image_id = processor.process_image(image_id, "grayscale")
processor.download_image(processed_image_id, "processed_grayscale.jpg")
```

