```csharp
public class MapGenerator
{
    private int _mapWidth;
    private int _mapHeight;
    private float _obstaclePercentage;
    private bool[,] _map;

    public void GenerateMap()
    {
        _map = new bool[_mapWidth, _mapHeight];
        int totalCells = _mapWidth * _mapHeight;
        int obstacleCells = Mathf.RoundToInt(_obstaclePercentage * totalCells);

        // Randomly place obstacles
        for (int i = 0; i < obstacleCells; i++)
        {
            int x = Random.Range(0, _mapWidth);
            int y = Random.Range(0, _mapHeight);
            _map[x, y] = true;
        }

        // Ensure connected obstacles
        for (int x = 0; x < _mapWidth; x++)
        {
            for (int y = 0; y < _mapHeight; y++)
            {
                if (_map[x, y])
                {
                    List<(int, int)> connectedCells = new List<(int, int)>();
                    FindConnectedCells(x, y, connectedCells);
                    foreach (var (cx, cy) in connectedCells)
                    {
                        _map[cx, cy] = true;
                    }
                }
            }
        }
    }

    private void FindConnectedCells(int x, int y, List<(int, int)> connectedCells)
    {
        if (x < 0 || x >= _mapWidth || y < 0 || y >= _mapHeight || !_map[x, y] || connectedCells.Contains((x, y)))
        {
            return;
        }
        connectedCells.Add((x, y));
        FindConnectedCells(x - 1, y, connectedCells);
        FindConnectedCells(x + 1, y, connectedCells);
        FindConnectedCells(x, y - 1, connectedCells);
        FindConnectedCells(x, y + 1, connectedCells);
    }
}
```

In the solution, the `GenerateMap()` method initializes the map and randomly places obstacles based on the specified percentage. Then, it ensures that all obstacle cells are connected by finding connected cells using a recursive depth-first search algorithm. This guarantees that there are no isolated groups of obstacles in the generated map, satisfying the map generation rules.

