use std::time::{SystemTime, UNIX_EPOCH};

struct Naday {
    include_module_path: bool,
}

impl Naday {
    fn format_timestamp(&self, timestamp: Option<SystemTime>) -> String {
        match timestamp {
            Some(ts) => {
                let formatted_time = ts.duration_since(UNIX_EPOCH)
                    .map(|dur| dur.as_secs())
                    .map(|secs| format!("Timestamp: {}", secs))
                    .unwrap_or_else(|_| "Invalid timestamp".to_string());
                formatted_time
            }
            None => {
                let current_time = SystemTime::now().duration_since(UNIX_EPOCH)
                    .map(|dur| dur.as_secs())
                    .map(|secs| format!("Current time: {}", secs))
                    .unwrap_or_else(|_| "Invalid timestamp".to_string());
                current_time
            }
        }
    }

    fn format_module_path(&mut self, include: bool) {
        self.include_module_path = include;
    }

