def csd_to_decimal(csd: str) -> int:
    decimal_value = 0
    power = 0
    for digit in reversed(csd):
        if digit == '1':
            decimal_value += 2 ** power
        elif digit == '0':
            pass
        elif digit == '-':
            decimal_value -= 2 ** power
        power += 1
    return decimal_value
