class Library:
    def __init__(self):
        self.books = []

    def add_book(self, title, author):
        self.books.append({"title": title, "author": author, "available": True})

    def remove_book(self, title):
        for book in self.books:
            if book["title"] == title:
                self.books.remove(book)
                return

    def display_books(self):
        if not self.books:
            print("The library is empty.")
        else:
            print("Books in the library:")
            for book in self.books:
                status = "Available" if book["available"] else "Unavailable"
                print(f"{book['title']} by {book['author']} - {status}")

    def borrow_book(self, title):
        for book in self.books:
            if book["title"] == title and book["available"]:
                book["available"] = False
                print(f"{title} has been borrowed.")
                return
        print(f"{title} is not available for borrowing.")

    def return_book(self, title):
        for book in self.books:
            if book["title"] == title and not book["available"]:
                book["available"] = True
                print(f"{title} has been returned.")
                return
        print(f"{title} is not a valid book to return.")

# Command-line interface
library = Library()
while True:
    print("\nLibrary Management System")
    print("1. Add a book")
    print("2. Remove a book")
    print("3. Display all books")
    print("4. Borrow a book")
    print("5. Return a book")
    print("6. Exit")
    choice = input("Enter your choice: ")

    if choice == "1":
        title = input("Enter the title of the book: ")
        author = input("Enter the author of the book: ")
        library.add_book(title, author)
        print(f"{title} by {author} has been added to the library.")
    elif choice == "2":
        title = input("Enter the title of the book to remove: ")
        library.remove_book(title)
        print(f"{title} has been removed from the library.")
    elif choice == "3":
        library.display_books()
    elif choice == "4":
        title = input("Enter the title of the book to borrow: ")
        library.borrow_book(title)
    elif choice == "5":
        title = input("Enter the title of the book to return: ")
        library.return_book(title)
    elif choice == "6":
        print("Exiting the library management system. Goodbye!")
        break
    else:
        print("Invalid choice. Please try again.")
