```csharp
using System;

public class Queue
{
    private class Node
    {
        public int Value;
        public Node Next;
    }

    private Node head;
    private Node tail;

    public void Enqueue(int value)
    {
        Node newNode = new Node { Value = value, Next = null };
        if (tail == null)
        {
            head = newNode;
            tail = newNode;
        }
        else
        {
            tail.Next = newNode;
            tail = newNode;
        }
    }

    public int Dequeue()
    {
        if (head == null)
        {
            throw new InvalidOperationException("Queue is empty");
        }
        int dequeuedValue = head.Value;
        head = head.Next;
        if (head == null)
        {
            tail = null;
        }
        return dequeuedValue;
    }

    public void Dispose()
    {
        // Your implementation here
    }
}

public class Program
{
    public static void Main()
    {
        Queue Q = new Queue();
        Q.Enqueue(10);
        Q.Enqueue(20);
        Q.Enqueue(30);
        Console.WriteLine(Q.Dequeue()); // Output: 10
        Q.Dispose();
    }
}
