func parseConfigurationFile(configuration: String) -> (products: [String: (type: String, targets: [String])], dependencies: [String: String]) {
    var products: [String: (type: String, targets: [String])] = [:]
    var dependencies: [String: String] = [:]

    // Extract products
    if let productsRange = configuration.range(of: ".products([") {
        let productsSubstring = configuration[productsRange.upperBound...]
        if let productsEndIndex = productsSubstring.firstIndex(of: "]") {
            let productsContent = productsSubstring[..<productsEndIndex]
            let productMatches = productsContent.matches(for: #"\.(library|executable)\(name: "(.*?)", targets: \[(.*?)\]\)"#)
            for match in productMatches {
                let type = match[1]
                let name = match[2]
                let targets = match[3].components(separatedBy: ", ")
                products[name] = (type: type, targets: targets)
            }
        }
    }

    // Extract dependencies
    if let dependenciesRange = configuration.range(of: ".dependencies([") {
        let dependenciesSubstring = configuration[dependenciesRange.upperBound...]
        if let dependenciesEndIndex = dependenciesSubstring.firstIndex(of: "]") {
            let dependenciesContent = dependenciesSubstring[..<dependenciesEndIndex]
            let dependencyMatches = dependenciesContent.matches(for: #"\.package\(url: "(.*?)", from: "(.*?)"\)"#)
            for match in dependencyMatches {
                let url = match[1]
                let version = match[2]
                if let productName = url.components(separatedBy: "/").last {
                    dependencies[productName] = "\(url) \(version)"
                }
            }
        }
    }

    return (products: products, dependencies: dependencies)
}

// Helper extension to extract regex matches
extension String {
    func matches(for regex: String) -> [[String]] {
        do {
            let regex = try NSRegularExpression(pattern: regex)
            let results = regex.matches(in: self, range: NSRange(self.startIndex..., in: self))
            return results.map { result in
                (0..<result.numberOfRanges).map {
                    result.range(at: $0).location != NSNotFound ? String(self[Range(result.range(at: $0), in: self)!]) : ""
                }
            }
        } catch let error {
            print("Invalid regex: \(error.localizedDescription)")
            return []
        }
    }
}
```

This solution defines a function `parseConfigurationFile` that takes the configuration file as input and uses regular expressions to extract the products and their dependencies. It then constructs and returns a tuple containing the products and their dependencies as dictionaries. The function also includes a helper extension to extract regex matches from a string.

