        "license_type": "",
        "version": "",
        "permissions": [],
        "restrictions": []
    }

    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            for line in lines:
                if "Licensed under the" in line:
                    license_details = line.split("Licensed under the ")[1].split(" (the")[0]
                    license_info["license_type"] = license_details.split(", Version")[0].strip()
                    license_info["version"] = license_details.split(", Version ")[1].split(" ")[0].strip()
                elif "you may " in line:
                    permission = line.split(" * ")[1].strip()
                    license_info["permissions"].append(permission)
                elif "you may not " in line:
                    restriction = line.split(" * ")[1].strip()
                    license_info["restrictions"].append(restriction)
    except FileNotFoundError:
        return license_info

    return license_info
