```rust
use std::collections::HashMap;

struct DDependencyDef {
    // Details of a dependency
}

struct DToolchainDef {
    // Details of a toolchain
}

struct DependencyManager {
    projects: HashMap<String, Vec<DDependencyDef>>,
}

impl DependencyManager {
    fn new() -> Self {
        DependencyManager {
            projects: HashMap::new(),
        }
    }

    fn add_dependency(&mut self, project: String, dependency: DDependencyDef) {
        self.projects
            .entry(project)
            .or_insert(Vec::new())
            .push(dependency);
    }

    fn remove_dependency(&mut self, project: &str, dependency: &DDependencyDef) {
        if let Some(dependencies) = self.projects.get_mut(project) {
            dependencies.retain(|d| d != dependency);
        }
    }

    fn alter_dependency(&mut self, project: &str, old_dependency: &DDependencyDef, new_dependency: DDependencyDef) {
        if let Some(dependencies) = self.projects.get_mut(project) {
            if let Some(index) = dependencies.iter().position(|d| d == old_dependency) {
                dependencies[index] = new_dependency;
            }
        }
    }
}

fn main() {
    let mut manager = DependencyManager::new();

    // Add a new dependency
    manager.add_dependency("project1".to_string(), DDependencyDef { /* details */ });

    // Remove an existing dependency
    manager.remove_dependency("project1", &DDependencyDef { /* details */ });

    // Alter an existing dependency
    manager.alter_dependency("project1", &DDependencyDef { /* old details */ }, DDependencyDef { /* new details */ });
}
```

