import Foundation

func ticketingSystem(totalTickets: Int) -> (() -> Int, (Int) -> Void) {
    let semaphore = DispatchSemaphore(value: totalTickets)
    var availableTickets = totalTickets
    var nextTicketNumber = 1
    var ticketLock = NSLock()

    let reserveTicket: () -> Int = {
        let waitTime = DispatchTime.now() + 1 // Timeout for waiting to acquire a ticket
        if semaphore.wait(timeout: waitTime) == .success {
            ticketLock.lock()
            defer {
                ticketLock.unlock()
            }
            if availableTickets > 0 {
                let ticketNumber = nextTicketNumber
                nextTicketNumber += 1
                availableTickets -= 1
                return ticketNumber
            } else {
                semaphore.signal() // Release the semaphore if no tickets are available
                return -1
            }
        } else {
            return -1 // Timeout reached, no tickets available
        }
    }

    let releaseTicket: (Int) -> Void = { ticketNumber in
        ticketLock.lock()
        defer {
            ticketLock.unlock()
        }
        if ticketNumber > 0 && ticketNumber < nextTicketNumber {
            availableTickets += 1
            semaphore.signal() // Signal the semaphore to release the reserved ticket
        }
    }

    return (reserveTicket, releaseTicket)
}
```

