struct ArgumentType {
    let label: String?
    let name: String
    let type: String
}

func generateStubCode(protocolName: String, functionDeclarations: [FunctionDeclarationType]) -> String {
    var stubCode = "protocol \(protocolName) {\n"

    for functionDeclaration in functionDeclarations {
        var argumentString = ""
        for argument in functionDeclaration.arguments {
            if let label = argument.label {
                argumentString += "\(label) \(argument.name): \(argument.type), "
            } else {
                argumentString += "\(argument.name): \(argument.type), "
            }
        }
        argumentString = String(argumentString.dropLast(2)) // Remove the trailing comma and space

        stubCode += "\tfunc \(functionDeclaration.name)(\(argumentString))\n"
    }

    stubCode += "}"

    return stubCode
}

struct FunctionDeclarationType {
    let name: String
    let arguments: [ArgumentType]
