class TaskManager {
  constructor() {
    this.tasks = [];
  }

  addTask(task) {
    this.tasks.push({ task, completed: false });
  }

  completeTask(index) {
    if (index >= 0 && index < this.tasks.length) {
      this.tasks[index].completed = true;
    } else {
      console.log("Invalid task index");
    }
  }

  viewTasks() {
    return this.tasks.map((task, index) => `${index + 1}. [${task.completed ? 'x' : ' '}] ${task.task}`).join('\n');
  }

  deleteTask(index) {
    if (index >= 0 && index < this.tasks.length) {
      this.tasks.splice(index, 1);
    } else {
      console.log("Invalid task index");
    }
  }
}

