def read_c_string_from_memory(memory: bytes, address: int) -> str:
    c_string = b""
    index = address
    while index < len(memory) and memory[index] != 0:
        c_string += bytes([memory[index]])
        index += 1
    return c_string.decode("utf-8")
```

