class Inventory:
    def __init__(self):
        self.items = {}

    def add_item(self, item_id, name, quantity, price):
        if item_id in self.items:
            self.items[item_id]['quantity'] += quantity
            self.items[item_id]['price'] = price
        else:
            self.items[item_id] = {'name': name, 'quantity': quantity, 'price': price}

    def remove_item(self, item_id):
        if item_id in self.items:
            del self.items[item_id]

    def display_inventory(self):
        for item_id, details in self.items.items():
            total_value = details['quantity'] * details['price']
            print(f"ID: {item_id}, Name: {details['name']}, Quantity: {details['quantity']}, Total Value: {total_value}")

    def calculate_inventory_value(self):
        total_value = sum(details['quantity'] * details['price'] for details in self.items.values())
        return total_value

# Command-line interface
