        $this->translations = [];
        foreach ($translatable as $property) {
            $this->translations[$property] = [];
        }
    }

    public function setTranslation($property, $language, $translation) {
        if (in_array($property, $this->translatable)) {
            $this->translations[$property][$language] = $translation;
        } else {
            throw new Exception("Property '$property' is not translatable.");
        }
    }

    public function getTranslation($property, $language) {
        if (array_key_exists($property, $this->translations) && array_key_exists($language, $this->translations[$property])) {
            return $this->translations[$property][$language];
        }
        return null;
    }
}

// Example usage
$translatable = ['icon_title1', 'icon_decs1', 'icon_title2', 'icon_decs2', 'icon_title3', 'icon_decs3',
    'icon_title4', 'icon_decs4', 'icon_title5', 'icon_decs5', 'icon_title6', 'icon_decs6'];

$manager = new TranslationManager($translatable);
$manager->setTranslation('icon_title1', 'en', 'Home');
$manager->setTranslation('icon_title1', 'fr', 'Accueil');
echo $manager->getTranslation('icon_title1', 'en'); // Output: Home
echo $manager->getTranslation('icon_title1', 'fr'); // Output: Accueil
echo $manager->getTranslation('icon_title2', 'en'); // Output: null
