import math

class Vector:
    """
    2D Vector class for position, velocity, and acceleration
    """
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __mul__(self, scalar):
        return Vector(self.x * scalar, self.y * scalar)

class Rock:
    """
    Rock class for the asteroids
    """
    def __init__(self, p=(0, 0), v=(0, 0), a=(0, 0), rad=45):
        self.pos = Vector(p[0], p[1])
        self.vel = Vector(v[0], v[1])
        self.radius = rad
        self.exploded = False

    def update_position(self, dt):
        """
        Update the position of the asteroid based on its current velocity and the time increment dt
        """
        self.pos = self.pos + (self.vel * dt)

    def check_collision(self, other_rock):
        """
        Check if the current asteroid collides with the other asteroid
        """
        distance = math.sqrt((self.pos.x - other_rock.pos.x) ** 2 + (self.pos.y - other_rock.pos.y) ** 2)
        return distance <= (self.radius + other_rock.radius)
```
