import random

def simulate_fishing(species, probabilities, num_simulations):
    catches = {s: 0 for s in species}
    for _ in range(num_simulations):
        rand_num = random.random()
        cumulative_prob = 0
        for i, prob in enumerate(probabilities):
            cumulative_prob += prob
            if rand_num < cumulative_prob:
                catches[species[i]] += 1
                break
    return catches

def main():
    N = int(input())
    species = []
    probabilities = []
    for _ in range(N):
        s, p = input().split()
        species.append(s)
        probabilities.append(float(p))

    num_simulations = 100
    catches = simulate_fishing(species, probabilities, num_simulations)
    for s, count in catches.items():
        print(f"{s}: {count}")

if __name__ == "__main__":
    main()
```

