import os

def compile_templates(template_directory: str, placeholder_values: dict, compiled_directory: str) -> None:
    if not os.path.exists(compiled_directory):
        os.makedirs(compiled_directory)

    for filename in os.listdir(template_directory):
        if filename.endswith(".txt"):
            with open(os.path.join(template_directory, filename), 'r') as file:
                template_content = file.read()
                compiled_content = template_content
                for placeholder, value in placeholder_values.items():
                    compiled_content = compiled_content.replace("{{" + placeholder + "}}", value)

                with open(os.path.join(compiled_directory, filename), 'w') as compiled_file:
                    compiled_file.write(compiled_content)
```

