        Comparator<Player> comparator;
        if (sortBy.equals("level")) {
            comparator = Comparator.comparingInt(Player::getLevel);
        } else if (sortBy.equals("score")) {
            comparator = Comparator.comparingInt(Player::getScore);
        } else {
            throw new IllegalArgumentException("Invalid sort attribute");
        }

        if (order.equals("asc")) {
            Collections.sort(players, comparator);
        } else if (order.equals("desc")) {
            Collections.sort(players, comparator.reversed());
        } else {
            throw new IllegalArgumentException("Invalid sort order");
        }
    }
}
