function calculateAverageSalary(employees) {
    let totalSalary = 0;
    let count = 0;

    for (let employee of employees) {
        if (employee.name !== null) {
            totalSalary += employee.salary;
            count++;
        }
    }

    if (count === 0) {
        return 0;
    }

