class FactorialCalculator {
    @FactorialMethod
    public int calculateFactorial(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("Factorial is defined only for non-negative integers.");
        }
        int factorial = 1;
        for (int i = 1; i <= number; i++) {
            factorial *= i;
        }
        return factorial;
    }
}

