struct YPAlbum {
    var thumbnail: UIImage?
    var title: String = ""
    var numberOfItems: Int = 0
}

func fetchPhotoAlbums() -> [YPAlbum] {
    var albums: [YPAlbum] = []

    let fetchOptions = PHFetchOptions()
    let userAlbums = PHAssetCollection.fetchAssetCollections(with: .album, subtype: .any, options: fetchOptions)

    userAlbums.enumerateObjects { collection, _, _ in
        let albumTitle = collection.localizedTitle ?? ""

        let fetchResult = PHAsset.fetchAssets(in: collection, options: nil)
        let albumThumbnail = fetchResult.firstObject.map { asset in
            let manager = PHImageManager.default()
            let targetSize = CGSize(width: 100, height: 100)
            let options = PHImageRequestOptions()
            options.isSynchronous = true
            var thumbnail: UIImage?
            manager.requestImage(for: asset, targetSize: targetSize, contentMode: .aspectFill, options: options) { result, _ in
                thumbnail = result
            }
            return thumbnail
        }

        let album = YPAlbum(thumbnail: albumThumbnail, title: albumTitle, numberOfItems: fetchResult.count)
        albums.append(album)
    }

    return albums
}
```

