import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.TypeAdapter;
import java.lang.reflect.Type;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class GsonUtility {
    private static final GsonBuilder GSON_BUILDER = new GsonBuilder();
    private static final Map<Type, TypeAdapter> typeAdapters = new ConcurrentHashMap<>();
    private static Gson gson;

    public static synchronized void registerTypeAdapter(final Type type, final TypeAdapter typeAdapter) {
        GSON_BUILDER.registerTypeAdapter(type, typeAdapter);
        gson = GSON_BUILDER.create();
        typeAdapters.put(type, typeAdapter);
    }

    public static synchronized void unregisterTypeAdapter(final Type type) {
        typeAdapters.remove(type);
        GSON_BUILDER.registerTypeAdapter(type, null);
        gson = GSON_BUILDER.create();
    }

    public static Gson getGson() {
        if (gson == null) {
            synchronized (GsonUtility.class) {
                if (gson == null) {
                    gson = GSON_BUILDER.create();
                }
            }
        }
        return gson;
    }
}
```

In the solution, the `unregisterTypeAdapter` method removes the type adapter from the Gson builder and updates the Gson instance. The `getGson` method ensures that the Gson instance is created only once and returned for subsequent calls. The use of `synchronized` ensures thread safety when registering or unregistering type adapters and accessing the Gson instance. The `ConcurrentHashMap` is used to store registered type adapters for efficient management.

