from typing import List

def performOperations(operations: List[str]) -> List[int]:
    stack = []
    for op in operations:
        if op.startswith("push"):
            _, num = op.split()
            stack.append(int(num))
        elif op == "pop":
            stack.pop()
        elif op.startswith("inc"):
            _, i, v = op.split()
            i, v = int(i), int(v)
            for j in range(min(i, len(stack))):
                stack[j] += v
    return stack
```

