class PythonCodeManipulator:
    @staticmethod
    def extract_default_value(func_def, keyword):
        start_index = func_def.find(keyword + "=")
        if start_index != -1:
            start_index += len(keyword) + 1
            end_index = func_def.find(",", start_index)
            if end_index == -1:
                end_index = func_def.find(")", start_index)
            return func_def[start_index:end_index].strip()
        return None

    @staticmethod
    def add_default_value(func_def, keyword, default_value):
        start_index = func_def.find(keyword + "=")
        if start_index != -1:
            end_index = func_def.find(",", start_index)
            if end_index == -1:
                end_index = func_def.find(")", start_index)
            return func_def[:start_index + len(keyword) + 1] + default_value + func_def[end_index:]
        return func_def

    @staticmethod
    def generate_modified_function(func_def, keyword, default_value):
        modified_function = PythonCodeManipulator.add_default_value(func_def, keyword, default_value)
        return modified_function
```

