#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <stdbool.h>

double my_strtod(const char* str, char** endptr) {
    const char* p = str;
    char* end = NULL;
    double result = 0.0;
    bool negative = false;
    bool hasDigits = false;

    // Skip leading whitespace
    while (isspace(*p)) {
        p++;
    }

    // Check for optional sign
    if (*p == '-') {
        negative = true;
        p++;
    } else if (*p == '+') {
        p++;
    }

    // Parse digits before decimal point
    while (isdigit(*p)) {
        hasDigits = true;
        result = result * 10 + (*p - '0');
        p++;
    }

    // Parse decimal point and digits after it
    if (*p == '.') {
        double fraction = 0.1;
        p++;
        while (isdigit(*p)) {
            hasDigits = true;
            result += fraction * (*p - '0');
            fraction *= 0.1;
            p++;
        }
    }

    // Parse exponent part
    if (tolower(*p) == 'e') {
        int exp = 0;
        bool expNegative = false;
        p++;
        if (*p == '-') {
            expNegative = true;
            p++;
        } else if (*p == '+') {
            p++;
        }
        while (isdigit(*p)) {
            exp = exp * 10 + (*p - '0');
            p++;
        }
        if (expNegative) {
            result /= pow(10, exp);
        } else {
            result *= pow(10, exp);
        }
    }

    // Set endptr and return the result
    if (hasDigits) {
        end = (char*)p;
        if (endptr != NULL) {
            *endptr = end;
        }
        return negative ? -result : result;
    } else {
        if (endptr != NULL) {
            *endptr = (char*)str;
        }
        return 0.0;
    }
}
```

