from functools import wraps
from framework import UseInterceptors, UsePipes, ValidationPipe

def validate_input(validation_schema):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Apply UseInterceptors and UsePipes to utilize ValidationPipe for input validation
            @UseInterceptors(ValidationPipe)
            @UsePipes(ValidationPipe)
            def validate_input_data(data):
                return data

            # Validate the input data using the provided validation_schema
            validated_data = validate_input_data(validation_schema)

            # Call the original API endpoint handler function with the validated input data
            return func(validated_data, *args, **kwargs)

        return wrapper
    return decorator
```

