import os

def read_temperature_files(directory):
    temperatures = []
    try:
        for file in os.listdir(directory):
            if file.startswith('hwmon') or file.startswith('nvme') or file.startswith('thermal_zone'):
                with open(os.path.join(directory, file, 'temp1_input'), 'r') as temp_file:
                    temperature = int(temp_file.read().strip()) / 1000  # Convert millidegrees to degrees
                    temperatures.append((file, temperature))
    except FileNotFoundError as e:
        print(f"Error reading temperature files: {e}")
    return temperatures

def format_and_display_temperatures(temperatures):
    for component, temp in temperatures:
        if component.startswith('hwmon'):
            component_name = open(os.path.join('/sys/class/hwmon', component, 'name'), 'r').read().strip()
        elif component.startswith('nvme'):
            component_name = open(os.path.join('/sys/class/nvme', component, 'model'), 'r').read().strip()
        elif component.startswith('thermal_zone'):
            component_name = open(os.path.join('/sys/class/thermal', component, 'type'), 'r').read().strip()
        else:
            component_name = "Unknown Component"
        print(f"{component_name}: {temp}°C")

def main():
