extension TableDirector {
    func scrollToThreshold(direction: PaginationController.Direction, offset: CGFloat) {
        guard let tableView = _tableView else { return }
        let tableHeight = tableView.bounds.height
        let rectSize = CGSize(width: 1, height: tableHeight)
        switch direction {
        case .up:
            let topPoint = CGPoint(x: 0, y: tableView.contentInset.top + offset)
            tableView.scrollRectToVisible(CGRect(origin: topPoint, size: rectSize), animated: true)
        case .down:
            let bottomPoint = CGPoint(x: 0, y: tableView.contentSize.height - tableHeight + offset)
            tableView.scrollRectToVisible(CGRect(origin: bottomPoint, size: rectSize), animated: true)
        }
    }
}
