            print(f"Book with ISBN {isbn} already exists in the library.")
        else:
            self.books[isbn] = Book(isbn, title, author, quantity)

    def borrow_book(self, isbn: str) -> bool:
        if isbn in self.books and self.books[isbn].quantity > 0:
            self.books[isbn].quantity -= 1
            return True
        else:
            return False

    def return_book(self, isbn: str) -> bool:
        if isbn in self.books and self.books[isbn].quantity >= 0:
            self.books[isbn].quantity += 1
            return True
        else:
            return False

    def is_book_available(self, isbn: str) -> bool:
        return isbn in self.books and self.books[isbn].quantity > 0

