use bigint::{Address, H256, U256};
use rlp::{Encodable, RlpStream};

#[derive(Debug)]
pub struct Log {
    pub address: Address,
    pub data: U256,
    pub topics: Vec<H256>,
}

impl Encodable for Log {
    fn rlp_append(&self, s: &mut RlpStream) {
        s.begin_list(3); // Begin RLP list with 3 items
        s.append(&self.address.0); // Serialize address as a byte array
        s.append(&self.data); // Serialize data as a U256
        s.begin_list(self.topics.len()); // Begin RLP list for topics
