You are tasked with implementing a multi-threaded program that simulates a simple ticketing system using semaphores. The program should consist of two types of threads: ticket sellers and ticket buyers. The ticket sellers will be responsible for adding tickets to the system, while the ticket buyers will attempt to purchase tickets. To ensure thread safety and prevent race conditions, you need to utilize semaphores for synchronization.

Your task is to complete the implementation of the `TicketSystem` class, which includes the following methods:
1. `AddTickets(int numTickets)`: This method should add the specified number of tickets to the system.
2. `BuyTickets(int numTickets)`: This method should attempt to buy the specified number of tickets from the system. If the requested number of tickets is available, they should be sold, and the method should return true. If the requested number of tickets is not available, the method should return false.

You should use the provided code snippet as a starting point and implement the necessary synchronization using semaphores to ensure that the ticketing system operates correctly in a multi-threaded environment.

```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <Windows.h>

class TicketSystem {
private:
    int totalTickets;
    HANDLE semaphore;

public:
    TicketSystem(int initialTickets) : totalTickets(initialTickets) {
        semaphore = CreateSemaphore(NULL, 0, 0x7FFFFFFF, NULL);
    }

    void AddTickets(int numTickets) {
        totalTickets += numTickets;
        ReleaseSemaphore(semaphore, numTickets, NULL);
    }

    bool BuyTickets(int numTickets) {
        if (WaitForSingleObject(semaphore, 0) == WAIT_OBJECT_0) {
            if (totalTickets >= numTickets) {
                totalTickets -= numTickets;
                return true;
            }
            ReleaseSemaphore(semaphore, 1, NULL);
        }
        return false;
    }
};

void SellerThread(TicketSystem& system, int numTickets) {
    system.AddTickets(numTickets);
}

void BuyerThread(TicketSystem& system, int numTickets) {
    if (system.BuyTickets(numTickets)) {
        std::cout << "Tickets purchased: " << numTickets << std::endl;
    } else {
        std::cout << "Tickets not available" << std::endl;
    }
}

int main() {
    TicketSystem ticketSystem(10);

    std::vector<std::thread> threads;
    for (int i = 0; i < 5; ++i) {
        threads.emplace_back(SellerThread, std::ref(ticketSystem), 3);
        threads.emplace_back(BuyerThread, std::ref(ticketSystem), 2);
    }

    for (auto& t : threads) {
        t.join();
    }

    std::cout << "Remaining tickets: " << ticketSystem.BuyTickets(0) << std::endl;

    return 0;
}
```

