```c
// parallel_sum.c
#include <stdio.h>
#include <stdlib.h>
#include <mpi.h>

#define ARRAY_SIZE 1000000000

int main(int argc, char *argv[]) {
    int rank, size;
    int *array;
    long long local_sum = 0, global_sum = 0;
    double start_time, end_time, total_time;

    MPI_Init(&argc, &argv);
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);

    if (rank == 0) {
        array = (int *)malloc(ARRAY_SIZE * sizeof(int));
        for (int i = 0; i < ARRAY_SIZE; i++) {
            array[i] = i + 1;  // Initialize array with values 1 to ARRAY_SIZE
        }
    }

    start_time = MPI_Wtime();

    MPI_Bcast(array, ARRAY_SIZE, MPI_INT, 0, MPI_COMM_WORLD);

    int chunk_size = ARRAY_SIZE / size;
    int start = rank * chunk_size;
    int end = (rank == size - 1) ? ARRAY_SIZE : start + chunk_size;

    for (int i = start; i < end; i++) {
        local_sum += array[i];
    }

    MPI_Reduce(&local_sum, &global_sum, 1, MPI_LONG_LONG, MPI_SUM, 0, MPI_COMM_WORLD);

    end_time = MPI_Wtime();
    total_time = end_time - start_time;

    if (rank == 0) {
        printf("Sum: %lld\n", global_sum);
        printf("Time taken: %f seconds\n", total_time);
    }

    MPI_Finalize();
    if (rank == 0) {
        free(array);
    }

    return 0;
}
```

The provided C program `parallel_sum.c` uses MPI to calculate the sum of an array of integers in parallel. The program initializes an array of integers with values from 1 to `ARRAY_SIZE` and distributes the workload across multiple processes to compute the sum in parallel. The program measures the time taken for the computation and outputs the sum and time for each number of processes used.

