import numpy as np

class GlowwormSwarmOptimizationV1:
    def __init__(self, D, nFES, NP, a, Rmin, Rmax, benchmark):
        self.D = D
        self.nFES = nFES
        self.NP = NP
        self.a = a
        self.Rmin = Rmin
        self.Rmax = Rmax
        self.benchmark = benchmark

    def initialize_positions(self):
        return np.random.uniform(self.Rmin, self.Rmax, (self.NP, self.D))

    def update_positions(self, positions, brightness):
        for i in range(self.NP):
            for j in range(self.NP):
                if brightness[j] > brightness[i]:
                    distance = np.linalg.norm(positions[j] - positions[i])
                    if distance < self.a:
                        positions[i] += (positions[j] - positions[i]) * (1 - np.exp(-distance**2 / self.a**2))

        return positions

    def run(self):
        positions = self.initialize_positions()
        best_position = positions[0]
        best_brightness = self.benchmark.function(best_position)

        for _ in range(self.nFES):
            brightness = np.array([self.benchmark.function(pos) for pos in positions])
            positions = self.update_positions(positions, brightness)

            max_brightness_index = np.argmax(brightness)
            if brightness[max_brightness_index] > best_brightness:
                best_position = positions[max_brightness_index]
                best_brightness = brightness[max_brightness_index]

        return best_position
```

