            return int(self.value)
        else:
            left_val = self.left.evaluate()
            right_val = self.right.evaluate()
            if self.value == '+':
                return left_val + right_val
            elif self.value == '-':
                return left_val - right_val
            elif self.value == '*':
                return left_val * right_val
            elif self.value == '/':
                return left_val / right_val
