import importlib

def import_module(module_name, imported=None):
    if imported is None:
        imported = {}

    if module_name in imported:
        return imported

    module = importlib.import_module(module_name)

    for name in dir(module):
        if not name.startswith('__'):
            imported[name] = getattr(module, name)

