#include "DataFormats/TrackReco/interface/Track.h"
#include "DataFormats/TrackReco/interface/TrackFwd.h"

class TrackAnalyzer : public edm::EDAnalyzer {
public:
  explicit TrackAnalyzer(const edm::ParameterSet&);
  ~TrackAnalyzer() override {}

  void analyze(const edm::Event& event, const edm::EventSetup&) override {
    edm::Handle<reco::TrackCollection> tracks;
    event.getByLabel(tracks_, tracks);

    if (!tracks.isValid()) {
      std::cerr << "Error: Track collection not found!" << std::endl;
      return;
    }

    int totalTracks = 0;
    double maxPt = 0.0;
    reco::Track maxPtTrack;
    double sumPt = 0.0;

    for (const auto& track : *tracks) {
      totalTracks++;
      double pt = track.pt();
      sumPt += pt;
      if (pt > maxPt) {
        maxPt = pt;
        maxPtTrack = track;
      }
    }

    double avgPt = totalTracks > 0 ? sumPt / totalTracks : 0.0;

    std::cout << "Total tracks: " << totalTracks << std::endl;
    std::cout << "Track with highest pT: pt=" << maxPt << ", eta=" << maxPtTrack.eta() << ", phi=" << maxPtTrack.phi() << std::endl;
    std::cout << "Average pT: " << avgPt << std::endl;
  }

private:
  edm::InputTag tracks_;
};

TrackAnalyzer::TrackAnalyzer(const edm::ParameterSet& config)
  : tracks_(config.getParameter<edm::InputTag>("tracks"))
{}

#include "FWCore/Framework/interface/MakerMacros.h"
DEFINE_FWK_MODULE(TrackAnalyzer);
