#include <iostream>
#include <sstream>
#include <string>
#include "itkTransform.h"

using TransformType = itk::Transform<double, 3, 3>;

void parseAndSetParameters(const std::string& attributeValue, typename TransformType::Pointer transform) {
    std::istringstream iss(attributeValue);
    double param;
    for (int i = 0; i < transform->GetNumberOfParameters(); ++i) {
        if (iss >> param) {
            transform->SetParameter(i, param);
        } else {
            std::cerr << "Error: Insufficient parameters in attributeValue" << std::endl;
            break;
        }
    }
}
