import org.w3c.dom.DOMImplementation;
import org.w3c.dom.Document;
import org.w3c.dom.Element;

public class SVGRectangleGenerator {
    public String generateSVGRectangle(int x, int y, int width, int height, String fillColor, String strokeColor, int strokeWidth) {
        // Create a DOM implementation
        DOMImplementation domImpl = GenericDOMImplementation.getDOMImplementation();

        // Create an instance of Document
        Document document = domImpl.createDocument(SVG_NAMESPACE_URI, "svg", null);

        // Create a rectangle element
        Element rectangle = document.createElementNS(SVG_NAMESPACE_URI, "rect");
        rectangle.setAttribute("x", String.valueOf(x));
        rectangle.setAttribute("y", String.valueOf(y));
        rectangle.setAttribute("width", String.valueOf(width));
        rectangle.setAttribute("height", String.valueOf(height));
        rectangle.setAttribute("fill", fillColor);
        rectangle.setAttribute("stroke", strokeColor);
        rectangle.setAttribute("stroke-width", String.valueOf(strokeWidth));

        // Append the rectangle to the SVG document
        document.getDocumentElement().appendChild(rectangle);

        // Apply style attributes
        rectangle.setAttribute(SVG_STYLE_ATTRIBUTE, SVGCSSStyler.STYLE_TEXT_DECORATION + ": " + SVG_VIEW_BOX_ATTRIBUTE);

        // Serialize the SVG document to a string
        StringWriter writer = new StringWriter();
        try {
            Transformer transformer = TransformerFactory.newInstance().newTransformer();
            transformer.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION, "yes");
            transformer.transform(new DOMSource(document), new StreamResult(writer));
        } catch (Exception e) {
            e.printStackTrace();
        }

        return writer.toString();
    }
}
```

This solution creates an SVG representation of a rectangle with the specified attributes using the Apache Batik library. The `generateSVGRectangle` method constructs the SVG document, creates a rectangle element with the given attributes, appends it to the document, applies style attributes, and then serializes the document to a string for output.

