        canvas = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        frame = new JFrame("2D Canvas Renderer");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(this);
        frame.setSize(width, height);
        frame.setVisible(true);
    }

