```javascript
function calculateFinalPrice(originalPrice, serviceCenter, serviceType) {
  const discountRates = {
    "serviceCenters": {
      "center1": {
        "discountRate": 0.1
      },
      "center2": {
        "discountRate": 0.15
      }
    },
    "serviceTypes": {
      "type1": {
        "discountRate": 0.05
      },
      "type2": {
        "discountRate": 0.1
      }
    }
  };

  const centerDiscount = discountRates.serviceCenters[serviceCenter] ? discountRates.serviceCenters[serviceCenter].discountRate : 0;
  const typeDiscount = discountRates.serviceTypes[serviceType] ? discountRates.serviceTypes[serviceType].discountRate : 0;

  const finalPrice = originalPrice * (1 - centerDiscount) * (1 - typeDiscount);
  return finalPrice;
}
```

