import functools

def property_cached(func):
    cache_name = f'_{func.__name__}_cache'

    @functools.wraps(func)
    def wrapper(self):
        if not hasattr(self, cache_name):
            setattr(self, cache_name, func(self))
        return getattr(self, cache_name)

    return property(wrapper)

# Example usage:
class ExampleClass:
    @property_cached
    def expensive_property(self):
        # Expensive computation to obtain the property value
        return 42

# Subsequent accesses to `expensive_property` will return the cached value without recomputation
example_instance = ExampleClass()
print(example_instance.expensive_property)  # Computes and caches the value (42)
print(example_instance.expensive_property)  # Returns the cached value (42) without recomputation
```

