function calculateAverageRating(ratingValues) {
  const rVals = ratingValues || [];
  if (rVals.length === 0) {
    return 0;
  }

  const numericRatings = rVals.filter(val => typeof val === 'number' && !isNaN(val));
  if (numericRatings.length === 0) {
    return 0;
  }

  const sum = numericRatings.reduce((acc, val) => acc + val, 0);
  return sum / numericRatings.length;
}
