import pytest

class Ellipsoid:
    def __init__(self, a, b, c):
        self._validate_positive(a, b, c)
        self._a = a
        self._b = b
        self._c = c

    @property
    def a(self):
        return self._a

    @a.setter
    def a(self, value):
        self._validate_positive(value)
        self._a = value

    @property
    def b(self):
        return self._b

    @b.setter
    def b(self, value):
        self._validate_positive(value)
        self._b = value

    @property
    def c(self):
        return self._c

    @c.setter
    def c(self, value):
        self._validate_positive(value)
        self._c = value

    def _validate_positive(self, *values):
        for value in values:
            if value <= 0:
                raise ValueError("Semi-axis value must be positive")

# Test cases
def test_invalid_values():
    # a is invalid
    ellipsoid = Ellipsoid(1, 1, 1)
    with pytest.raises(ValueError):
        ellipsoid.a = 0
    with pytest.raises(ValueError):
        ellipsoid.b = 0
    with pytest.raises(ValueError):
        ellipsoid.c = 0
```

In this solution, the `Ellipsoid` class enforces the constraint that the semi-axes `a`, `b`, and `c` must be positive. The class includes property setters that raise a `ValueError` if an attempt is made to set a non-positive value for any of the semi-axes. The provided test case ensures that the constraints are enforced when setting the values of `a`, `b`, and `c`.

