def generate_migration_commands(fields: list) -> list:
    migration_commands = []
    for field in fields:
        field_name = field['name']
        field_attributes = field['attributes']
        field_type = field_attributes['type']
        if field_type == 'IntegerField':
            if 'primary_key' in field_attributes and field_attributes['primary_key']:
                migration_commands.append(f'ALTER TABLE table_name ADD COLUMN {field_name} INTEGER PRIMARY KEY;')
            else:
                default_value = field_attributes.get('default', 'NULL')
                migration_commands.append(f'ALTER TABLE table_name ADD COLUMN {field_name} INTEGER DEFAULT {default_value};')
        elif field_type == 'CharField':
            max_length = field_attributes['max_length']
            migration_commands.append(f'ALTER TABLE table_name ADD COLUMN {field_name} VARCHAR({max_length});')
    return migration_commands
