public:
    void performAction() override {
        // Perform PANACHE card's action
    }
};

class RuptureAction : public CardAction {
public:
    void performAction() override {
        // Perform RUPTURE card's action
    }
};
```

Then, we modify the `Card` class to use the strategy pattern:

```cpp
class Card {
public:
    CardId id;
    std::unique_ptr<CardAction> action;

    // Constructor
    Card(CardId cardId) : id(cardId) {
        // Initialize the corresponding action based on the card ID
        switch (id) {
            case CardId::PANACHE:
                action = std::make_unique<PanacheAction>();
                break;
            case CardId::RUPTURE:
                action = std::make_unique<RuptureAction>();
                break;
            // ... handle other card IDs
        }
    }

    // Method to perform the card's action
    void play() {
        action->performAction();
    }
};
```

With this implementation, adding a new card and its action is as simple as creating a new concrete strategy class and updating the `Card` constructor to initialize the corresponding action based on the new card ID. This design allows for easy extension and maintenance of the card system.

