        shutil.copy(src, dest)
        print(f"Successfully copied {src} to {dest}")
    except FileNotFoundError:
        print(f"Error: {src} not found")
    except PermissionError:
        print(f"Error: Permission denied for {dest}")

def copy_directory(src, dest):
    try:
        shutil.copytree(src, dest)
        print(f"Successfully copied {src} to {dest}")
    except FileNotFoundError:
        print(f"Error: {src} not found")
    except PermissionError:
        print(f"Error: Permission denied for {dest}")

def change_ownership(file_path, user, group):
    try:
        os.chown(file_path, user, group)
        print(f"Changed ownership of {file_path} to {user}:{group}")
    except FileNotFoundError:
        print(f"Error: {file_path} not found")
    except PermissionError:
        print(f"Error: Permission denied for {file_path}")

