func extractPackageInfo(from manifest: String) -> [String: Any]? {
    guard let packageStartIndex = manifest.range(of: "let package = Package(") else {
        return nil
    }

    guard let packageEndIndex = manifest[packageStartIndex.upperBound...].range(of: ")") else {
        return nil
    }

    let packageSubstring = manifest[packageStartIndex.upperBound..<packageEndIndex.lowerBound]

    var packageInfo: [String: Any] = [:]

    if let nameRange = packageSubstring.range(of: "name: \"") {
        let nameSubstring = packageSubstring[nameRange.upperBound...]
        if let nameEndRange = nameSubstring.range(of: "\"") {
            packageInfo["name"] = String(nameSubstring[..<nameEndRange.lowerBound])
        }
    }

    if let platformsRange = packageSubstring.range(of: "platforms: [") {
        let platformsSubstring = packageSubstring[platformsRange.upperBound...]
        if let platformsEndRange = platformsSubstring.range(of: "]") {
            let platformsContent = platformsSubstring[..<platformsEndRange.lowerBound]
            let platforms = platformsContent.components(separatedBy: ",")
                .compactMap { platform -> String? in
                    if let platformNameRange = platform.range(of: ".") {
                        return String(platform[..<platformNameRange.lowerBound])
                    }
                    return nil
                }
            packageInfo["platforms"] = platforms
        }
    }

    if let iOSVersionRange = packageSubstring.range(of: ".iOS(.v") {
        let iOSVersionSubstring = packageSubstring[iOSVersionRange.upperBound...]
        if let iOSVersionEndRange = iOSVersionSubstring.range(of: ")") {
            if let minimumiOSVersion = Int(iOSVersionSubstring[..<iOSVersionEndRange.lowerBound]) {
                packageInfo["minimumiOSVersion"] = minimumiOSVersion
            }
        }
    }

    return packageInfo
}
```

