func processFile(fileName: String, characterPosition: Int) -> (line: Int, column: Int, iOSAvailable: Bool, compilationDirective: String?) {
    // Read the content of the file
    guard let fileContent = try? String(contentsOfFile: fileName) else {
        fatalError("Failed to read the file.")
    }

    // Find the line and column numbers of the character position
    var currentLine = 1
    var currentColumn = 1
    for (index, char) in fileContent.enumerated() {
        if index == characterPosition - 1 {
            return (line: currentLine, column: currentColumn, iOSAvailable: #available(iOS 9.0, *), compilationDirective: findCompilationDirective(in: fileContent))
        }
        if char == "\n" {
            currentLine += 1
            currentColumn = 1
        } else {
            currentColumn += 1
        }
    }

    fatalError("Character position is out of range.")
}

func findCompilationDirective(in fileContent: String) -> String? {
    let directives = ["#if", "#error", "#elseif", "#warning", "#else"]
    for directive in directives {
        if fileContent.contains(directive) {
            return directive
        }
    }
    return nil
}
```

