use std::net::{UdpSocket, SocketAddr};
use std::thread;

// Define the Event enum
enum Event {
    PacketReceived(Vec<u8>),
    Error(String),
}

// Define the UdpEventDispatcher struct
struct UdpEventDispatcher {
    socket: UdpSocket,
}

impl UdpEventDispatcher {
    // Create a new instance of UdpEventDispatcher
    fn new() -> std::io::Result<Self> {
        let socket = UdpSocket::bind("0.0.0.0:8080")?;
        Ok(UdpEventDispatcher { socket })
    }

    // Bind the dispatcher to a specific UDP port for receiving events
    fn bind(&self, addr: &str) -> std::io::Result<()> {
        self.socket.bind(addr)?;
        Ok(())
    }

    // Handle and dispatch incoming UDP events to the appropriate event handlers
    fn dispatch_event(&self) -> std::io::Result<Event> {
        let mut buf = [0; 1024];
        let (size, peer) = self.socket.recv_from(&mut buf)?;
        let data = buf[..size].to_vec();
        Ok(Event::PacketReceived(data))
    }
}

fn main() {
    // Create a new instance of UdpEventDispatcher
    let dispatcher = UdpEventDispatcher::new().expect("Failed to create UdpEventDispatcher");

    // Bind the dispatcher to a specific UDP port
    dispatcher.bind("0.0.0.0:8080").expect("Failed to bind UdpEventDispatcher");

    // Spawn a new thread to handle incoming UDP events
    thread::spawn(move || {
        loop {
            match dispatcher.dispatch_event() {
                Ok(event) => {
                    match event {
                        Event::PacketReceived(data) => {
                            // Handle the received packet data
                            println!("Received packet: {:?}", data);
                        }
                        Event::Error(err) => {
                            // Handle the error event
                            eprintln!("Error: {}", err);
                        }
                    }
                }
                Err(err) => {
                    // Handle the error while dispatching event
                    eprintln!("Error while dispatching event: {}", err);
                }
            }
        }
    });

    // Keep the main thread running to continue other operations
    loop {}
}
```

