from abc import ABC, abstractmethod
from typing import List

class Logger(ABC):
    def __init__(self):
        self.logs = {}

    @abstractmethod
    def log(self, message: str, severity: str) -> None:
        pass

    @abstractmethod
    def get_logs(self, severity: str) -> List[str]:
        pass

class ConcreteLogger(Logger):
    def log(self, message: str, severity: str) -> None:
        if severity in self.logs:
            self.logs[severity].append(message)
        else:
            self.logs[severity] = [message]

    def get_logs(self, severity: str) -> List[str]:
        return self.logs.get(severity, [])
