```java
import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;

public class DependencyInjector {
    private Map<Class<?>, Object> singletonInstances = new HashMap<>();

    public void processAnnotations(Object target) {
        Class<?> targetClass = target.getClass();
        if (targetClass.isAnnotationPresent(Component.class)) {
            processComponentAnnotation(target);
        }
        processSingletonAnnotations(target);
    }

    public void inject(Object target) {
        Class<?> targetClass = target.getClass();
        for (Field field : targetClass.getDeclaredFields()) {
            if (field.isAnnotationPresent(Inject.class)) {
                Class<?> fieldType = field.getType();
                Object dependency = singletonInstances.get(fieldType);
                if (dependency != null) {
                    try {
                        field.setAccessible(true);
                        field.set(target, dependency);
                    } catch (IllegalAccessException e) {
                        e.printStackTrace();
                    }
                }
            }
        }
    }

    private void processComponentAnnotation(Object target) {
        Class<?> targetClass = target.getClass();
        for (Field field : targetClass.getDeclaredFields()) {
            if (field.isAnnotationPresent(Inject.class)) {
                processSingletonAnnotations(field.getType());
            }
        }
    }

    private void processSingletonAnnotations(Object target) {
        Class<?> targetClass = target.getClass();
        for (Field field : targetClass.getDeclaredFields()) {
            if (field.isAnnotationPresent(Singleton.class)) {
                Class<?> fieldType = field.getType();
                if (!singletonInstances.containsKey(fieldType)) {
                    try {
                        Object instance = fieldType.newInstance();
                        singletonInstances.put(fieldType, instance);
                        processAnnotations(instance);
                    } catch (InstantiationException | IllegalAccessException e) {
                        e.printStackTrace();
                    }
                }
            }
        }
    }
}
```

This `DependencyInjector` class provides the core functionality for dependency injection. It processes the `@Singleton` and `@Component` annotations, identifies singleton instances, and injects dependencies into the specified target objects. The `processAnnotations` method processes the annotations, and the `inject` method performs the actual injection of dependencies. The `processComponentAnnotation` and `processSingletonAnnotations` methods handle the processing of component and singleton annotations, respectively.

To use the `DependencyInjector`, you would create an instance of it and call its methods to process and inject dependencies into the `SampleApplication` and `MainActivity` classes.

