```python
class Node:
    def __init__(self, init_data):
        self.data = init_data
        self.next = None

    def get_item(self):
        return self.data

    def get_next(self):
        return self.next

    def set_next(self, new_next):
        self.next = new_next


class LinkedList:
    def __init__(self):
        self.head = None

    def add_node(self, item):
        # Add a new node with the given value at the beginning of the linked list
        new_node = Node(item)
        new_node.set_next(self.head)
        self.head = new_node

    def remove_node(self, item):
        # Remove the first occurrence of a node with the given value from the linked list
        current = self.head
        previous = None
        found = False
        while current and not found:
            if current.get_item() == item:
                found = True
            else:
                previous = current
                current = current.get_next()
        if found:
            if previous is None:
                self.head = current.get_next()
            else:
                previous.set_next(current.get_next())

    def __str__(self):
        node = self.head
        linked_list_str = []
        while node:
            linked_list_str.append(str(node.get_item()))
            node = node.get_next()
        return ' -> '.join(linked_list_str)
```

