class TaskManager:
    def __init__(self):
        self.tasks = []

    def add_task(self, task_description):
        self.tasks.append({"description": task_description, "completed": False})

    def remove_task(self, task_description):
        for task in self.tasks:
            if task["description"] == task_description:
                self.tasks.remove(task)
                break

    def get_tasks(self):
        return [task["description"] for task in self.tasks]

    def complete_task(self, task_description):
        for task in self.tasks:
            if task["description"] == task_description:
                task["completed"] = True
                break

    def incomplete_tasks_count(self):
        return sum(1 for task in self.tasks if not task["completed"])

    def completed_tasks_percentage(self):
        if not self.tasks:
            return 0.0
        completed_count = sum(1 for task in self.tasks if task["completed"])
        return (completed_count / len(self.tasks)) * 100
