import { SubscribeMessage, WebSocketGateway, WebSocketServer, WsResponse } from '@nestjs/websockets'
import { Server, Socket } from 'socket.io'
import { StartGameData } from 'src/dto/data/start-game.data'
import { SelectWordPayload } from 'src/dto/payload/select-word.payload'
import { Room } from 'src/models/room.model'
import { GameService } from 'src/services/game.service'
import { START_GAME, WORD_SELECT } from 'src/util/events'

@WebSocketGateway()
export class GameGateway {
    @WebSocketServer() server: Server
    private rooms: Map<string, Room> = new Map<string, Room>()

    constructor(private readonly gameService: GameService) {}

    @SubscribeMessage('startGame')
    handleStartGame(client: Socket, data: StartGameData): void {
        const room = this.getRoomForClient(client)
        if (room) {
            // Notify all clients in the room to start the game
            this.server.to(room.id).emit(START_GAME, data)
        }
    }

    @SubscribeMessage('selectWord')
    handleSelectWord(client: Socket, payload: SelectWordPayload): void {
        const room = this.getRoomForClient(client)
        if (room) {
            // Handle word selection logic and notify all clients in the room about the selected word
            this.server.to(room.id).emit(WORD_SELECT, payload)
        }
    }

    private getRoomForClient(client: Socket): Room | undefined {
        for (const [roomId, room] of this.rooms) {
            if (room.clients.has(client.id)) {
                return room
            }
        }
        return undefined
    }
}
```

In the solution, we have completed the implementation of the `GameGateway` class by adding message handling methods for "start game" and "select word" events. These methods use the WebSocket server to emit messages to all clients in the same room. Additionally, a method `getRoomForClient` is added to retrieve the room associated with a client. The `rooms` map is used to store and manage the game rooms.

