use std::fs::File;
use std::os::unix::io::FromRawFd;

#[derive(Debug)]
pub struct Undropped<T>(Option<T>);

impl<T> Undropped<T> {
    // Create a new Undropped smart pointer containing the provided object
    pub fn new(obj: T) -> Undropped<T> {
        Undropped(Some(obj))
    }

    // Consume the Undropped smart pointer and return the inner object
    pub fn into_inner(self) -> Option<T> {
        self.0
    }

    // Return a reference to the inner object
    pub fn as_ref(&self) -> Option<&T> {
        self.0.as_ref()
    }
}

fn main() {
