import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.annotation.processing.SupportedSourceVersion;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.Element;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;
import javax.lang.model.type.ExecutableType;
import javax.lang.model.type.TypeMirror;
import javax.lang.model.util.Elements;
import javax.lang.model.util.Types;
import javax.tools.Diagnostic;
import javax.tools.JavaFileObject;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Collections;
import java.util.Set;

@SupportedAnnotationTypes("your.package.FunctionInvocation")
@SupportedSourceVersion(SourceVersion.RELEASE_8)
public class AnnotationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        Elements elements = processingEnv.getElementUtils();
        Types types = processingEnv.getTypeUtils();

        for (Element element : roundEnv.getElementsAnnotatedWith(FunctionInvocation.class)) {
            if (element.getKind().isMethod()) {
                ExecutableType methodType = (ExecutableType) element.asType();
                TypeMirror returnType = methodType.getReturnType();

                String methodName = element.getSimpleName().toString();
                String generatedMethodName = "generated_" + methodName;

                try {
                    JavaFileObject fileObject = processingEnv.getFiler().createSourceFile(
                            elements.getPackageOf(element).getQualifiedName() + "." + generatedMethodName, element);
                    try (PrintWriter writer = new PrintWriter(fileObject.openWriter())) {
                        writer.println("package " + elements.getPackageOf(element).getQualifiedName() + ";");
                        writer.println("public class " + generatedMethodName + " {");
                        writer.println("    public " + returnType + " " + methodName + "() {");
                        writer.println("        return " + methodName + "(Index.DEFAULT);");
                        writer.println("    }");
                        writer.println("}");
                    }
                } catch (IOException e) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, e.getMessage(), element);
                }
            }
        }
        return true;
    }
}
