            while current:
                if current.key == key:
                    current.value = value
                    return
                if current.next is None:
                    break
                current = current.next
            current.next = ListNode(key, value)

    def get(self, key):
        index = hash(key) % self.size
        current = self.map[index]
        while current:
            if current.key == key:
                return current.value
            current = current.next
        return -1

    def remove(self, key):
        index = hash(key) % self.size
        current = self.map[index]
        prev = None
        while current:
            if current.key == key:
                if prev:
                    prev.next = current.next
                else:
                    self.map[index] = current.next
                return
            prev = current
            current = current.next
```
This `HashMap` class uses separate chaining to handle collisions and provides the required `put`, `get`, and `remove` operations for a custom hash map implementation.

