fn update_hashes(hashes: &mut HashMap<String, String>, file_name: &str) {
    if let Ok(metadata) = fs::metadata(file_name) {
        if metadata.is_file() {
            if let Ok(contents) = fs::read(file_name) {
                let hash = calculate_hash(&contents);
                hashes.insert(file_name.to_string(), hash);
            }
        }
    }
}

// Function to calculate the hash of file contents
fn calculate_hash(contents: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    let mut hasher = Sha256::new();
    hasher.update(contents);
    format!("{:x}", hasher.finalize())
}

