// Create the Lua bindings for the Vec2 struct
fn create_lua_bindings(lua: &Lua) -> Result<(), LuaError> {
    let globals = lua.globals();
    let table = lua.create_table()?;

    // Bind the len_square method to the Lua table
    table.set(
        "len_square",
        lua.create_function(|_, this: Vec2| Ok(this.len_square()))?,
    )?;

    // Expose the Vec2 table to Lua
    globals.set("Vec2", table)?;

    Ok(())
}
```

