                    self.retry_seconds = data.get("RETRY_SECONDS")
                    self.del_record_limit = data.get("DEL_RECORD_LIMIT")
                    self.max_iterations = data.get("MAX_ITERATIONS")
                    return True
                else:
                    return False
            else:
                return False
        except json.JSONDecodeError:
            return False

# Example usage
