def count_places(places: list, exact_match: bool) -> dict:
    place_counts = {}
    for place in places:
        if exact_match:
            if place in place_counts:
                place_counts[place] += 1
            else:
                place_counts[place] = 1
        else:
            found = False
            for key in place_counts:
                if place.lower() in key.lower() or key.lower() in place.lower():
                    place_counts[key] += 1
                    found = True
                    break
            if not found:
                place_counts[place] = 1
    return place_counts
```
