```java
private static int countChange(int n, int[] denominations, int x) {
    if (n < 0 || x < 0 || x >= denominations.length) return 0;
    if (n == 0) return 1;

    int count = 0;
    for (int i = x; i < denominations.length; i++) {
        if (n - denominations[i] >= 0) {
            count += countChange(n - denominations[i], denominations, i);
        }
    }
    return count;
}
```

