```rust
use serde::{Deserialize, Deserializer, de::{Visitor, Error}};
use std::fmt;

#[derive(Debug)]
struct DcName(String);

impl DcName {
    fn values() -> Vec<&'static str> {
        vec!["dc1", "dc2", "dc3"]
    }
}

impl<'de> Deserialize<'de> for DcName {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error> where
        D: Deserializer<'de> {
        struct DcNameVisitor;

        impl<'de> Visitor<'de> for DcNameVisitor {
            type Value = DcName;

            fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                let values = DcName::values()
                    .iter()
                    .fold(String::new(), |mut acc, v| {
                        acc.push_str(*v);
                        acc
                    });
                write!(formatter, "one of the following values: {}", values)
            }

            fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
            where
                E: Error,
            {
                if DcName::values().contains(&value) {
                    Ok(DcName(value.to_string()))
                } else {
                    Err(Error::invalid_value(serde::de::Unexpected::Str(value), &self))
                }
            }
        }

        deserializer.deserialize_str(DcNameVisitor)
    }
}
```

