class ShortAnswerQuestionPlugin:
    def __init__(self):
        self.questions = {}

    def add_question(self, question, case_sensitive=False):
        self.questions[question] = {'case_sensitive': case_sensitive, 'responses': {}}

    def add_correct_response(self, question, response, score):
        if question in self.questions:
            self.questions[question]['responses'][response] = score
        else:
            raise ValueError("Question not found")

    def get_correct_responses(self, question):
        if question in self.questions:
            return self.questions[question]['responses']
        else:
            raise ValueError("Question not found")

    def check_response(self, question, response):
        if question in self.questions:
            case_sensitive = self.questions[question]['case_sensitive']
            responses = self.questions[question]['responses']
            if case_sensitive:
                if response in responses:
                    return responses[response]
                else:
                    return 0
            else:
                for resp in responses:
                    if resp.lower() == response.lower():
                        return responses[resp]
                return 0
        else:
            raise ValueError("Question not found")
```

