import java.util.HashMap;
import java.util.Map;

// Custom exception for missing values
class MissingValueException extends RuntimeException {
    // Custom exception implementation
}

// Enum for lookup types
enum LookupType {
    PATH, HEADER, COOKIE, FLASH, SESSION, QUERY, FORM, MULTIPART
}

// Value class to retrieve the actual value
class Value {
    private Object actualValue;

    public Value(Object actualValue) {
        this.actualValue = actualValue;
    }

    public Object value() {
        if (actualValue == null) {
            throw new MissingValueException();
        }
        return actualValue;
    }
}

// MockContext class for context lookup
public class MockContext {
    private Map<String, Map<LookupType, Object>> contextMap;

    public MockContext() {
        this.contextMap = new HashMap<>();
    }

    public Value lookup(String key, LookupType... lookupTypes) {
        Map<LookupType, Object> values = contextMap.get(key);
        if (values == null) {
            return new Value(null); // Return value with null actual value
        }

        for (LookupType type : lookupTypes) {
            Object value = values.get(type);
            if (value != null) {
                return new Value(value);
            }
        }

        return new Value(null); // Return value with null actual value if no matching lookup type found
    }

    // Method to set values in the context map for testing
    public void setValue(String key, LookupType type, Object value) {
        contextMap.computeIfAbsent(key, k -> new HashMap<>()).put(type, value);
    }
}
```

This solution provides the implementation for the `MockContext` and `Value` classes to support the lookup and retrieval of values based on the provided lookup types. The `MockContext` class uses a map to store values for different keys and lookup types, and the `Value` class handles the retrieval of the actual value, throwing a `MissingValueException` if the value is missing.

