class DoublyLinkedList:
    class Node:
        def __init__(self, value, prev=None, next=None):
            self.value = value
            self.prev = prev
            self.next = next

    def __init__(self):
        self.head = None
        self.tail = None

    def pushFront(self, val):
        new_node = self.Node(val, None, self.head)
        if self.head:
            self.head.prev = new_node
        else:
            self.tail = new_node
        self.head = new_node

    def popFront(self):
        if not self.head:
            raise Exception("List is empty")
        value = self.head.value
        self.head = self.head.next
        if self.head:
            self.head.prev = None
        else:
            self.tail = None
        return value

    def pushBack(self, val):
        new_node = self.Node(val, self.tail, None)
        if self.tail:
            self.tail.next = new_node
        else:
            self.head = new_node
        self.tail = new_node

    def popBack(self):
        if not self.tail:
            raise Exception("List is empty")
        value = self.tail.value
        self.tail = self.tail.prev
        if self.tail:
            self.tail.next = None
        else:
            self.head = None
        return value

    def peekFront(self):
        if not self.head:
            raise Exception("List is empty")
        return self.head.value

    def peekBack(self):
        if not self.tail:
            raise Exception("List is empty")
        return self.tail.value
