        # Simulate downloading tracks from self.to_download list
        for track in self.to_download:
            print(f'Downloading {track}...')
        print('\n')

    def _remove_songs(self):
        print('Deleting removed tracks from local file system.')
        # Simulate removing tracks from self.to_remove list
        for track in self.to_remove:
            print(f'Deleting {track}...')
        print('\n')

    def synchronize(self):
        if len(self.to_remove) or len(self.to_download):
            self._remove_songs()
            self._download_songs()
            notify_message = f'Synchronization complete. Playlist contains {len(self.local_data)} tracks.\n'
