fn maximize_happiness(happiness: &[i32], cost: &[i32], budget: i32) -> i32 {
    let n = happiness.len();
    let mut dp = vec![vec![0; (budget + 1) as usize]; n + 1];

    for i in 1..=n {
        for j in 0..=budget as usize {
            if cost[i - 1] > j as i32 {
                dp[i][j] = dp[i - 1][j];
            } else {
                dp[i][j] = dp[i - 1][j].max(dp[i - 1][j - cost[i - 1] as usize] + happiness[i - 1]);
            }
        }
    }

    dp[n][budget as usize]
}

// Test
assert_eq!(maximize_happiness(&[3, 8, 2, 10], &[6, 7, 2, 5], 10), 13);
