export const useMultiStepForm = () => {
  const [formData, setFormData] = useState({});
  const [currentStep, setCurrentStep] = useState(0);
  const steps = ['step1', 'step2', 'step3']; // Replace with actual step names

  const checkMulti = (stepNames) => {
    return stepNames.every((step) => {
      // Replace with actual validation logic for each step
      return formData[step] && formData[step].isValid;
    });
  };

  const setData = (step, data) => {
    setFormData((prevData) => ({
      ...prevData,
      [step]: data,
    }));
  };

  const goToNextStep = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep((prevStep) => prevStep + 1);
    }
  };

  const goToPreviousStep = () => {
    if (currentStep > 0) {
      setCurrentStep((prevStep) => prevStep - 1);
    }
  };

  const getCurrentStepData = () => {
    return formData[steps[currentStep]] || {};
  };

  return {
    checkMulti,
    setData,
    currentStep,
    goToNextStep,
    goToPreviousStep,
    getCurrentStepData,
  };
};
