package com.xhiteam.xauth.impl.jwt;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;

import java.security.Key;
import java.util.Date;

public class JwtTokenUtil {
    private static final Key SECRET_KEY = Keys.secretKeyFor(SignatureAlgorithm.HS256);
    private static final long EXPIRATION_TIME = 86400000; // 1 day in milliseconds

    public static String generateToken(String userId, String role) {
        Date now = new Date();
        Date expiration = new Date(now.getTime() + EXPIRATION_TIME);

        return Jwts.builder()
                .setSubject(userId)
                .claim("role", role)
                .setIssuedAt(now)
                .setExpiration(expiration)
                .signWith(SECRET_KEY, SignatureAlgorithm.HS256)
                .compact();
    }

    public static String[] validateToken(String token) {
        Claims claims = Jwts.parserBuilder()
                .setSigningKey(SECRET_KEY)
                .build()
                .parseClaimsJws(token)
                .getBody();

        String userId = claims.getSubject();
        String role = (String) claims.get("role");

        return new String[]{userId, role};
    }
}
```

In this solution, the `JwtTokenUtil` class provides methods to generate and validate JWT tokens using the `com.xhiteam.xauth.impl.jwt` package. The `generateToken` method creates a JWT token containing the user's ID and role, signed using a secure secret key. The `validateToken` method validates the token's signature and extracts the user's ID and role from the token. The implementation uses the `io.jsonwebtoken` library for working with JWT tokens and ensures that the generated tokens meet the specified requirements.

