class Hangman:
    def __init__(self, word):
        self.word = word
        self.guessed_letters = set()
        self.body_parts = {}

    def guess(self, letter):
        self.guessed_letters.add(letter)
        if letter in self.word:
            return True
        else:
            self.body_parts[letter] = True
            return False

    def get_status(self):
        revealed_word = ''.join([letter if letter in self.guessed_letters else '_' for letter in self.word])
        if all(letter in self.guessed_letters for letter in self.word):
            return "You win!"
        elif len(self.body_parts) >= 6:
            return f"{revealed_word}, You lose!"
        else:
            hangman_parts = ''.join(self.body_parts.keys())
            return f"{revealed_word}, {hangman_parts}"
```

