    var foregroundHandlers: [() -> Void] = []

    func registerHandler(eventType: String, handler: @escaping () -> Void) {
        switch eventType {
        case "background":
            backgroundHandlers.append(handler)
        case "foreground":
            foregroundHandlers.append(handler)
        default:
            break
        }
