class StateTransitionSystem:
    def __init__(self, initial_state):
        self.current_state = initial_state
        self.transitions = {}

    def add_event_transition(self, event, from_state, to_state):
        if event not in self.transitions:
            self.transitions[event] = {}
        self.transitions[event][from_state] = to_state

    def trigger_event(self, event):
        if event in self.transitions:
            if self.current_state in self.transitions[event]:
                self.current_state = self.transitions[event][self.current_state]
                return True
        return False

# Example usage
