def simulate_lock_movement(lock_map, commands):
    final_positions = dict(lock_map)  # Create a copy of the initial lock_map

    for command in commands:
        lock_number, direction, steps = command[:-2], command[-2], int(command[-1])
        current_position, max_position = final_positions[lock_number]

        if direction == '+':
            final_positions[lock_number] = (min(current_position + steps, max_position), max_position)
        elif direction == '-':
            final_positions[lock_number] = (max(current_position - steps, 0), max_position)

    return final_positions
