data = {
    'a': 1,
    'b': {
        'c': 2,
        'd': {
            'e': 3
        }
    }
}

def add_prefix(key):
    return f'prefix_{key}'

result = apply_fun_to_keys(data, add_prefix)
print(result)
# Output:
# {
#     'prefix_a': 1,
